// The gallery's block texts in Japanese (spec 2026-10-23 languages-b §9): display name, description and notes of every id HANDLES points at.
// Block ids, parameter names, cut.ts code and English technical terms stay as they are. blocks.test.ts checks every id has one.
import type { BlockText } from './blocks.ts';

export const BLOCKS_JA: Record<string, BlockText> = {
  'core.flash': { label: 'フラッシュ', doc: '画面全体を一瞬ある色（既定は白）で光らせる。撮り直し、場面転換、カメラのシャッターを切った瞬間の閃光に。fade out はエンディングのフェードアウト：項目の長さいっぱいをかけて色がだんだん画面を覆う（color を #000 にすると黒へフェード）、fade in は冒頭に色からフェードイン。keys「秒:不透明度」でキーフレームどおりに変化（黒へのフェード、白からのフェード、2 回の点滅）。mode で光の形を選ぶ。blend で合成モードを変える（screen は明るくするだけ）。' },
  'core.title': { label: 'タイトル', doc: '旧タイトルブロック。古いプロジェクトを開くためだけに残しています。新しい動画はタイトル（common.heading）とそのテンプレートを使います。' },
  'core.caption': { label: '字幕', doc: '旧字幕ブロック。古いプロジェクトを開くためだけに残しています。新しい動画は共通の字幕（common.caption）とそのテンプレートを使います。' },
  'core.lowerThird': { label: 'ロワーサード', doc: '左下に、メインの見出しとサブ見出しを色バー付きで表示する。場所、人名、時刻に。' },
  'core.endCard': { label: 'エンドカード', doc: '終わりに複数行のテキストを1行ずつ表示する（1行が1項目）。謝辞、スタッフ、日付に。' },
  'common.backdrop': { label: '背景パターン', doc: '映像全体の柄の背景で、動画の下に置く。動画がパネルに縮んだときに見える地で、色は theme に従う。glow は下から光がにじみ、強さは「秒:強さ」で変わる（スコアや気分に合わせてだんだん熱くなる）。bits は両側に小さな紙吹雪（丸、四芒星、ギザギザ線、小さなバツ、テーマの色、きらめく）をいくつか散らし、どのパターンにも使える。' },
  'common.ambient': { label: 'グラデーション雰囲気背景', doc: '映像全体の背景色が「度合い」に応じて色の並びに沿って変わる（潜るほど深く、遅くなるほど暗く、冷えるほど青く）。漂う微粒子と消えていく光線つき。動画の下に置き、数値は common.meter と共有する。look sky は一日の空：値が空の様子（0 夜明け、1 嵐、2 晴れ間、3 ゴールデンアワー、4 夕暮れ、5 夜）になり、流れる雲、嵐の細い雨、晴れ間の日差し、夕暮れの電球の光、夜の星、flash の時刻に稲妻（誕生日、結婚式、一日の vlog の天気の移り変わりに。雷は common.thunder）。' },
  'common.shader': { label: '動く背景（GPU）', doc: '映像全体に流れる質感のある背景を GPU でリアルタイム描画する。色は既定で theme を使い、動画の下に置く（冒頭、エンドカード、素材のない区間、パネルの背景）。' },
  'common.panel': { label: '動画パネルの枠', doc: '長方形に縮めた動画の外側の枠。x,y,w,h は動画の frame と、radius は動画の角丸と同じにし、動画トラックの上に置く。' },
  'common.badge': { label: '番号バッジ', doc: 'バッジの中に番号（No.1、02）を入れ、横に店名やタイトルのプレート（plate）を添えられる。ランキング、リスト、区間紹介（何軒目、何番目のコツ）に。' },
  'common.tag': { label: 'カプセルタグ', doc: '小さなタグ。tags はカンマ区切りで、1つずつ現れる。タイトル下の要点、場所、日付、店名のような短い字に。' },
  'common.burst': { label: '爆発カード', doc: '大きな1語が弾け出るカード。【語】 は強調色になる。後ろに common.speedlines を足せる。' },
  'common.speedlines': { label: 'スピード線', doc: 'マンガのスピード線。爆発カードの後ろや、驚き、ダッシュ、転換の瞬間に。look で見た目を変える：一点から放射、四辺から中心へ向かう集中線、画面全体を飛ぶ平行線。' },
  'common.caption': { label: '字幕（共通）', doc: 'スタイル（style）、単語の効果（wordFx）、入場、退場、色、フォントを自由に組み合わせる字幕。よく使う組み合わせは名前付きの字幕テンプレート（npm run tellcut -- catalog CAP で一覧。template に id、作品全体は c.captionTemplate）。words は話し言葉の単語ごとの時間（speechCaptions の karaoke が付ける）で、ないときは単語の効果を長さに均等に割り振る。【語】はハイライト、{語} は記号で伏せ字。name と speaker で話者を示す（speaker 1＝テーマの accent2、2＝ハイライト色、3＝メインカラー。tint を切ると名前の札だけ色が変わる。role は名前の横の小さな肩書き）。point は名前を左の札に入れて話者へ矢印。gloss は下の一回り小さい訳、tag は上のメインカラーの札、y は下端を任意の高さに。big は手書き、qa は明朝、neon は丸ゴシックが既定で、styleFont か項目自身の font で置き換わる。ショート動画の下端と左右の安全領域を避ける。' },
  'common.slam': { label: 'どーん文字', doc: '超特大の1行が画面に「叩きつけ」られる（拡大して弾み、少し揺れ、傾く）。【語】 は強調色になる（hlScale で拡大）。stagger は行ごとに順に叩きつける。上下に小さな1行（kicker／after）を添えられる。enter: press は大から縮んで印泥がにじむよう、chars は1文字ずつ跳ね上がる。bar は文字の下に強調色の帯が広がり、drift は落ち着いたあと非常にゆっくり拡大する（拍に合わせたカード）。kickerBg は上の小さな字を色のブロックに入れて左から滑り込ませ、shade は文字の後ろを暗くする。動画の要点、驚き、フック、結論に。' },
  'common.censor': { label: '伏せ字ステッカー', doc: '口に貼る伏せ字ステッカー（弾んで入り、左右に揺れる）。言ってはいけない言葉のときに使い、common.beep のピー音と組み合わせる。位置はアイテムの transform で動かす。' },
  'common.stamp': { label: 'スタンプ', doc: 'スタンプやカードが画面に「押される」。検証済み、要点、おすすめ、完成、NG のような判定に。common.thud と組み合わせる。head は大きな文字の上に字間を広げた小さな1行を添える（判決、VERDICT。box、circle、double、ember で使える）。' },
  'common.pen': { label: '手描きマーク', doc: 'ペンで描いたようなマークが、描きながら現れる。x、y、w、h の枠の中に描き、kind で何を描くかを選ぶ。style でペンを変える：smooth はきれいな線（既定）、ballpoint ボールペン、marker マーカー、crayon クレヨン（塗りは斜線で紙の質感つき）、pencil 鉛筆。boil は線が毎秒何度かゆれ直す（手描きアニメの感じ）。画面の要点、商品、ディテールを指すのに。絵本、ノート、解説向き。' },
  'common.sparkle': { label: 'きらきら星', doc: 'きらめきの印：四角い星がはじけたり瞬いたり、色とりどりの紙が降ったり、十字の光がきらっと光ったり。お祝い、サプライズ、強調、高級感に。' },
  'common.emoji': { label: '絵文字スタンプ', doc: '大きな絵文字（char）：ステッカー、雨、上へ流れるリアクション、ダブルタップのハート、または顔隠し。感情、笑いどころ、お祝い、食いしん坊感、いいねに。float と tap の ♥ はピンクのハートとして描く。' },
  'common.header': { label: '章ラベル', doc: '章ラベル：解説、リスト、区間紹介で今どこを話しているかを示す。shade は画面上端に暗いグラデーションを敷き（高さ shadeH）、明るい映像でも小さな字が読める。' },
  'common.glitch': { label: 'グリッチ', doc: 'デジタルのノイズが断続的に走る（いつ走るかは乱数シードで決まる）。場面転換、ドッキリ、テック感、「何か起きた」瞬間に。shift はずれの量。rgb、block と scan の跳びは Chromium 系ブラウザ（Chrome、Edge）のプレビューでのみ見える。書き出しは常に Chrome を使う。' },
  'common.progress': { label: '進行バー', doc: '動画がどこまで進んだかを示す進行バーや章の印。フック短編、解説、レシピ、旅日記でよく使う。runner、stretch、paws、segments、fuse、battery、rocket、ring、vine、stamps の 10 種は進み方が同じ：step -1 は動画とともに最後まで進み、項目が終わる最大 1 秒前にゴールして到着の動きを見せる。step 0 以上は今の章で、この項目のあいだに章の始めから終わりまで進む。1 章に 1 項目、dots は章の総数。paws と segments は薄いので上端に置ける。runner、stretch、fuse、battery、vine は背が高いので下端に置く（position bottom）。上端に置くときは common.header の y を下げて場所を空ける。' },
  'common.meter': { label: '数値メーター', doc: '大きな数字が時間とともに各値へ跳ねていく（深さ、標高、温度、回数、順位…）。「どんどん…になる」が軸の動画で進み具合を見せる。stops の3つ目に数字を書くとその区間だけの跳ねる時間になる（ambient と共通）。' },
  'common.scoreboard': { label: 'スコアチケット', doc: '上部のチケットカード：見出し行と数マス（アイコン、名称、数値）で、区間ごとに1つの状態を置く。変わったマスが弾み、小さな注釈も付けられる。戦績、釣果、収集の進み、採点カード（味 ★★★★）に。' },
  'common.receipt': { label: 'レシート', doc: '感熱紙のレシート：各行「秒|アイコン|名称|金額|色調」が時間になると印字される（紙は下へ伸び、古い行は上へ送られる）。最後に合計が印字される（【語】 は赤）。色調 bar は黒地に白抜きの店名帯。出費、旅の家計簿、開封、「払ったもの vs 得たもの」に。' },
  'common.tripclock': { label: '旅の時計', doc: '画面上部の現地時刻（撮影時刻に合わせて進む）、到着してからの経過、そして一駅ずつ点灯していく道のり。旅行、日帰りの行程、時間に沿って進む動画に。' },
  'common.route': { label: '手描きルートマップ', doc: 'ベージュの紙カードの手描きルートマップ：上に大きな数字の約束の列（数字|説明）、下に鉛筆の通り、出発点（大きな時計や絵文字）から赤い点線が一駅ずつ点灯していき、最後の数駅にはてなを付けられる。upto で k 駅目までだけ描き、already で最初からその駅まで点灯済みにできる（already k−1＋upto k＝カードが1拍戻って次の駅を点灯）、nameSize で駅名の大きさ。お店巡り、日帰り旅、街歩きルート、シリーズ予告に。look page は画面全体のノートのルートマップ：場所は輪のように並び（pts で位置指定も可）、鉛筆で全体の道を薄く下書きし、青いボールペンの点線が区間ごとに描かれ（ペン先が付いていく）、各区間の横に赤ペンで徒歩時間（legs）と波線、着くと落書き（icons：bowl／bun／box／jar／tofu／cup／station／train／house／star または絵文字）と赤いチェックになり、名前が手書きで蛍光ペン付きで書かれる。カメラは cams「秒|モード」で full 全体、walk 地図を上に（下は映像用）、stop 隅の小さな紙切れに縮む（今の場所が点滅）、end、near 今の場所に寄って追う、の間を動く。loop で出発点に戻る道、flash で全部のチェックが順に跳ねる。common.paper look grid の上に置く。' },
  'common.card': { label: 'インデックスカード', doc: '重ねたインデックスカードの一番上の1枚：上半分は絵の窓（任意のブロック、例えばプロジェクト独自のイラスト fx や大きな絵文字を入れられる）、下半分の罫線にはステップ番号、タイトル、分量（蛍光ペン）、小さなヒント。ステップごとにめくり、配るように登場し、最後に滑り出せる。レシピ、解説のステップ、リストに。' },
  'common.countdown': { label: 'カウントダウン', doc: '大きな数字が from から to までカウントダウンする（アイテム全体を等分）。最後の一拍は文字（GO!）に変えられる。クイズ、チャレンジ、当てっこ、ランキング発表に。' },
  'common.list': { label: 'リストカード', doc: '見出しと数行の項目を持つカードで、1行ずつ現れる。style で各行の頭の記号を変える。レビュー、解説、3つの要点、誤解を解く動画に。look: stack はカードなしで、大きな字が1拍1行で叩きつけられ、番号の色ブロック、最新の行は蛍光色（写真の連打では各写真の名前を残す）。' },
  'common.rating': { label: '評価カード', doc: '評価カード：数行の「項目:点数」（星は半分も可、または棒）で、点数が1行ずつ伸びていき、合計を大きな字で添えられる。グルメ、開封、映画やドラマのレビューに。' },
  'common.info': { label: '情報カード', doc: 'theme を使った情報カード：見出し行と数行の「アイコン 文字」（📍住所、🕐営業時間、💰価格、🚇交通…）が、下のセーフゾーンから上へ滑り出る（または上から）。旅行、グルメ、コーデ、お店紹介に。' },
  'common.polaroid': { label: 'ポラロイド静止', doc: '素材のある瞬間をポラロイドとして静止させる：まず白く光り、写真が斜めに落ちてきて、下に手書きの1行が入る。crop { x, y, zoom }（ほかの写真カードやショット行と同じく「x,y,zoom」とも書ける）でクリップの crop と同じように正方形の写真の中を切り取る（焼き込み文字を外す、顔に合わせる）。下の1行は既定でテーマの見出しフォントで手書きではない。手書きにするなら font（例えば LXGW WenKai TC）。ハイライト、旅行、ベストショットに（c.polaroid は再生中のクリップから source と時刻を自動で取り、シャッター音も付く。crop は取らないので自分で指定する）。' },
  'common.mystery': { label: 'はてなサスペンス', doc: 'サスペンスの表紙：画面の周りが暗くなり、中央のメインカラーの大きな丸印の中ではてなが回りながら弾んで入り、上に一言（5軒目は…）、下にヒントを添えられ、斜めに貼った2本のマスキングテープの文字がゆっくり流れる。予告で答えを引っ張り、答えは本編に残す。' },
  'common.outro': { label: 'エンド誘導', doc: 'エンドカード。look で誘導カード（cta）、お礼のクレジット（credits）、番組のエンドカード（episode）を選ぶ。大きな字はどれも lines に 1 行ずつ書き、cta と credits では 1 拍に 1 行ずつ出る（beat は 1 拍の秒数）。' },
  'common.film': { label: 'フィルム質感', doc: '画面全体にかけるフィルム質感（1つのブロック）。粒子は毎フレーム変わり、映像に合成される（暗部と中間調でいちばん見え、真っ黒と白飛びには出ない）。フィルム、ノスタルジー、質感がほしいときに最上層へ重ねる。grain 0.07〜0.15 で控えめなフィルム感、0.3 以上は粗い。blend overlay はコントラストが強く中間調に集まる（ブランド映像、映画風、grain 0.07 前後）。' },
  'common.tone': { label: '色調', doc: '映像全体の色調補正：ソフトライト（soft-light）を動画に重ね、中央に色の光、周りを暗くする。既定は暖色（屋台、夕焼け、ノスタルジー）、青にすれば寒色。amount を 1 より上げるとソフトライトをもう一層重ね（最大 3）、色調がひと目でわかる。common.film とよく併用する。' },
  'common.paper': { label: '紙の机', doc: '映像全体の紙の地。静止画で、動画の下に置く。手帳、レシピ、手書き解説、絵本、ノートに。common.notecard と組み合わせる（card: false ならこのカードに書く）。' },
  'common.notecard': { label: '手書きインデックスカード', doc: '罫線のインデックスカードに、内容が手書きで一筆ずつ書かれる。mode でページを変える。レシピ、解説、手帳風。card を切ると common.paper が描いたカードに書く。' },
  'common.handwrite': { label: '手書き文字', doc: '手書き文字が一筆ずつ書かれ、文ごとに自分のタイミングを持つ：「秒-秒|文」でナレーションの時間に合わせて1文字ずつ書かれる手書き字幕（replace：一度に1文。終了秒のある文は終了秒から hold 秒（既定 1.2）でフェードアウトし、次の文が先に来ればそこで替わる）、手紙のように1行ずつ積み上がる（stack）、または写真に貼った小さなメモ（paper: note、小さな字を1行添える）。look でペンを選ぶ（万年筆、チョーク、蛍光ペン、クレヨン）。red に挙げた要点の語は赤ペンで書かれ、書き終えると下に下線が引かれる。ポストカード、日記、手帳、レシピに。' },
  'common.gauge': { label: 'ゲージメーター', doc: '半円のスピードメーター：色ゾーン（開始:名称）が目盛り帯に沿い、バネ式の針、LED の数字表示と今のゾーン名、光輪がだんだん悪魔の角に変わる。hits「秒:加点」ごとに針が弾む。冒頭で乱れ跳ね、起動時に一度スキャンし、警告の赤ランプ、最後に振り切れる（針が端に当たり、ガラスが割れる）こともできる。readout で LED に数字ではなく文字を出せる（No.1 のような順位、1語。カンマ区切りなら加点ごとに次へ、{v}＝今の点数）。既定の look: neutral は中立のゲージ（色だけのゾーン、光輪・警報・振り切りなし。自分で指定した zones、halo、danger、boom はそのままで、zones を指定すればゾーン名も出る）。「罪悪指数」の見た目（清白…地獄級のゾーン、光輪、警報、振り切り）は look: guilt、その中で外したいものは zones を指定して halo: false、danger: -1、boom: -1。罪悪感指数、辛さ、ときめき指数、熱量、点数、順位に。' },
  'common.hangtag': { label: '加点タグ', doc: '証拠品タグ風のスタンプが画面に斜めに押される：大きな「＋点数」、名称、原文の小さな字、一言のツッコミ。続いて「＋点数」が指定の点（例えば common.gauge）へ飛び、そこで輪になって弾ける。採点、価格、カロリー、罪状、収集に。' },
  'common.strike': { label: '取り消して書き直し', doc: 'まず柔らかい細い字の1行（上に小見出し1行）が浮かび、at 秒に accent の色で取り消され（消し方は look で選ぶ）、その下に accent 地の大きな字のスタンプが押される。「本当は A ではなく B」、期待と現実、誤解を解く、どんでん返しに。' },
  'common.timelapse': { label: '早送り時計', doc: '時間の早送り：画面が暗くなり、時計の針が猛烈に回り、下の時間が上がり続け（「冷蔵 2.3 時間」）、上で「▶▶ 早送り」が点滅する。冷蔵、焼き上げ、発酵、待ち時間、一晩が過ぎるジャンプカットに。' },
  'common.routeboard': { label: 'ルート看板', doc: '上部の暗いルート看板：本物の緯度経度のミニマップ（都市の点、歩いた線が明るくなる）、今の駅が点滅し、駅数 01/03 がめくれ、日付が出る。stops「秒|都市|日付」で各時点でどの駅を点灯させるかを決める（- は移動中、all は全部）。複数都市の旅の早回しで全体に掲げる。同じ街の数か所（全部が半度以内）は自動で地図いっぱいに広げる。' },
  'common.mapjump': { label: '全画面ルートジャンプ', doc: '画面全体がベージュの紙のルートマップ（本物の緯度経度、経緯線と度数）になる1〜2拍：leg は前の駅から次の駅へ赤い弧を描き、点が拍で着地する。all はルート全体を描き、各駅に順にスタンプが押される。上に大見出し、下に日付。旅の早回しで都市が変わるとき、全行程の振り返りに。' },
  'common.ticket': { label: '到着チケット', doc: '下にクリーム色のチケットが叩きつけられる（赤いチケットヘッド＋No.01/03、大きな都市名、ラテン文字、右の日付の半券、ミシン目）。stampAt 秒に赤い二重丸の「到着」スタンプが押される。旅の早回しで各駅に着いたとき、行程、チケット、搭乗に。' },
  'common.snap': { label: '写真フラッシュイン', doc: '写真が入ってくると白い光がひらめき、白い写真の枠が画面の外から収まり、隅にオレンジに光るカメラの日付スタンプ（\'22 5 26）が出る。既定は画面全体を囲み、window [x, y, w, h]（画面比。クリップの frame と同じ。例えば 4:5 の写真窓）でその窓の外側を囲み、日付スタンプも窓の隅に入る。写真の連打、思い出、フィルムカメラ感に。' },
  'common.stations': { label: '駅スタンプの締め', doc: '締めの最後の一拍：画面の下側が暗くなり、赤い線が各駅のスタンプ（番号つきの赤い丸印、駅名の大きな字、ラテン文字）をつなぎ、一緒に押され、日付が浮かぶ。旅の早回し、シリーズの振り返り、行程のまとめに。' },
  'common.postcard': { label: 'ポストカード', doc: 'ポストカード旅日記の一駅：木の机の上のポストカードの束に、新しい1枚が滑り込み（または裏返って）重なり、隅に切手（その駅の画面）、消印（地名＋日付）が押され、ナレーションが1文字ずつカードに手書きされる。カードが落ち着くと写真窓は透明な穴になり、メイントラックのクリップ（frame＝postcardWindow）がそこから再生される。カードが動いている間、窓の中は静止画（そのときカードはクリップの上）。最後の1枚は裏返して文字を書き、全部を広げられ、drop で展開の後に最後のカードを落とせる。pushAt から写真窓がクリップごと全画面に広がり、pushBack からカードに戻る（広がる・戻る間はメイントラックに frame＝postcardWindow のクリップ、全画面の間は全画面のクリップを置くと字幕が上に出る）。簡単なパラメータなら1枚、card／pile／spread で一式。' },
  'common.postmark': { label: '消印', doc: '消印が画面に「押される」：二重の円、上の弧に地名、下の弧に現地語の地名、中央に日付、右に5本の波線、ムラのあるインク。ミシン目つきの切手（絵は素材のある瞬間の画面で、なければ描かれた夕焼けの海）を添えられる。旅行、手紙、「来たよ」、日付スタンプに。' },
  'common.frame': { label: '実物フレーム', doc: '動く実物のフレームの中で動画が再生される：ポラロイド、木の額縁、古いテレビ、カードが、落ちてきたり滑り込んだりし、裏返して文字を書けて、退場もできる。動いている間、窓の中は素材の静止画で、落ち着くと窓が穴になり、メイントラックのクリップ（frame＝frameWindow(パラメータ)）が穴から再生される。思い出、作品紹介、古いテレビでの再生、額縁の中の人に。' },
  'common.dotmatrix': { label: 'ドット文字', doc: 'ドット文字：任意の文字（漢字も可）を小さなドットに変換し、ドットを1つずつ描き戻す。look led は黒地の電光掲示（点灯したドットが光り、消えたドットは格子）、print は感熱紙のインクの点。看板、電光掲示、LED ボード、レシート、呼び出し機に。' },
  'common.digits': { label: '数字ディスプレイ', doc: '数字ディスプレイ：style vfd はレジの緑のドット小計（「秒|+40」で数字が跳ね上がり、黄色の「+40」が光り、合計で点滅）、led は赤い7セグメントの呼び出し（「秒|02」で番号が替わると3回点滅し、横に縦書きの小札 呼び出し中／次の方）。title を足すと看板になる（左に店名と小さな字、右にディスプレイ）。出費、採点、呼び出し、カウントダウン、階数に。' },
  'common.printer': { label: 'レシートプリンター', doc: '感熱レシートプリンター（画面の下部）：各行「秒|スタイル|文字|金額」がドット文字で印字され、ステッピングモーターが紙をカクカクと送り、紙は上へ伸びて clip（動画窓）より上の後ろへ潜り込む。shop は黒地に白抜きの店名帯で、印字ヘッドにすり減った筋が出る。本体の VFD 小計は自動で跳ね上がり「+40」が光る。最後にスタンプが押され、赤ペンで1行が消され、tearAt でレシート全体がちぎれて画面中央に広がる。グルメの家計簿、食べながら計算、買い物リストに。本物の POS プリンターの見た目：感熱紙の紙目、わずかな反り、ギザギザの切り口と影、つや消しの本体、金属のカッター、スモークガラス越しの VFD。surface counter は clip（動画窓の下端）より下にライトの当たったカウンターを敷き、映像に自前の背景があれば none。' },
  'common.rolldoor': { label: 'シャッター', doc: 'シャッター：鋼板が上から1枚ずつ下りてきて枠（たいてい動画窓）を覆い、下まで下りると紙の札（本日終了）が貼られて弾む。dir up は最初閉まっていて、時間になると上へ巻き上がる。閉店、終わり、締め、次回に続くに。common.rattle の効果音と組み合わせる。' },
  'common.callout': { label: '丸囲み注釈', doc: '画面の中のものに印を付け、注釈線をラベルまで引く。印が先に描かれ、線が伸び、ラベルが弾んで出て、ラベルは自動でセーフゾーンに収まる。食材、作り方のような要点を指すのに。' },
  'common.slip': { label: '整理券', doc: '生成り色の整理券：mode stub は左に赤い番号の半券（理由 01）＋点線の切り取り口、右に見出しと小さな字で、左から印字されていく（何番目の理由、一言の要点）。mode board はエンドの整理券：大きな字、点線、1行ずつ弾んで入る番号付きの振り返り（items）、一番下に小さな字1行、背後は暗くなる。行列の名店、3つの理由、振り返りのまとめに。slot を指定すると、最後の 0.55 秒で半券が縮んで common.progress の slots の列のその枠へ飛び込む（slots と slotY はその項目と同じにする）：言い終えたルールを番号カードにしまう。' },
  'common.quote': { label: '名言カード', doc: "名言カード：名言（text、1行ずつ）、話者（who）と小さな文字1行（kicker）。一番強い行（hit、既定は最後の行）はメインカラー（accent）。mode で出し方を選ぶ。ポッドキャスト、インタビュー、講演、告白の名言に。" },
  'common.wipe': {"label":"斜め色帯トランジション","doc":"トランジション。mode で 9 種類の見た目を選ぶ。切り替え点（レイアウトの切り替え、場面転換）はアイテムのちょうど真ん中に置き、最上層（layer: top）に置く。common.whoosh と組み合わせる。band と stripes の傾きは slant（上下の端が画面幅いくつ分ずれるか。角度は画面比で変わる：1 で 9:16 は約 30 度、1:1 は 45 度、16:9 は約 60 度）。iris、blinds、ink は dir を使わない。"},
  'common.duo': { label: '二人分割対談', doc: '二人用の分割画面の枠（上下は dir v、左右は h）：冒頭に色ブロックの小札＋題、2枠の間（左右のときは下）に字幕帯、各枠の隅に名札。segs「開始-終了|a／b／ab」で誰が話しているかを示す：話している枠が点灯し（話者色の縁取り＋内側の光、名札が塗られ、音量バーが跳ねる）、もう一方の枠は灰色になって暗くなる。二人のクリップの frame は duoWindow(\'a\'|\'b\', 同じパラメータ) で2枠に入れる（a は c.clip、同じ瞬間の b は c.beside(a の id, { frame: duoWindow(\'b\', 同じパラメータ), crop })：一つの二人ショットを二人に切り分けるか、別のカメラ）。長い題はまず縮み、次に 2 行になり、切れることはない。size でヘッダーと名札の文字をまとめて拡大縮小。二人のインタビュー、ポッドキャスト、討論、彼が言う彼女が言うに。common.versus と caption の point と組み合わせる。mode solo は一度に一人だけ映るポッドキャストの切り抜き：縦長の角丸ウィンドウの縁が、話している人の色に光り（segs で決まる）、外側は暗い地に二人の色のもや、ウィンドウの下端に字幕用の影（dim）、各人が初めて話すときウィンドウ左上に名札（最長 2.6 秒、その発言が終わる前に消える）。クリップの frame は duoWindow(\'a\', 同じパラメータ)。' },
  'common.versus': { label: '対決カード', doc: '二者対決のカード（common.duo と組み合わせる）。mode で動画のどの部分に使うかを変える。二人のインタビュー、討論、2つのやり方の比較に。' },
  'common.chart': { label: 'データチャート', doc: 'データチャートカード。kind でグラフを変える。data は1行1件「名称|数値|表示する字」、hl はどの件を点灯させるか（max、min または何番目）、mark circle はそれを丸で囲み、title は見出し、source は出典、時間 at はアイテムの開始からの相対。look clean はシンプル（theme の色）、hand は手描き（pen は marker マーカー／crayon クレヨン／pencil 鉛筆／ballpoint ボールペン、boil でゆれ）、woodcut は羊皮紙に木版のハッチング。データ、統計、比較、ランキング、割合、推移に。' },
  'common.touch': { label: 'タッチ表示', doc: '画面録画の「タッチを表示」の点：touches は 1 行に 1 つのジェスチャー。「秒|tap|x,y」タップ、「秒-秒|drag|x,y>x,y」ドラッグ（点はいくつでも）、「秒-秒|pinch|x,y|0.4>0.15」2 本指のピンチ（距離は短辺基準、大きくなればズームイン）、「秒-秒|press|x,y」長押し。位置は画面比率。指が触れた所に波紋が広がる（ripple）。すべてのアイテムの一番上に描く。スマホ操作、アプリの使い方、アルバム、チャット、検索の画面録画に。' },
  'common.headline': { label: '明朝体カード（取り消し線、名前タイトル）', doc: 'タイトル（動画名、章、地名）には common.heading を（テンプレート doc-rules が上下の細線の明朝体カードで、ほかの見た目、レイアウト、下地、入り方もそちらにあり、動画のタイトルテンプレートに従う）；headline は heading にないことに：文字の取り消し（strikeFrom／strikeAt）、roll の入り方、look name の名前タイトル。最後のお礼のクレジットは common.outro の look credits。' },
  'common.mapcam': { label: "地図カメラ", doc: "assets map で取得した地図写真をパン・ズームできるカメラにする（source は地図の素材 id。経緯度と zoom は素材に記録済み、古い地図は at＋zoom で補う）：cam キーフレーム「秒|地点|zoom」（空＝ゆっくり寄る）、layers で同じ場所の別 zoom の地図を重ねる（画面を覆うと自動でフェードイン、宇宙から街まで）、routes ルートを区間ごとに描く（先頭は矢印・点・絵文字）、pins ピンが落ちて地名、rings 円、areas エリアを囲む、labels 海の名前と注記、titles 大見出し、cta 締めの大きなピン；open／close で隅の小さな丸い地図から開く・戻す、mode mini はその隅の地図（横に何番目の地点か）；地名はすべて places（名前|ラテン文字|経度|緯度）；地図写真がないときは世界の海岸線で代用。地球儀から国までは common.worldmap、その先は mapcam へ（zoom ≈ log2(2π·cos緯度·10^log10R／256)）。" },
  'common.worldmap': { label: "地球儀マップ", doc: "手描き風の世界地図：カメラのキーフレーム「秒|地点|log10 半径|回転」で宇宙に浮かぶ地球儀（球体、光、経緯線）から国まで寄り、寄ると地球儀が平面の海図（海岸にさざ波）に変わる；pins ピンと地名カード、routes 航路の弧（arc）または地点に沿った線（line）、先頭に絵文字（✈️ 🛵 ⛵）、regions 自分で指定した多角形や四角の範囲を強調色で塗る（陸地のみ。国境データはないので形は指定した点で、本物の国境ではない）、labels 海と陸の名前、titles 大見出し；iris で一点から円形に開く、card で傾いた小さな地図カードに。海岸線は Natural Earth 1:110m（国まで）、それより寄るなら地図写真の common.mapcam へ。オープニングの位置、国をまたぐ旅、航路。" },
  'common.notify': { label: "通知スタック", doc: "スマホの通知スタック：items は 1 行に 1 件「秒(-消える秒)|アイコン|アプリ|タイトル|本文|key=値…」。時間が来ると押し込まれ（新しいものが一番上、古いものは下へ押される。grow up はチャット風で新しいものが一番下）、full 件を超えたカードは最後の 1 枚の下に重なり、「秒-秒」は 2 つ目の時間で右へスワイプして消える。本文は / で改行、【語】はハイライト。sub= 第二言語の小さな字、when= 時刻、tone= plain／light／dark／accent（accent は theme の紙色の大きな丸ゴシックのカード）、lock はプレビュー非表示（本文が薄くなり鍵マーク）、chip= ボタンの文字と chipAt=／press= でボタンが開いて押される。アイコンは内蔵の汎用アイコン（bell work group cal mail phone msg mic play moon camera torch lock heart star pin bag music news plane gift sun clock user check alert app image search share trash info）か絵文字 1 つ。9:16 は画面全体、16:9／1:1 は画面中央に 1 台のスマホ（device）。common.lockscreen の上に重ねる（y 0.43）。効果音は common.buzz（バイブ）、common.recv（メッセージ）、common.hush（ミュート）、common.send（スワイプ／送信）。" },
  'common.lockscreen': { label: "スマホのロック画面", doc: "映像の上に重ねるスマホのロック画面（映像が壁紙）：ステータスバー（time／carrier／signal／wifi／battery）、モードのピル（mode は 1 行に「秒|文字|plain/calm/accent|アイコン」）、日付、大きな時計（clock「秒|時刻」、変わった数字が上にめくれる）、タイトル行（title「秒|文字」）とカウントの点（count「秒|n」、of はマスの数）、ライブアクティビティのバー（live「秒-秒」：時計がたたまれ上部がバーに変わる。liveLabel はカウントの前の文字）、下部の dock（丸ボタン 2 つ、解除のヒント「秒|文字|up」—up は跳ねて矢印が付く—、ホームバー。band は下にあるものを隠す濃い帯を足す）。9:16 は画面全体、16:9／1:1 は画面中央に 1 台のスマホ（device、wall で壁紙）。通知は common.notify を重ねる（y 0.43）。効果音は common.buzz（バイブ）、common.recv（通知）、common.hush（ミュート、モード切替）、common.tick（時計がめくれる）。" },
  'common.reels': { label: "ショート動画の画面", doc: "映像の上に重ねるショート動画／ストーリーズのアプリの枠（汎用の画面で、実在のアプリではない）：mode feed は全編に出る枠——上部のセグメントバー（segs は「秒-秒」をカンマか改行で区切る。slow の段はゆっくり進み最後にやっと終わる。hook「秒-秒|段」は後の段を先に見せるコールドオープンで、最後の 0.5 秒で巻き戻しアイコンとともに全部巻き戻る）、アバターとアカウント（handle）と場所（place）、タイトルのステッカー（title、手書き文字）と段数の札（count）、右側のハート／コメント／シェア／保存ボタンと数（likes、comments、shares は 1 行に「秒|数」、数の間はイージング。counts で zh 1.2萬／ja 1.2万／en 1.2K／plain 12,345。taps はダブルタップの時刻：ハートが跳ねて赤くなる。saveAt でブックマークが塗られる）、下部のアカウントとフォローボタン（follow）、説明文（caption＋more）、音楽のマーキー（music）、ナビバー（nav）；mode end は最後に feed の上に重ねる：固定コメントが飛び出し（q、qName、pinLabel）、投稿者の返信（reply、███ は黒い帯になる。replyName が空なら handle、authorLabel は投稿者の札）、保存のトースト（toast、saveAt で）、シェアシートが下からせり上がり（sheetTitle、sheetAt）、大きなボタン（btn）が tapAt で押される（指は common.touch）。9:16 は画面全体、16:9／1:1 は画面中央に 1 台のスマホ（device。common.comments と common.story に同じ値を渡すと同じスマホに重なる）。字幕は common.caption の auto／big、浮かぶハートは common.emoji の float、ダブルタップのハートは tap、コメントの流れは common.comments、ストーリーズのステッカーは common.story。効果音は common.rewind（コールドオープンの巻き戻し）、common.pop（ダブルタップ、ボタン）、common.recv（コメント）、common.send（シェア）。" },
  'common.comments': { label: "コメントの流れ", doc: "どの映像にも重ねられるライブのコメントの流れ：items は 1 行に 1 件「秒|名前|コメント|key=値」。時間が来ると下から現れ（アバター、名前、暗い吹き出しの中のコメント。長いと 2 行に折り返す）、古いものを上へ押し上げ、hold 秒とどまって消える。top より上へ押されたものも消える。color= アバターの色（なければ行ごとの色）、avatar= アバターの絵文字か文字（なければ名前の最初の文字）。x、w は左端と行の最大幅、bottom は最新の 1 件の下端、top は消える高さ（-1 自動：9:16 はセーフエリアの下端、common.reels の右側ボタンを避ける）。9:16 は画面全体、16:9／1:1 は common.reels と同じスマホに重なる（device。none はスマホなしで画面全体）。効果音は common.recv（1 件ごとに 1 回）。" },
  'common.story': { label: "ストーリーズのステッカー", doc: "ストーリーズのインタラクティブなステッカー（飛び出し、rot だけ傾き、最後の 0.2 秒で縮んで消える）。kind で投票、絵文字スライダー、タイマーを選ぶ。x、y は中心（スマホ画面に対する比率）。9:16 は画面全体、16:9／1:1 は common.reels と同じスマホに重なる（device）。場所のステッカーは common.tag の label、値札は common.hangtag、文字のステッカーは common.tag／common.caption、リングのタイマーは common.countdown。効果音は common.pop（出現、投票）、common.tick（タイマー）。" },
  'common.album': { label: "スマホのアルバム", doc: "スマホのアルバムの画面録画（汎用アプリで実在のアプリではない：文字、タブ、日付、場所、ステータスバーの時刻はすべてパラメータ、アイコンは内蔵の描画アイコン）。同じスマホに 5 つの mode を重ねる。photos は 1 行に 1 枚「素材|秒|角の文字|x,y」（プロジェクトの素材 id、動画はその秒の画面；- か空＝描いた仮の色面；角の文字が空＝動画なら長さ、- で書かない；x,y サムネイルの焦点）で、grid はこれをマスに並べ、zoom、swipe、foryou は pick 番目を使う；ステータスバーの time、battery；9:16 は画面全体、16:9／1:1 は画面中央のスマホ（device；メイントラックのクリップは frame: screenFrame(幅, 高さ)）；指は common.touch（albumTile(パラメータ, 写真, 秒, 幅, 高さ) でマスの位置）、手書きメモは common.handwrite、白／黒のフラッシュは core.flash；効果音は common.tick（タップ）、common.whoosh（開く、フリック、スワイプ）、common.thud（ピンチ）。" },
  'common.chat': { label: "チャット画面", doc: "メッセージアプリの会話の画面録画（汎用アプリで実在のアプリではない：文字はすべてパラメータ、配色も独自）、1 本の動画で 1 項目：items は 1 行に 1 件「秒[-秒]|誰|内容|key=値…」、誰＝me（右）／them（左、アイコン付き；ほかの言葉＝グループのその人の名前）／sys（中央の灰色のシステムメッセージ）／ch（章の吹き出し）；時間になるとポンと出て、新しいものが一番下に、会話は上へスクロール；種類は後ろに：既定はテキスト（/ で改行、長い行は自動で折り返し、吹き出しの高さは行数どおり）、typing 相手の入力中の 3 つの点（相手の次のメッセージか「秒-秒」まで）、photo 写真、video 動画（play=秒-秒 再生中は吹き出しに角丸の穴、メイントラックのクリップは frame: chatWindow(パラメータ, 何件目, 幅, 高さ)；open=秒-秒 吹き出しがその場から全画面へ広がり、時間になると吹き出しに戻る（片道 openTime 秒；open=秒 は項目の終わりまで開いたまま）、その間ブロック自身がそのメイントラックのクリップを広がる枠に描くので、クリップの frame はそのまま、後ろのチャットは暗く（openDim）；mute アイコン、dur= 長さ）、album アルバム（pics=素材@秒,素材@秒,- 複数枚、labels= それぞれの名前）、link リンクカード（内容がタイトル、sub=、button=、badge= 長さ、press= 押す）、voice ボイスメッセージ（dur=、play=秒-秒 で波形が進む、内容は文字起こし）、sticker 大きなスタンプ（内容は絵文字、吹き出しなし）；src= 素材 id、t= 何秒目（素材なし＝描いた仮の色面）、t2= 再生後の画面、crop=x,y,zoom、ratio=4:5、w= 幅（画面の幅の比率）、tag= 写真の小さなラベル；自分のメッセージは readAfter 秒後に既読（read で文字を変更；read=秒 個別指定、unread 表示しない）、when= 時刻の小さな文字；name= avatar= color= グループのメンバー；上部の pin ピン留め（タイトル；ch があれば章の点が順に点灯、icon= 点のアイコン、既定は章の文字の先頭の絵文字）；ヘッダー：name、status、avatar；2 つ目の項目で続ける：同じパラメータに since=秒（items の時間）を足すと、この項目は会話のその秒から始まり、それまでのメッセージはもう表示され、ポンと出ず、スクロール済み、再生済みの動画は t2= の画面（chatWindow／chatPoint の秒は items の時間）；入力欄 inputs「秒-秒|文字|type/delete」で入力・削除、空なら hint；panel 入力欄の下のスタンプパネル（絵文字を空白区切り；空＝なし）；wall「秒|#上|#下」壁紙の色（キーの間をイージング、昼から夕方へ）；9:16 は画面全体、16:9／1:1 は画面中央のスマホ（device）；指は common.touch（chatPoint(パラメータ, 何件目, 秒, 幅, 高さ) で位置）、大きな爆発ステッカーは common.burst、漂う絵文字は common.emoji、字幕は common.caption；効果音は common.send、common.recv、common.typing、common.buzz（既読スルー）、common.pop（スタンプ）。" },
  'common.search': { label: "検索画面", doc: "検索エンジンの画面の画面録画（汎用のダークな検索画面で実在のものではない：ロゴも色付きの文字もなし；タブ、関連検索、検索中…、もしかして、強調スニペット、完全版などの文字はすべてパラメータ）、mode で 5 つの画面を切り替える；時間は項目の開始から；enter 秒で下から押し上げて登場；9:16 は画面全体、16:9／1:1 は画面中央のスマホ（device）；指は common.touch（searchPoint(パラメータ, pick/bar/play, 幅, 高さ) で位置）、白いフラッシュは core.flash、字幕は common.caption、エンディングは common.outro；効果音は common.typing、common.tick（タップ）、common.pop（事実カード）。" },
  'common.camcorder': { label: 'ビデオカメラのファインダー', doc: '家庭用ビデオカメラ／DV のファインダー：osd は映像の上に重ね、ff、rew、snow は画面全体を覆う。文字（REC、TAPE、月名…）はすべて words で変えられる。思い出、結婚式、ホームビデオ、Y2K、旅の DV に。common.film の look vhs、common.beep の kind rec／end、common.rewind と合わせる' },
  'common.magazine': { label: '雑誌のページ', doc: '映像がレイアウトの映像枠（穴）から流れる雑誌の 1 ページ（メイントラックのクリップは frame＝magazineWindow(パラメータ)）：雑誌の紙、誌名（title）と号の表記（issue／issueSub）、号数とページ（no／page）とページの四角の列、二重線。縦長ではコマを映像の下に、正方形と横長では横に置く。インタビュー、旅の特集、人物紹介、開封、ランキングに。ページめくりは common.wipe mode curl。全面の映像に誌名と目次を重ねるだけ（都市・グルメの雑誌風の表紙、誌名をタイプ）か一色の裏表紙なら common.masthead、静止画の写真の一ページ（スウォッチ、コラム、映像の下に敷く）なら common.spread。' },
  'common.casefile': { label: '調査ファイル', doc: 'ファクトチェックの調査ファイル：紙の上のクラフト紙のフォルダーに、マスキングテープで留めた映像の窓（窓は穴で、frame＝casefileWindow(パラメータ) のメイントラックのクリップがそこから見える）。見出しに発言者、発言が 1 字ずつ打たれ、証拠欄が slots「秒|ラベル」の時刻に 1 マスずつ押印される。strikeAt で発言が赤ペン 2 本で消され、二重枠の「却下」印が押され、closeAt でふたが上から閉じて窓を覆い「結審」印が押される。縦型・正方形では見出しが窓の上、横型では窓の右。文字はすべてパラメータ。ファクトチェック、論破、発言と証拠の突き合わせ、まとめ、判決に。common.thud、common.whoosh と合わせる' },
  'common.beep': { label: '伏せ字ピー音', doc: '1 kHz のテレビの伏せ字ピー音。長さは伏せる言葉に合わせる。common.censor ステッカーと組み合わせる。kind rec はビデオカメラが録画を始めるときの短く高い「ピピッ」2 回、end はテープ残りわずか・電池切れの 3 回（この 2 つは長さと周波数を見ない。DV、ホームビデオ、common.film の vhs と一緒に）。' },
  'common.whoosh': { label: 'シュッ', doc: '一度掃き抜ける風切り音。場面転換、要素の飛び込みと飛び出しに。' },
  'common.impact': { label: '重い一撃', doc: '低音の重い一撃に長い余韻。どーん文字の着地、タイトルの登場、転換に。' },
  'common.shing': { label: '光のスイープ', doc: '光が横切る明るい音（高いシャーという音と下がっていく高音）。ロゴの着地、文字を走る光、明かされる瞬間に。' },
  'common.air': { label: 'ひと息', doc: 'ゆっくり立ち上がって消える空気の音。画面が開く、壁が現れる、パートのあいだの息つぎに。bright で明るく。' },
  'common.riser': { label: 'ライザー', doc: 'だんだん高く大きくなる上昇音で、高い所で終わる。転換や発表の前の盛り上げに。' },
  'common.pop': { label: 'ポン', doc: '短い泡の「ポン」。ステッカー、絵文字、小さな要素の登場に。' },
  'common.thud': { label: 'ドスッ', doc: '短く低い鈍い音で、スタンプを押すよう。common.stamp と組み合わせる。paper: 机の上の紙カードに押すゴム印（木をたたく音と紙の音がもう1つ）、common.postmark／common.flatlay と組み合わせる。' },
  'common.tick': { label: 'カチッ', doc: 'すっきりしたクリック音。数える、進行、タイピング、1文字ずつ現れるときに。' },
  'common.ding': { label: 'チン', doc: '澄んだ「チン」という一音。正解、要点の登場、ひらめきに。チンを連続させるなら一段ずつ上がるように：同じ pitch（主音）、step 0、1、2…（scale: major 長調／pentatonic 五音音階）。' },
  'common.error': { label: 'エラー音', doc: '低く鈍い「ブッブッ」の2音。不正解、失敗、NG に。' },
  'common.shutter': { label: 'シャッター', doc: 'カメラのシャッターの「カシャ」。静止、撮影、ポラロイドに。' },
  'common.typing': { label: 'タイピング', doc: 'キーボードを打つ音で、長さは調整できる。文字が1つずつ現れる、検索、コメントに。' },
  'common.cash': { label: 'レジ', doc: 'レジの「チャリーン」。価格、節約、儲け、大きな出費に。coins は引き出しが開く音と硬貨の音を加える（合計、会計）。' },
  'common.deflate': { label: 'しぼむ音', doc: '「プシュー」と下がっていくしぼむ音。ノーカウント、がっかり、ほんの少ししか動かない、場がしらける、に。' },
  'common.scratch': { label: 'レコードスクラッチ', doc: 'レコードが引っかかって止まる「キュイーッ」。空気が急変、割り込み、「ちょっと待って」の笑いどころに。' },
  'common.powerup': { label: '起動スキャン', doc: 'メーターの起動：サーボモーターが回り上がってまた戻り、チクタクの連なりが付く。ゲージ、機械の起動、スキャンに。' },
  'common.alarm': { label: 'アラーム', doc: '短い「ピッ、ピッ、ピッ」のアラーム（回数は調整可）。危険、振り切れそう、カウントダウンの最後の数秒に。' },
  'common.explode': { label: '爆発＋ガラス破片', doc: 'ドーンという爆発と低音の落下、続いてガラスの破片の音。振り切れ、やらかし、大発表に。common.burst の blast と組み合わせる。' },
  'common.ffwd': { label: '早送り', doc: 'テープの早送りの「ヒュルル」と駆け上がる音。時間の早送り、待ちを飛ばすときに。common.timelapse と組み合わせる。' },
  'common.page': { label: 'ページめくり', doc: '紙のページをめくる音：紙が持ち上がり、裏返り、そっと落ちる柔らかなさらさら音（中低域中心で耳に刺さらない）。ステップの切り替え、カードの切り替え、次のページを開くときに。common.notecard と組み合わせる。' },
  'common.slide': { label: 'カード滑り込み', doc: '紙の束の上をカードが滑り、最後にそっと落ち着く音。ポストカード、カード、写真が画面に滑り込むときに。common.flatlay と組み合わせる。' },
  'common.flip': { label: 'カード裏返し', doc: '机の上のカードが裏返る音：紙と空気のパタパタが2回、そして落ち着く。裏面に返す、面を替えるときに。common.flatlay と組み合わせる。' },
  'common.xylo': { label: '木琴', doc: '短い木琴の一音。リストのチェック、項目が1つずつ現れるときに（同じ pitch を主音に step 0、1、2… と一段ずつ上がる、scale: major／pentatonic。または pitch を直接変えて小さなメロディにする）。' },
  'common.print': { label: '印字', doc: '感熱レシートプリンターの印字のうなり（印字ヘッドとステッピングモーター）で、長さは調整できる。1行印字するごとに一音。common.printer と組み合わせる。' },
  'common.clunk': { label: '紙切りカチャ', doc: 'レシートプリンターのカッターや紙送りのラッチの「ガチャ」という一音。新しい区間、お店の切り替え、機械の動作に。' },
  'common.tear': { label: '紙を破る', doc: '紙を1枚「ビリッ」と破り取る音。レシートを切る、日めくりを破る、破ってやり直すときに。common.printer の tearAt と組み合わせる。' },
  'common.rattle': { label: 'シャッターのガラガラ', doc: 'シャッターを下ろす「ガラガラ」と最後のドン。閉店、終業、終わりに。common.rolldoor と組み合わせる。' },
  'common.dingdong': { label: 'ピンポーン', doc: '呼び出し機の「ピンポーン」の2音（高音から低音、既定は A5→F5）。番号の切り替え、次の方、区間の切り替え、到着に。common.digits の led と組み合わせる。' },
  'common.ringbell': { label: 'リングのゴング', doc: 'ボクシングのリングのゴング「カン、カン」（回数は調整可）：強く打つ一撃に長い金属の余韻。ラウンド開始、対決、冒頭の VS、試合終了に。common.versus のラウンドカードと組み合わせる。' },
  'common.chime': { label: 'きらきらチャイム', doc: 'ちりんちりんと駆け上がるきらめき（鉄琴の分散和音で、音数、開始音、間隔は調整可。chip: 8ビットの矩形波）。きらきら、きれいになる、発表、魔法、レア物に。common.sparkle の画面と組み合わせる。' },
  'common.coin': { label: 'コイン', doc: '8ビットゲームのコイン投入「チャリン↑」（矩形波の2音で、音の高さは調整可）。コイン投入、得点、アイテム入手、ガチャ、ポイント集めに。' },
  'common.fanfare': { label: 'クリアファンファーレ', doc: '8ビットのクリアファンファーレ：4音が上がり、さらに大きな和音が1つ（主音は調整可）。完了、コンプリート、勝利、解放、エンドに。' },
  'common.knock': { label: '木のノック', doc: '木を叩く「コンコン」（回数、間隔、音の高さは調整可。低めはドアのノック、高めは木魚のよう）。ノック、リマインド、1つずつ数える、禅の雰囲気に。' },
  'common.boing': { label: 'バネ', doc: 'バネの「ボヨヨーン」というコミカルな弾み（音の高さは調整可）。跳び上がる、飛び出す、ぷにぷに、おどけた跳ね返りに。' },
  'common.footstep': { label: '足音', doc: '足音の連なり（歩数、間隔は調整可。左右の足で音の高さが違う。soft：柔らかいコミカルな足音、既定は板の床）。画面に歩いて入る、隣の部屋へ歩く、こっそり近づくときに。' },
  'common.flap': { label: '羽ばたき', doc: '翼が「バサバサバサ」と羽ばたく（回数、間隔は調整可）。鳥が飛び去る、画面に飛び込む、紙が舞うときに。' },
  'common.whirr': { label: 'テープ巻き', doc: 'ビデオテープやカセットが巻かれる「ウィーン」というモーター音（長さは調整可）。テープの交換、巻き戻し、過去へ戻る、古いビデオに。common.film と組み合わせる。' },
  'common.scribble': { label: 'ペンの走り書き', doc: 'ペンが紙に文字や線を書くさらさらという音（長さ、毎秒の筆数は調整可。crayon：クレヨンで、太くざらつく）。手書き文字、丸を描く、チェック、落書きに。common.handwrite／common.pen と組み合わせる（common.scratch のレコードスクラッチとは別物）。' },
  'common.tape': { label: 'テープを剥がす', doc: 'テープの巻きから一片を「ビーッ」と剥がして貼り付ける一音（press を切ると剥がす音だけ）。ラベル貼り、メモ貼り、写真貼りに。common.tear（紙を1枚破り取る）とは別物。' },
  'common.clink': { label: 'スプーンと器', doc: 'スプーンが陶器の器に当たる「チン」という澄んだ一音（glass：氷がグラスに当たる、チンチンチンの3回）。食べる、かき混ぜる、スープを飲む、冷たい飲み物、乾杯に。' },
  'common.drip': { label: 'しずく', doc: '水滴の「ポチャン」と上へ滑る一音（滴数、間隔、音の高さは調整可）。水滴、汗、考えが浮かぶ、少しずつたまるときに。' },
  'common.sizzle': { label: '油で焼く', doc: '熱い油に入れる「ジュー」という焼ける音で、油はねのパチパチ付き（長さは調整可）。焼く、揚げる、炒める、鍋に入れる、あつあつに。' },
  'common.pour': { label: '注ぐ', doc: '水や飲み物を注ぐ「ジャー」という水流の音（長さは調整可）。お茶を注ぐ、スープを注ぐ、ソースを足す、満たすときに。' },
  'common.cry': { label: '赤ちゃんの泣き声', doc: 'コミカルな赤ちゃんの泣き声「うえーん」（回数、音の高さは調整可。柔らかく耳に刺さらない）。赤ちゃん、子育て、大崩れ、泣くときに。' },
  'common.thunder': { label: '遠雷', doc: '遠くの雷：最初に小さくバリッと鳴り、低いゴロゴロが約 3 秒かけて遠ざかる（seed で別の鳴り方）。嵐、空が暗くなる、悪い知らせ、稲妻に。common.ambient の look sky とその稲妻と合わせる。' },
  'common.buzz': { label: 'スマホのバイブ', doc: 'テーブルに置いたスマホが震える「ブーッ、ブーッ」（回数は調整可）。着信、通知、メッセージが届く、既読スルー、心がドキッとする瞬間に。common.touch と組み合わせる。' },
  'common.send': { label: 'メッセージ送信', doc: 'チャットのメッセージを送ったときの短く上がる「シュッ」。メッセージ送信、コメント投稿、送信ボタン、投稿に。' },
  'common.recv': { label: 'メッセージ受信', doc: 'メッセージが届いたときの柔らかく上がる 2 音（2 音目は 5 度上、音の高さは調整可）。新着メッセージ、相手の返信、通知のポップアップに。common.dingdong（呼び出し機の下がる 2 音）とは別物。' },
  'common.hush': { label: 'ミュート', doc: '下がっていく 2 音「トゥ↓トゥ」：通知をオフ、ミュート、アラームを止める、着信拒否、相手にしたくないときに。common.deflate（空気が抜ける下降音）、common.error（不正解）とは別物。' },
  'common.rewind': { label: '巻き戻し', doc: 'ビデオテープを巻き戻す「キュルルル↓」：明るいノイズがこもっていき、高い音が下がっていく（長さは調整可）。巻き戻し、過去に戻る、やり直し、振り返りに。common.ffwd（上がっていく早送り）の逆。' },
  'style:pluck': { label: '軽快なピッキング', doc: '明るい撥弦楽器の分散和音、木琴の小さなメロディ、軽いシェイカーと手拍子。楽しい日常、グルメ、旅行、開封に。' },
  'style:lofi': { label: 'Lo-fi', doc: 'ゆるいエレピのセブンスコード、ゆるく跳ねるドラム（スウィング付き）、柔らかいベース。勉強、おしゃべり、日常、夜、思い出に。' },
  'style:cinematic': { label: 'シネマティック', doc: 'ゆっくり広がるシンセの大きなパッド、低音の長い音、まばらな鐘、盛り上がるドラム。風景、予告、情感、ドキュメンタリーに。' },
  'style:tech': { label: 'テックパルス', doc: '四つ打ちのバスドラ、16分音符のパルスベース、裏拍のオープンハイハット。テック、解説、データ、AI、編集、ハードコアに。' },
  'style:playful': { label: 'おちゃめな木琴', doc: '弾む木琴のメロディ、低高交互の oom-pah 伴奏、シェイカーと手拍子。かわいい、おもしろい、子ども、ペット、気楽な日常に。' },
  'style:bout-bell': { label: 'リングのラウンド', doc: '軽快なクイズ番組風のパルス（短調、100 bpm）：冒頭にボクシングのゴングと重い一撃、各区間の頭（新しいラウンド）にシュッ＋ゴング「カンカン」＋低音の重い一撃、各区間の終わりにスタンプの鈍い音と止めの和音、最後は小太鼓のロールから明るい締めの和音へ。上下分割の対談、討論、彼が言う彼女が言う、二者の比較に（ゴングの効果音は common.ringbell にもある）。' },
  'style:chiptune': { label: '8ビットアーケード', doc: '8ビットのテレビゲーム：矩形波の主旋律と速いアルペジオ、三角波のオクターブ跳躍ベース、ノイズのドラム、明るい長調で軽快（150 BPM）。ゲーム、ガチャ、カード引き、収集、ステージクリア、レトロに。' },
  'style:funk-minor': { label: 'マイナーファンク', doc: '96 BPM の短調ファンク：弾けるシンセベース（オクターブポップ）、boom-bap のドラム、2/4拍の手拍子、スウィングするハイハット、裏拍のミュートしたクラビネット。各区間の前でドラムとベースが半拍抜ける。語録、動くテキスト、名言、笑い、ストリート感（スクラッチ、スタンプなどの効果音は c.sfx で置く）。' },
  'style:garden-folk': { label: '午後のキッチン', doc: 'やさしい午後のキッチンのフォーク：撥弦の分散和音、オルゴールのメロディ、暖かいパッド、軽いシェイカーとブラシのドラムで、バスドラはない。手書きレシピ、ベイキング、手作り、スローライフの vlog に。' },
  'style:guzheng-pop': { label: '古箏ライトエレクトロ', doc: '五音音階の古箏の撥弦（押さえ弦のスライドあり）＋月琴の分散和音＋軽いエレクトロのビート（96 BPM）で、まばらから満ちて、最後に古箏へ戻る。客家、台湾の伝統、東洋の味わいで現代的な情報解説、文化紹介、地元グルメに。' },
  'style:hijaz-route': { label: 'スパイスルート', doc: '中東／シルクロードの風味：低音の持続音（主音＋5度）の上でヒジャーズ音階のウード撥弦、フルート、枠太鼓の dum/tek とシェイカー（84 BPM）。尺に応じてまばらから満ち、長尺は7割の所でドローンと鈴だけになり、最後に主題へ戻って大きな和音で終わる。歴史、地図、航海、スパイス、古代文明、市場の解説動画に。' },
  'style:lullaby-box': { label: '常夜灯のオルゴール', doc: 'やさしい常夜灯のオルゴール（72 BPM、長調）：オルゴールのメロディ、暖かいパッド、柔らかいベース、フェルトピアノの分散和音。中盤で短調に転じて低い鼓動が加わり、後半に鉄琴が入り、エンドの前は余白で単音だけ残る。子育て、寝る前、赤ちゃん、あたたかい科学解説や思い出に。' },
  'style:market-groove': { label: '夜市グルーヴ', doc: '王道進行の都会的なポップのグルーヴ：エレピのシンコペーションの和音、弾むベース、木魚と木琴の小さなフック。にぎやかだがすっきりした屋台、市場、お店巡りに。' },
  'style:mischief': { label: 'こっそりピッキング', doc: 'こっそりした撥弦のグルーヴ（ニ短調、120 bpm）：冒頭のアクセント、やさしい1小節、層を重ねて厚くなるつまみ食い感のグルーヴ、チクタクの鼓動だけの息を止める間、小太鼓の積み重ね、ロール、ドン、明るいニ音の空虚5度で終わる。おもしろいギャップ、採点、振り切れ、どんどん大げさになる短編に。' },
  'style:postcard-felt': { label: 'ポストカードのフェルトピアノ', doc: 'ゆっくりしたフェルトピアノ：左手は分散和音、右手はまばらな小さなメロディ、ときどきオルゴールの一音。やさしく、懐かしく、自分への手紙のよう。ゆったりしたペースの旅日記や思い出に。' },
  'style:queue-call': { label: '呼び出し短調', doc: '軽快な木琴＋撥弦ベース＋シェイカーで、各区間の頭に呼び出し機の「ピンポーン」、終わりの前に低いドラムの重い拍。軽食店、行列の名店、1軒ずつ紹介、何番目の理由に（番号が替わるピンポーンの効果音は common.dingdong にもある）。' },
  'style:quote-drop': { label: '名言ドロップ', doc: '短調の静かなインタビューの下地：鼓動のベース、こもった撥弦、軽いハイハット。冒頭に1小節の予告（低音のうなり＋ライザー＋重低音）、6割あたりの名言の前の半小節は全部止まってライザーだけ、名言の小節の1拍目に重低音と高音の鈴、その後は長調に転じて終わる。ポッドキャストの名言、インタビュー、講演の一番強い一言に（名言は quoteDropPlan(小節数).hit の小節の1拍目に置く）。' },
  'style:rail-beat': { label: '駅ビート', doc: '120 BPM の短調エレクトロビート：半分の速さの冒頭の重い拍、四つ打ちのバスドラ、都市が替わるときにドラムを抜いてライザーから重い拍で到着、リプレイ区間は16分音符のハイハットとパルスの主旋律、小太鼓の押し、ブレイクのあと重い拍で終わる。小節数から区間を自動で配置する。拍に合わせた早回し、旅のリズム編集、複数都市の旅に。' },
  'style:receipt-hop': { label: 'レシートのホップ', doc: '軽快なレジ台の小さな日常：裏拍の撥弦の和音、ウォーキングベース、シェイカーと軽い手拍子、木琴の小さな尾、レジのような小さなチクタク。グルメの家計簿、リスト、買い物に。' },
  'style:steelpan-bossa': { label: '夏のスチールパン', doc: '涼しい夏の軽いボサ（100 BPM、長調）：スチールパン、マリンバのアルペジオ、Rhodes のセブンスコード（シティポップ進行）、根音と5度のベース、リムショット、シェイカー。ほとんどは人が話せるよう薄いリズムだけを残し、中盤の短い区間と最後の区間でだけメロディが開く。アイス、夏、海辺、おしゃべりの多いグルメ紹介に。' },
  'style:walking-pizz': { label: '街の散歩', doc: '散歩感（100 BPM、軽いスウィング）：ピチカートの弦の和音、ウッドベースの4分音符のウォーキングベース、ブラシのドラム、鉄琴の小さな返し、口笛のメロディ。地図のルート、お店巡り、散歩、食べ歩き、街の小さな旅に。' },
  'style:candle-glow': { label: 'キャンドルの灯り', doc: 'あたたかいお祝いの音楽（72 BPM、長調）：エレピのモチーフ、ストリングスのパッド、チェレスタのきらめき、はじく弦のグルーヴ。cues で映像に合わせる：low は短調になり低いドローンだけ、bright で長調に戻って広がる、play は弾むように、wait はサプライズ前に宙づり、shout は歓声のために止まる、party は軽いグルーヴ、quiet はパッドだけ残して会場の歌に譲る、tender はピアノだけ。誕生日、結婚式、卒業、送別、サプライズパーティーに。' },
  'style:night-studio': { label: '夜のスタジオ', doc: 'トークのためのごく静かな下敷き（84 BPM、短調）：柔らかいエレピの七の和音（i–VI–III–VII）、伸ばしたパッドとルートのサブベース、厚い小節だけシェイカーとベル。インタビューやポッドキャストの切り抜きの下で声とぶつからない（gain は -19 前後、c.duck と併用）。' },
  'style:cold-case': {"label":"未解決事件","doc":"トーク切り抜きの低いサスペンスの下敷き（60 BPM、短調）：拍ごとに乾いた掛け時計のチクタク、短調の低い持続音（i–VI–iv–i）、ときどき寂しい鐘の音が二つ。cue reveal で 2 秒すべて抜け、cliff で音楽がぷつりと切れてエンドカードに低い音が一つだけ残る。実録事件、未解決事件、ミステリー、調査もの（gain は -14 前後、c.duck と併用）。"},
  'style:handmade': {"label":"手づくりの朝","doc":"あたたかいゆっくりした曲（72 BPM、長調）：フェルトピアノ、コントラバスのような持続音、柔らかいパッド。cues で少しずつ満ちていく（beats で分散和音、proof がいちばん厚く、breath で一拍止まり、we でゆっくり和音が開き、logo で低いオクターブと鐘）。手作り、パン、早朝、小さな店のブランド動画に。"},
  'style:sunny-hop': {"label":"晴れの日スキップ","doc":"明るく弾む曲（108 BPM、長調）：裏拍の撥弦、オクターブで跳ねるベース、手拍子、マリンバのフック、水滴の「ポン」。cues：groove でドラムが入り、lift でさらに厚く、breath で抜け、rise で盛り上がり、hit でロゴの一撃。動く文字、アウトドア、スポーツ、軽快なブランド動画に。"},
  'style:circuit-pulse': {"label":"サーキットパルス","doc":"クールで精密な電子音の下敷き（100 BPM、長調）：8 分音符のベースのパルス、16 分音符の撥弦アルペジオ、軽いドラム。cues で段落に合わせて起伏する（build でアルペジオ、drums でビート、full で手拍子、breath でパッドだけ、hit でロゴに一撃）。テック、アプリ、ハードウェア、スタートアップのブランド動画や製品紹介に。"},
  'recipe:travel': { label: 'ナレーション旅行', doc: '場面ごとのナレーションに映像を合わせる：字幕はナレーションに従い、各場面に場所ラベルを1つ、タイトルとエンドカード、音楽はナレーション中に下がる。旅行、街歩き、思い出に。', notes: [
    '各場面の長さはナレーションで決まる（ナレーションの長さ＋場面間の gap 秒）。場面内のショットは weight でこの時間を分け合い、最後の場面は 1.5 秒多く残る。',
    'ショットは素材の次のシーンへまたがない：必要な長さが from のあるシーンを超えるときは、from を前へずらす。シーン全体が足りないときはそのまま使い、結果に警告を出す（別の素材を使うか、ショットを足す）。',
    'タイトル（title）は約 2.4 秒、エンドカード（end）は 3.5 秒で、どちらも尺に含まれる。',
    'music はスタイル名、または { style, bpm, key, seed, gain }。新しく書いたスタイルは projects/<id>/score/ に置く。',
  ] },
  'recipe:hook': { label: 'フック短編', doc: '話している素材から切り出したフック短編：パネルのレイアウト、冒頭の爆発文字、区間ごとの番号バッジとタグ、話し声の字幕（ハイライト、伏せ字、誤字の修正）、章の点、最後の行動の呼びかけ。グルメ、インタビュー、ポッドキャストに。', notes: [
    'レイアウトは上から下へ重ならない：バッジとタグ（画面高の 0.05–0.13）→ パネル（既定 0.15–0.62）→ 章の点（パネルの真下）→ 字幕（下部のインターフェース領域の上）。',
    'panel に { frame: [x, y, 幅, 高さ] } を渡すとパネルの位置を変えられる。章の点はパネルの下に付いてくる。',
    'censor の語は、その区間で本当に話されている語でなければならない（文字起こしを基準にする）。文字起こしが聞き間違えた語は fix で字幕を直す（伏せ字の照合には影響しない）。',
    'cta は最後の区間の最後の 2.2 秒に重なる。',
    '各区間は既定で tighten: true：話の途中の 0.6 秒を超える間は 0.3 秒に縮められ、区間は len より短くなる。間を残したい（例えば笑いどころを待つ）なら tighten: false を渡す。',
    'captions には残したい文を渡せる（例えば ["新鮮", "いい香り"]：これらの語を含む字幕だけを残す）。',
    'c.recipe は各区間で作られたアイテムの id を返す（segments[i].clip（間を切った後の最初の1つ）／pieces（すべて）／badge／tags／captions／progress）。あとで c.update(id, { params: { size: 5 } }) や { transform: { x, y, scale } } でどれでも微調整できる（バッジ、タグ、章の点は各区間の clip にぶら下がり、start／end を渡すときはその clip を基準にした秒数）。',
  ] },
  'recipe:montage': { label: 'ミュージックモンタージュ', doc: '音楽の拍にショットを切る：4ショットごとに1区間、区間の頭に白いフラッシュとシュッ、タイトルと大きな文字カード、フィルム質感。結婚式、旅の思い出、イベントの記録に。', notes: [
    '尺＝すべてのショットの拍数 × 1拍の秒数（60 / bpm）に、エンドカード（end）の 8 拍を足したもの。',
    'mood が各ショットのおおよその長さを決め（gentle 3.5 秒、steady 2.5、lively 1.6、urgent 1）、整数拍に丸める。rhythm の既定は varied：4ショットごとにおよそ「1、½、1½、1」倍の長さで交互になる（区間の合計は変わらず、小節に合う）。全部同じ長さ（スライドショーのよう）にはしない。beats を渡したときの既定は even。',
    'hero: true のショットは基本の長さ2つ分とどまる（長い位置に置かれたときは長いほう）。動画全体で一番大事な画面のために取っておく。drop はそのショットの索引で、音楽はそのショットが始まるときに2拍あける（感情のピークの間）。',
    'ショットの sound に dB（例えば -14）を渡すと、そのショット自身の音（笑い声、波の音）を残す。渡さなければ音楽だけ。',
    '隣り合う2つのショットを同じ素材の隣り合う位置にしない（ジャンプカットに見える）。同じ被写体とサイズが続くのも避ける。保存時に前者を警告する。',
    'cards の shot はショットの索引で、0 から数える（最初のショットが 0）。',
    'title は文字列、または { text, size }（size は文字サイズで画面高の %、既定 9。長いタイトルは小さくする）。改行は \\n で書く。',
    'ショットの beats は個別に指定できる（例えば最後だけ 8 拍）。mood、rhythm、hero より優先される。',
  ] },
  'clip.shake': { label: 'カメラの揺れ', doc: 'そのとき再生中のクリップの画面が一度揺れてからゆっくり止まる：どーん文字、衝撃、笑いどころに。hook レシピの冒頭を揺らしたいなら、hook に shake: true を足す。' },
  'clip.follow': { label: 'ステッカーが口（や顔）を追う', doc: 'どんなステッカーもクリップの中の人の口や顔に貼って一緒に動かせる。何人かいるときは who: left／right／largest／center を足す。伏せ字：censorSpeech(…, { follow: true })。' },
  'clip.avoidBurned': { label: '元映像の焼き込み字幕を避ける', doc: '元映像に焼き込まれた字幕（分析時に検出）がこの区間にあるとき、自動で拡大クロップして字幕を画面の外へ押し出し、映っている顔は画面内に残す。拡大の上限は素材の解像度で決まり（それ以上はぼやける）、避けられないときや顔が切れるときはそのままにし、その字幕に重なっていて位置を指定していないこちらの字幕を画面上部へ移して知らせる。' },
  // クリップのトランジションと形：名前はエディターのもの（ja.ts の ed.trans*、形は日本語にした名前）
  'clip.transition.dissolve': { label: 'ディゾルブ', doc: '前のクリップがゆっくり消え、このクリップが浮かび上がる。二つの画面が重なって入れ替わる、いちばん静かなトランジション。時間や場所をそっと変えるときに。' },
  'clip.transition.slide': { label: 'スライド', doc: 'このクリップが片側から滑り込んで前のクリップを覆い、滑りながら浮かび上がる。次の話題、次の場所へ。dir で入ってくる側を決める。' },
  'clip.transition.wipe': { label: 'ワイプ', doc: '一本の線が画面を横切り、線の後ろがこのクリップになる。はっきりした段落の切り替え、ビフォーアフターに。dir で動く向きを決める。' },
  'clip.transition.iris': { label: 'アイリス', doc: 'このクリップが円の中から開き、円が広がって画面を覆う。種明かし、一点への注目に。x、y は円の中心。' },
  'clip.transition.clock': { label: 'クロックワイプ', doc: '針が 12 時から時計回りに一周し、通ったところがこのクリップになる。時間の経過、カウントダウン、一日後。' },
  'clip.transition.bars': { label: 'ストライプ', doc: '画面が六本の帯に分かれ、上下交互に一本ずつこのクリップに変わる。軽快な段落の切り替え、リストの次の項目に。dir で始まる側を決める。' },
  'clip.transition.push': { label: 'プッシュ', doc: 'このクリップが前のクリップを画面の外へ押し出し、二つの画面が並んで動く。次の目的地へ、時間が先へ進むときに。dir で押す向きを決める。' },
  'clip.transition.zoom': { label: 'ズームスルー', doc: '前のクリップがぼやけながら大きくなって突っ込み、このクリップが拡大から元に戻る。次の場面へ飛び込む、スピード感。' },
  'clip.transition.whip': { label: 'ホイップパン', doc: 'カメラを素早く振ったように、二つのクリップが一緒に高速で横へ流れ、途中にモーションブラーがかかる。テンポのいい編集、「次の瞬間には…」。dir で振る向きを決める。' },
  'clip.transition.blur': { label: 'ブラー', doc: '前のクリップがぼやけ、このクリップがぼかしの中から浮かんでピントが合う。回想、夢、ぼんやりした気分に。' },
  'clip.transition.dip': { label: '暗転', doc: '前のクリップが真っ黒まで暗くなり、黒の中からこのクリップが明るくなる。章と章の間、時間が大きく飛ぶとき、エンディングの前に。' },
  'clip.transition.flash': { label: '白フラッシュ', doc: '途中で一瞬白く光り、前のクリップが白く飛んで、光が引くとこのクリップになる。写真を撮る瞬間、記憶のフラッシュ、拍に合わせた一撃に。' },
  'clip.shape.circle': { label: '円', doc: '映像を正円に切り抜き、ウィンドウの中央に置く。人物紹介、アイコン、一つのものへの注目に。' },
  'clip.shape.ellipse': { label: '楕円', doc: 'ウィンドウいっぱいの楕円に切り抜く。古い写真、やわらかいピクチャーインピクチャーに。' },
  'clip.shape.arch': { label: 'アーチ', doc: '上が半円で下が四角いアーチ窓。高さより幅が広くなることはない。窓の外の景色、戸口から見た眺め、上品なレイアウトに。' },
  'clip.shape.heart': { label: 'ハート', doc: '映像をハートに切り抜き、ウィンドウの中央に置く。好きなもの、カップル、お祝いに。' },
  'clip.shape.star': { label: '星', doc: '五芒星。先端の数、内側の角の深さ、角の丸みを変えられる（先端が多く内側が浅いと爆発形に）。ハイライト、受賞、サプライズに。' },
  'clip.shape.ngon': { label: '多角形', doc: '正多角形（初期値は六角形）。辺の数、角の丸み、回転を変えられる。三角形、ひし形、ハニカムのレイアウトに。' },
  'clip.shape.stamp': { label: '切手', doc: '四辺に目打ちのある切手のふち。旅行、絵はがき、コレクションの一枚に。' },
  'clip.shape.bubble': { label: '吹き出し', doc: 'しっぽ付きの吹き出し。tail でしっぽの向きを決める。誰が何を言ったか、心の声、リアクションのカットに。' },
  'clip.shape.blob': { label: 'ブロブ', doc: '丸みのある不規則なかたまり。ゆっくり揺らすこともできる（wobble）。かわいさ、手作り感、楽しいレイアウトに。' },
  'clip.shape.torn': { label: '破れた紙', doc: '紙を破いたようなふち。どの辺を破るか選べる。コラージュ、手帳、切り抜きの雰囲気に。' },
  'clip.shape.brush': { label: 'ブラシストローク', doc: 'ふちがかすれた一本の筆あと。高さは幅の 1 : 2.6 まで。手描き感のあるタイトル画面、アートな雰囲気に。' },
  'clip.shape.slats': { label: 'スラット', doc: '映像を縦（または斜め）の何本かのスラットに分け、間にすき間を空ける。ブラインド、分割の見せ方、ファッションの雰囲気に。' },
  'clip.shape.text': { label: '文字', doc: '大きな文字の中で映像が流れる（1 行か 2 行。字が少なく太いほど映像がよく見える）。タイトル、地名、スローガンに。' },
  'caption:clean': { label: 'くっきり縁取り', doc: '白い文字に黒い縁取り。邪魔にならない話し言葉の字幕。' },
  'caption:bare': { label: '白文字だけ', doc: '白い文字だけ。画面が十分に暗く落ち着いているときに。' },
  'caption:darkbox': { label: '暗い下地', doc: '半透明の暗い角丸の箱に白い文字。にぎやかな画面でも読める。' },
  'caption:bubble': { label: '吹き出し', doc: 'クリーム色の吹き出しに太い墨の枠と墨の文字。強調はメインカラー。' },
  'caption:receipt': { label: 'レシートの紙片', doc: 'ギザギザに破れたレシートの紙片に印字され、下から飛び出す。' },
  'caption:crayon': { label: 'クレヨンの帯', doc: 'クレヨンで塗ったハイライト色の帯に墨の文字。絵本、手作り風。' },
  'caption:snippet': { label: '検索スニペット', doc: '左に細い色の線がある暗い角丸のバー。検索結果の抜粋のように。' },
  'caption:interview': { label: '雑誌インタビュー', doc: '暗いグラデーションの上に左寄せの明朝体。Q、A や名前を左のバッジに。' },
  'caption:autocap': { label: '自動字幕', doc: '暗い角丸の箱に白い文字が 0.88 倍から弾んで出る。SNS の自動字幕のように。' },
  'caption:sticker': { label: 'デカ文字ステッカー', doc: '手書きの大きな文字をハイライト色と太い黒縁で。0.6 倍から弾んで出る。リアクション、ツッコミに。' },
  'caption:strips': { label: '手帳の紙テープ', doc: '一行ごとに少し傾いたクリーム色の紙テープ。話している言葉に蛍光ペン。' },
  'caption:punch-box': { label: 'ショート動画の下地', doc: '太い縁取りの白文字。話している語の下を黄色い下地が滑っていく。文全体が弾んで出る。' },
  'caption:punch-color': { label: '縁取り語ハイライト', doc: '太い縁取りの白文字。話している語がハイライト色になり少し大きくなる。' },
  'caption:punch-roll': { label: '縁取りロールアップ', doc: '太い縁取りの白文字が下から転がり上がり、最後は下へ落ちていく。' },
  'caption:double-pop': { label: '二重縁取りポップ', doc: '墨とメインカラーの二重の縁取りの白文字が一語ずつ弾んで出る。' },
  'caption:soft-fade': { label: '柔らかい影のフェード', doc: '柔らかい影だけの白文字がゆっくりフェードイン・アウト。静かな画面に。' },
  'caption:frost-color': { label: 'すりガラス語ハイライト', doc: 'すりガラスの下地。話している語が淡い青になり大きくなる。ぼかしで入る。' },
  'caption:frost-underline': { label: 'すりガラス下線', doc: 'すりガラスの下地。話している語の下に線が引かれる。' },
  'caption:cinema': { label: '映画字幕', doc: '中くらいの太さ、少し広い字間、ぴったりした影の白文字。映画字幕のようにフェードする。' },
  'caption:cinema-type': { label: 'タイプライター字幕', doc: '映画字幕の文字が話すタイミングで一文字ずつ打たれ、カーソルが続く。' },
  'caption:slab-wipe': { label: '斜め色帯ワイプ', doc: '一行ごとに斜めに切ったメインカラーの帯に白文字。左から拭き取って出入りする。' },
  'caption:hollow-color': { label: '中抜き語ハイライト', doc: '輪郭だけの文字。話している語がハイライト色で塗られる。大きい所から縮んで入る。' },
  'caption:marker-fill': { label: '蛍光ペン点灯', doc: '一行ごとの蛍光ペンの下地に墨の文字。まだ話していない語は薄い。' },
  'caption:neon-fill': { label: 'ネオン点灯', doc: 'ピンクのネオン管の文字。話すまで暗く、話すと点灯し、話している語は青く光る。' },
  'caption:neon-wave': { label: 'ネオンウェーブ', doc: '青いネオン文字がゆるやかに上下に揺れる。グリッチで入る。' },
  'caption:gradient-zoom': { label: 'グラデーション大文字', doc: '白からオレンジのグラデーションの大きな文字に暗い硬い縁。話している語は青のグラデーション。大きい所から縮んで入る。' },
  'caption:gradient-one': { label: 'グラデーション一語ずつ', doc: '画面の中央にグラデーションの大きな語が一つずつ出る。' },
  'caption:extrude-one': { label: '一語ずつ', doc: '黄色い立体文字。画面の中央に一語ずつ弾んで出る。' },
  'caption:extrude-stretch': { label: '立体バウンス', doc: '黄色い立体文字が伸び縮みして入り、語が一つずつ弾む。' },
  'caption:sticker-pop': { label: '手書きステッカー', doc: '白い縁の手書きステッカー文字が一語ずつ落ちてきて弾む。強調は赤。' },
  'caption:sticker-wave': { label: 'ステッカーウェーブ', doc: '白い縁の手書きステッカー文字が四方から集まり、そのあと揺れる。' },
  'caption:heavy-rise': { label: '重い影', doc: '極太の文字に右下へ落ちる硬い影。ポスターのように。' },
  'caption:heavy-pop': { label: '重い影ポップ', doc: '硬い影の極太文字が一語ずつ弾んで出る。' },
  'caption:offset-color': { label: '版ずれ', doc: 'ハイライト色の文字の後ろに第二の色がずれて重なる、刷りずれのような見た目。話している語は白に。' },
  'caption:offset-glitch': { label: '版ずれグリッチ', doc: '版ずれ文字がグリッチで入り、拭き取られて消える。' },
  'caption:gold-zoom': { label: '金属ゴールド', doc: '光沢のある金のグラデーション文字に茶色の縁。大きい所から縮んで入り、話している語は明るい金に。' },
  'caption:gold-one': { label: '金の一語ずつ', doc: '画面中央に金色の大きな語が一つずつ出る。' },
  'caption:chrome-flip': { label: 'クロームフリップ', doc: '冷たい銀のクローム文字が回転して入る。' },
  'caption:chrome-color': { label: 'クローム語ハイライト', doc: 'クローム文字。話している語が青い金属の光沢に。' },
  'caption:flow-fade': { label: '流れるグラデーション', doc: '青とピンクのグラデーションが文字の中を流れ続ける。' },
  'caption:flow-wave': { label: '流れるウェーブ', doc: '黄色とオレンジの流れるグラデーション文字が揺れる。' },
  'caption:halo-fill': { label: 'ソフトグロー点灯', doc: 'ピンクの柔らかい光をまとった白文字。まだ話していない語は薄い。' },
  'caption:halo-blur': { label: 'ソフトグローぼかし', doc: '青い柔らかい光の白文字がぼかしで出入りする。' },
  'caption:duotone-pop': { label: 'ツートーンポップ', doc: '上が黄色、下がピンクの二色文字が一語ずつ弾む。' },
  'caption:duotone-slide': { label: 'ツートーンスライド', doc: '上が青緑、下が青の二色文字がスライドして出入りする。' },
  'caption:longshadow-drop': { label: 'ロングシャドウ落下', doc: '右下へ長い影を落とす文字が一語ずつ落ちてくる。' },
  'caption:longshadow-one': { label: 'ロングシャドウ一語ずつ', doc: '画面中央に長い影の大きな語が一つずつ。' },
  'caption:emboss-fade': { label: 'エンボスプレート', doc: '灰色のプレートに浮き彫りの文字。フェードで出入り。' },
  'caption:emboss-type': { label: 'エンボスタイプ', doc: 'エンボスの文字が話すタイミングで打ち出される。' },
  'caption:block-bounce': { label: 'ブロック文字バウンス', doc: '太い縁の白いブロック文字にメインカラーの厚い側面。語が一つずつ弾む。' },
  'caption:block-color': { label: 'ブロック文字ハイライト', doc: 'ブロック文字。話している語がハイライト色に。' },
  'caption:puffy-pop': { label: 'ぷっくり文字', doc: '丸く膨らんだピンクの文字に厚い白縁。一語ずつ弾む。' },
  'caption:puffy-wave': { label: 'ぷっくりウェーブ', doc: '水色のぷっくり文字が伸び縮みして入り、揺れる。' },
  'caption:tape-wipe': { label: 'マスキングテープ', doc: '一行ごとにミント色のマスキングテープと墨の文字。左から貼られ、はがれる。' },
  'caption:tape-color': { label: 'テープ語ハイライト', doc: 'アプリコット色のテープ。話している語がメインカラーに。' },
  'caption:postit-type': { label: '付箋', doc: '少し傾いた黄色い付箋に手書きの文字が話すタイミングで現れる。' },
  'caption:postit-flip': { label: 'ピンクの付箋', doc: 'ピンクの付箋が回転して入る。' },
  'caption:label-type': { label: 'ラベルライター', doc: '一行ごとの黒いラベルテープに白い浮き文字。話すタイミングで打たれる。' },
  'caption:label-stretch': { label: 'ラベル伸び縮み', doc: 'ラベルテープが伸び縮みして入り、縮んで消える。' },
  'caption:ransom-pop': { label: '切り抜き文字', doc: '一文字ずつ色、書体、角度の違う切り抜きの紙。一語ずつ弾む。' },
  'caption:ransom-scatter': { label: '切り抜き集合', doc: '切り抜き文字が四方から集まり、最後は落ちていく。' },
  'caption:rgb-glitch': { label: 'RGB グリッチ', doc: '赤とシアンがずれた白文字。グリッチで入り、ぼかしで消える。' },
  'caption:rgb-color': { label: 'RGB 語ハイライト', doc: 'RGB のずれた文字。話している語がハイライト色に。' },
  'caption:pixel-type': { label: 'ピクセルタイプ', doc: '8 ビットのゲーム文字が話すタイミングで打たれる。' },
  'caption:pixel-pop': { label: 'ピクセルポップ', doc: '8 ビット文字が一語ずつ弾む。強調は緑。' },
  'caption:vhs-type': { label: 'ビデオタイプ', doc: 'ビデオ画面の等幅大文字が話すタイミングで打たれる。' },
  'caption:vhs-fade': { label: 'ビデオ画面文字', doc: '色にじみのあるビデオ画面の白文字。グリッチで入る。' },
  'caption:terminal-type': { label: 'ターミナル', doc: '暗いコンソール枠の緑の等幅文字。話すタイミングで打たれ、カーソルが続く。' },
  'caption:terminal-color': { label: 'ターミナル語ハイライト', doc: 'ターミナルの緑文字。話している語が明るい白に。' },
  'caption:segment-type': { label: '液晶表示', doc: '灰緑の液晶パネルに暗い文字。話すタイミングで現れる。' },
  'caption:segment-roll': { label: '液晶ロールアップ', doc: '液晶パネルが転がり上がる。' },
  'caption:scanline-glitch': { label: '走査線', doc: '青い走査線の縞の文字。古い画面のようにグリッチで入る。' },
  'caption:scanline-fill': { label: '走査線点灯', doc: 'オレンジの走査線文字。まだ話していない語は薄い。' },
  'caption:news-wipe': { label: 'ニュースバー', doc: '左にメインカラーのブロックがある白いバーに黒文字。拭き取りで出入り。' },
  'caption:news-slide': { label: 'ニュースバースライド', doc: 'ニュースバーが左から滑り込み、話している語がメインカラーに。' },
  'caption:chat-pop': { label: 'チャットの吹き出し', doc: '話者 2、3 は右のメインカラー、それ以外は左の灰色の吹き出しで、弾んで出る。' },
  'caption:chat-type': { label: 'チャット入力', doc: '吹き出しの文字が話すタイミングで打たれる。' },
  'caption:lyric-fill': { label: '歌詞', doc: '柔らかく光るクラシックな明朝体の白文字。歌っている語は金色に、まだの語は薄い。' },
  'caption:lyric-blur': { label: '歌詞ぼかし', doc: '歌詞の行がぼかしで出入りする。' },
  'caption:dialog-type': { label: 'ゲームの会話枠', doc: '二重枠の紺のゲーム会話ボックス。話すタイミングで文字が打たれる。' },
  'caption:dialog-roll': { label: '会話枠ロールアップ', doc: 'ゲームの会話枠が転がり上がり、縮んで消える。' },
  'caption:comic-bounce': { label: 'コマ', doc: '太い黒枠と網点の白いコマが伸び縮みして入る。' },
  'caption:comic-pop': { label: 'コマポップ', doc: '青い網点のコマ。語が一つずつ弾む。' },
  'caption:chalk-type': { label: '黒板とチョーク', doc: '黒板のチョーク文字が話すタイミングで書かれる。' },
  'caption:chalk-fade': { label: '黒板フェード', doc: '黒板のチョーク文字がフェードで出入りする。' },
  'caption:comic-narration': { label: 'マンガのナレーション', doc: '黄色地に細い黒枠のマンガのナレーション枠。左上にワイプで現れる（マンガのページと一緒に）。' },
  'caption:desk-type': {"label":"デスクトップのメッセージ","doc":"パステルのレトロなウィンドウのようなメッセージ枠（ピンクのタイトル帯、濃い紫の枠、硬い影）、話すとおりに文字が打たれる（レトロなデスクトップと一緒に）。"},
  'caption:scrap-chip': {"label":"スクラップのメモ","doc":"小さく破いた色紙に白い明朝体、少し傾いている（スクラップブックの写真と一緒に）。"},
  'caption:mono-box': {"label":"モノボックス","doc":"小さな黒い枠に白い太字、縁のすぐ内側に白い細線（文字のフレームと一緒に；白地に黒なら color を黒、outline を白に）。"},
  'caption:editorial-bar': {"label":"エディトリアルバー","doc":"白地に黒い明朝体、左にテーマの第二色（accent2）の細い帯、左揃え：雑誌風のナレーション（マストヘッドや見開きと一緒に）。"},
  'caption:color-boxes': {"label":"単色の積み箱","doc":"一行ずつ直角のメインカラーの箱、太い黒の文字、左寄せ、ワイプで現れる：ビートに合わせた速いカットに（common.grade、common.poster と一緒に）。"},
  'caption:story-serif': {"label":"マスタードの明朝","doc":"マスタード色の明朝体を中央に、フェードイン・アウト、映像の上下の無地の色ブロック（common.backdrop solid とクリップの frame）の上に：絵本風・ウェス・アンダーソン風の旅行動画に（タイトルテンプレート storybook と一緒に）。"},
  'caption:pop-box': {"label":"黒枠の明朝","doc":"黒いボックスに太い白の明朝体、弾んで出る。ドーパミンカラーの購入品紹介、リスト、コーデに（タイトルテンプレート pop、common.popcard と）。"},
  'common.dachshund': { label: 'ダックスフント', doc: 'Tellcut のダックスフント。黒とクリーム色で、胴体がフィルムになっている。歩く、しっぽを振る、首をかしげる、座る、クリップのように体を二つに切る。フィルムのコマに映像を入れられる。ユーザーが Tellcut のダックスフントを求めたときだけ使う。' },
  'common.audiogram': {"label":"音声波形","doc":"話し声に合わせて動く波形。音声だけのポッドキャストやインタビューの画面を支える。音は素材の解析から読む：やり取り全体に 1 つ置けば音声トラックで流れている話し声を追う（tighten で詰めても合う。ほかの音声クリップがあるときは source で素材を指定）。1 つのクリップだけなら c.attach(c.effect('common.audiogram', { at, len, look }), clipId) で掛ければ、トリムや移動にもついていく。at は項目の頭を source の何秒に合わせるか。speakers [[開始, 終了, 何人目]]（素材の秒数、c.speechCaptions と同じ書き方）と names ['', 'A', 'B']：話し手が替わった瞬間に色と名札が替わる（既定はテーマの accent、accent2、colors で上書き）。hold（秒）は二つの音声や二人の話し手の間のそれより短いすき間で、前の人の色と名札を保つ。only（何人目）はその人が話すときだけ動き、色と名札はずっとその人のもの（一人に一つずつ置くとき）。カバーは art（プロジェクト内のファイル）か artSource＋artT（素材の 1 コマ）。正方形でないカバーは覆うように拡大し、はみ出しを中央から均等に切るので、大事なものは真ん中に。arts [[開始, 終了, ファイル], …]（素材の秒数、speakers と同じ）で時間ごとにカバーを替え、それ以外の時間は art。x y w h で位置と大きさ、nameX nameY で名札の中心、fadeIn fadeOut でフェードイン・アウト、gain と smooth で音量の調整。音声がまったくないときは見本の音量を描く。背景、番組タイトル、字幕は common.backdrop、common.header、common.caption で。"},
  'common.quiz': {"label":"クイズカード","doc":"バラエティ番組風のクイズの問題カード（紙のカードに太い黒枠）：上端のタブに問題番号（no）と難易度の星（stars 1〜5）。問題文は qt「開始,終了」秒の間に一文字ずつ打たれ、選択肢（options を | 区切り、2〜6 個、letters は前の記号）が shows の秒で一つずつ飛び出し、カードもそれに合わせて伸びる。reveal 秒で答え合わせ：不正解は赤い×で灰色に、正解（answer、0 から数える）は緑に光り、続いて不正解の行がたたまれ、正解が一行目に上がって右端にバッジが飛び出す（badge は絵文字か文字、badgeSource は素材の 1 コマを画像に：国旗、商品写真）。fact は答え合わせの後でカードの上に落ちてくる数字の小カード（factSub は出典）。y -1 で全選択肢があるときのカードの下端を下のセーフエリアに揃える。クイズ、当てっこ、雑学、選択問題に。効果音は common.pop（選択肢）、common.buzz（×）、common.ding（正解）、カウントダウンは common.countdown。"},
  'common.doodle': {"label":"手描きの落書き","doc":"マーカーで一画ずつ描かれていく手描きの落書き：data は描線リストの JSON [{a,b,p:[x,y,…],c,w,d,g,k,o}]——a から b 秒で描き終え、p は画面比率の座標、c 色、w 太さ、d 点線、g 同じグループで一緒に揺れる（jig で揺れ幅）、k [周期,位相,点いている割合] 描き終えた後に点滅、o 不透明度。boil で線を毎秒その回数だけ揺らし直す（wob で揺れ幅）。erase 秒から黒板消しが ex0〜ex1、ey0〜ey1 の範囲を上から下へ往復して消していく。ホワイトボード解説、ノート、図解、描いて見せるときに。出来合いの丸・矢印・チェックひとつなら common.pen、カット越しに形をなぞるなら common.pen の trace。効果音は common.scribble（線、黒板消し）。"},
  'common.healthbar': {"label":"ライブ見出し＋体力ゲージ","doc":"ライブ配信のアーカイブ風の見出しカード：上の行に赤い LIVE の丸ラベル（点が点滅）、灰色のアーカイブラベル、1 行のタイトル（どれも空欄にでき、全部空ならこの行はなし）、下の行に名前と区切りのあるゲームの体力ゲージ。stops「秒:体力 0〜100」をカンマ区切り：ダメージでカードが揺れ、白い残りゲージがゆっくり追いつく。回復するとマスが白く光る。右の状態の文字が体力に合わせて変わる（states「高,中,低,破壊」）。x と書いた時点でゲージが砕ける：マスが飛び散り、枠が赤い点線になり、最後の状態の文字がスタンプされる。ライブのハイライト、リアクション、チャレンジ、対決、持ちこたえられるか。y -1 で上のセーフエリアに付ける。効果音は common.hit か common.thud（ダメージ）、common.glass（砕ける）。"},
  'common.tabletop': {"label":"テーブル天板","doc":"映像の下に敷くテーブルの天板（静止）：look steel はステンレス（ヘアライン、上のランプの暖かい光のたまり、斜めの光の帯）、wood は木のテーブル（板、木目、左上の暖かいランプ）。color で天板の色、light でランプの色を変える。grill で角に炭火のコンロを埋め込む（鉄の輪、赤い炭火、焼き網：焼肉、鍋、屋台）。グルメ、開封、手作りの動画、映像パネルやレシートプリンター、カードを置くテーブルの地に。紙の机は common.paper。"},
  'common.leak': {"label":"ライトリーク","doc":"ライトリーク：光が角か片側から画面をゆっくり横切って消える（screen 合成で明るくするだけ、粒子なし、ちらつきなし）。travel 0 は (x, y) に留まってフェードイン・アウトし、少し呼吸する（角の夕日）。color、core、rose で色を変え、青と白にすると冷たい光。look で光の種類を変える（動く道筋と明るさは同じ）。"},
  'common.comic': {"label":"マンガのページ","doc":"映像がコマの中で流れるマンガのページ：白いコマ間、黒枠の斜めのコマ、コマが一つずつ滑り込み、コマの中に集中線も；layout でページを選び、panels で自分でコマを描く（一行一コマ「x,y x,y x,y x,y」画面比）；times と from は各コマの出る秒と方向（カンマ区切り、ないものは 0.6 秒おきに右左交互）；focus は一行一つの集中線「何コマ目|x,y|秒」；n コマ目のクリップは frame: comicWindow(n, 同じパラメータ)（@tellcut/plugin-common から）：メイントラックのクリップを一コマ、ほかのコマは c.beside；1 ページ 1 アイテム、次のページは次のアイテム；common.onomatopoeia の擬音、字幕テンプレート comic-narration、burst の網点と影、ページめくりの glitch と一緒に。"},
  'common.onomatopoeia': {"label":"擬音","doc":"マンガの擬音（ハハハ！、クンクン、Zzz…）：一文字ずつ出てくる大きな文字、画面のどこにでも斜めに置ける；look でその音の描き方を選ぶ；rise で一文字ごとに高くなる（上がっていく笑い声）、vertical は縦書き（rise は左右のずれになる）；color はメインの色、color2 は二つ目の色、ink は墨の色；英語は Bangers などのフォントにして字間を少し広げる；大きな文字と小さな英語を一画面に二つ置ける；common.comic、common.speedlines、ポップ音と合う。"},
  'common.desktop': {"label":"レトロなデスクトップ","doc":"パステルのレトロなパソコンのデスクトップ、動画全体に一つ：章ごとに色が変わるグラデーション（薄い方眼、流れるピクセルの雲、きらめき）、メニューバー（menu）と右上のプログラム名（app）、地球とフォルダー三つ、下のタスクバーに「★ スタート」と章ごとの .exe ボタン、今の章が光る（進み具合がタスクバーに出る）；chapters は一行一章「秒|名前|上の色|下の色」；common.window（最後に自分の章のボタンへ飛び込む）、common.popup、common.touch の cursor、字幕テンプレート desk-type と一緒に；誕生日、パーティー、思い出アルバム、「ファイルを開く」まとめ動画に。"},
  'common.window': {"label":"レトロなウィンドウ","doc":"レトロなパソコンのウィンドウ：タイトルバー（ファイル名 title、ボタン三つ、bar は lav・pink・mint・yellow か色）、濃い紫の枠、硬い影、content で中身を選ぶ；ポンと開き、最後（exit）は min でタスクバーの slot 番目（全部で slots、common.desktop の章と同じ）へ飛び込む、close で閉じる、max で maxAt 秒に画面上部いっぱいに広がる（高さ maxH、タイトルバーは消える）、none はそのまま；一章に数枚を斜めに重ねる；common.desktop、common.popup と一緒に。"},
  'common.popup': {"label":"レトロなダイアログ","doc":"レトロなパソコンのダイアログ：mode dialog は小さな「notice」ウィンドウに質問（text）とボタン二つ（buttons「メイン|もう一つ」、一つ目が黄色）、press 秒に pick 番目が押され、ポンと開いて最後に閉じる（「パーティー中止？［中止］［待つ］」）；mode sheet は締めのパネル：下からクリーム色の面が上がり、text を打ち、ボタン（buttons の一つ目）が press 秒に押されて done に変わり（「思い出を保存 → 保存しました ✓」）、ピクセルの紙吹雪；common.desktop、common.window、common.touch の cursor（ボタンに合わせる）と一緒に。"},
  'common.prints': {"label":"スクラップブックの写真","doc":"スクラップブックの一ページの写真：prints は一行一枚「秒|素材の秒|x,y,幅|傾き|幅:高さ|オプション」（x,y は画面比、幅は画面の短辺に対する比）、素材のその瞬間の静止画（source。src=素材 でその一枚だけ別の素材）に白いギザギザの縁と柔らかい影、少し大きく傾いたところから落ちて収まる；オプション tape（マスキングテープ、tape=#色）、clip（クリップ）、crop=x,y,zoom（クリップの crop やほかの写真カードと同じ切り取り：x、y は狙う点、zoom は 1 以上で拡大。素材の焼き込み文字を避ける。古い書き方 focus=x,y も読める）；一ページ一アイテム、全面の映像か紙（common.paper）の上に、後から来る大きな一枚が前の写真に重なる；common.scraps、字幕テンプレート scrap-chip、タイトルテンプレート scrapbook-card、common.wipe の tiles と一緒に；旅行・家族・ペットのスクラップブック、思い出アルバムに。"},
  'common.scraps': {"label":"紙片とテープ","doc":"写真の周りに貼るもの、scraps は一行一つ「秒|種類|x,y,幅,高さ|傾き|色」（x,y は画面比、幅と高さは画面の短辺に対する比）、それぞれの秒にポンと貼られる：paper 破いた紙片、dots 網点のマスキングテープ、tape 半透明のテープ、pin 丸い押しピン（幅＝直径）、clip クリップ、grid 画面全体の白い細い継ぎ目（位置は「列,行」、common.wipe の tiles の後も継ぎ目を残す）；common.prints、scrap-chip、scrapbook-card と一緒に。"},
  'common.monoframe': {"label":"文字のフレーム","doc":"画面の周りの白黒の文字フレーム：斜めの帯が、ink 地に paper の文字と paper 地に ink の文字で交互に並び、text がくり返し帯に沿ってゆっくり流れる（speed）、真ん中の角丸の窓から映像が見える（border はフレームの幅、画面の短辺に対する比）；win で窓を動かす（一行一つ「秒|x,y,幅,高さ」画面比、例えば真ん中の細い帯に縮めてから全体に広げる）、full は画面全体が文字；一章一アイテム、章ごとに文字を変える（都市名、テーマ、何語でも）；タイトルテンプレート mono-cycle、字幕テンプレート mono-box、章替えに common.wipe の vortex、common.filmstrip と一緒に；ストリート感のある旅行・都市・グルメのショート動画に。"},
  'common.filmstrip': {"label":"フィルムストリップ","doc":"一ページに 35mm フィルムが二本、一本は上へ一本は下へ流れ（speed は一秒に流れる画面の高さ）、コマには素材（source）の stills の秒の静止画（カンマ区切り、順番に）、両側にパーフォレーション、コマの間にエッジナンバー（label と 21A、22A…）；bg は地の色；映像の下に一ページの地として置き（layer: under）、字幕を上に；振り返り、「まだまだ覚えておきたいこと」、旅のまとめに；素材の焼き込み文字がないショットを選ぶ（コマはトリミングしない）。"},
  'common.masthead': {"label":"雑誌のマストヘッド","doc":"雑誌の表紙と裏表紙：mode front は全面の映像の上に、誌名（title）が一文字ずつ打たれ下に細線が伸び、上の両隅に小さな号の文字（issueL、issueR）、右に目次（contents、一行一つ）が一行ずつ、左下に斜体の一行（script）がワイプで現れる；mode back は裏表紙：color の一面に NEXT ISSUE／SEE YOU AGAIN、誌名、細線、号（sub）、真ん中に写真の帯（source の t 秒）、その下に斜体の一行（script）；旅行・都市・グルメの雑誌風のオープニングとエンディングに、間に common.spread、common.wordbands、タイトルテンプレート didone-full、字幕テンプレート editorial-bar；雑誌のレイアウトの窓で映像を流す（中ページ、リスト、表紙コピー付きの表紙、ボタン付きの裏表紙）なら common.magazine、masthead は全面の映像に誌名を重ねるか一色の裏表紙；common.magazine のパラメーター名も受け付ける：layout（cover＝front、back）、issue（右上）、no（左上）、accent（裏表紙の色）。"},
  'common.spread': {"label":"雑誌の見開き","doc":"雑誌の一ページ（映像の下に地として置き layer: under、字幕を上に）、写真は source の t 秒の静止画（fx、fy で寄せる）：layout swatch は「味のインデックス」のカラーページ：color の一面、上に欄の名前（header）と n／total、大きな写真、大きなセリフの数字（no）と名前（name）、右下にページと同じ色のスウォッチカード（色番号 code と色名 cname、デザイン上の文字でよい）；layout column はコラムページ：紙の上に左上の大きな数字、重なる写真カード、写真の下端にかかる白抜きの大きな単語（word）、右上に欄の名前、右下にページ番号（page）；一ページ一アイテム、次のページへそのまま切り替え（ページの効果音と一緒に）；料理リスト（一品一色）、街のいくつかの場所、カタログに；common.masthead、字幕テンプレート editorial-bar と一緒に；写真は静止画でページは映像の下：レイアウトの窓で映像を流すなら common.magazine；common.magazine の名前 kicker（＝header）も受け付ける。"},
  'common.wordbands': {"label":"ワードバンド","doc":"斜めの帯が続き、帯の上を斜体のセリフ文字がくり返し流れ、真ん中に白枠の写真（source の t 秒）：bands は一行一本「秒|文字|帯の色|文字の色」、それぞれの秒に前の帯の約二倍の幅で現れ、最後の帯は画面を覆う；bg は地の色；映像の下に一ページとして置く（layer: under）；EAT · EVERY · SINGLE · BITE のような一拍一語のスローガン、章の間のリズム、グルメ雑誌風の動画に；common.masthead、common.spread と一緒に。"},
  'common.grade': {"label":"単色グレード","doc":"下の映像の色をビートで切り替える：動画全体に一つ置き、steps「秒|bw／mono／none」（アイテム内の秒、一行一つ）で白黒、color 一色のモノトーン、元の色に（#色＝その色のモノトーン）；deep で色をもっと濃く：mono の区間に淡い tone を乗算し、明るい空まで染める（以前は common.wash を別に重ねていた）；字幕や文字のブロックはこの後に置けば色が変わらない；スポーツ・サイクリング・旅行の速いカットに、common.viewfinder、common.echo、common.poster と一緒に。"},
  'common.wash': {"label":"カラーウォッシュ","doc":"古いブロック（新しい動画は common.grade の deep）：steps の mono の区間に淡い色を乗算（multiply）で重ね、明るいところも色に染める；common.grade の後に同じ steps で置く（bw と none の区間はそのまま）。"},
  'common.viewfinder': {"label":"ファインダー","doc":"動画全体のファインダー：四隅に color の L 字（始めに伸びる）、左上にタイトル（title）と章の一行（chapters「秒|文字」、時間で切り替わる）、右上にルート（route）とカット数（cuts は各カットの秒をカンマ区切り、05 / 16 と表示）、左に目盛りと動画に合わせて下りていく針；小さな文字は飾りで字幕ではない；common.grade、common.echo と一緒に。"},
  'common.echo': {"label":"エコー文字","doc":"画面に太い長体の斜体の大文字（Anton）、まわりに同じ文字の白抜きが何層か（look で並べ方、echoes で層の数）；文字は少し大きく弾んでから落ち着く；label は文字の左上の小さな番号（01、02：場所や章）；幅が広すぎる文字は画面幅の 74% まで縮む；モノトーン（common.grade の mono）の区間は文字と白抜きが onMono の色になる（オレンジの画面にオレンジの文字は見えないため）：steps が空ならその時点の動画の common.grade に合わせ、自分の steps（このアイテムの秒；0|none＝変えない）があればそれに従う；スポーツや旅行のカットの地名や動作の言葉（RIDE、WALK、PARIS）。"},
  'common.poster': {"label":"単色ポスターページ","doc":"映像のない区間に置く一色（color）のページ：後ろに薄い巨大な白抜き文字がゆっくり流れ（ghost、空＝上の文字）、上に太い斜体の大文字（top）が落ちてきて、下の文字（bottom）がせり上がり、真ん中に写真カード（四隅に mark 色の L 字、右下に黒いハードシャドウ、入るときに少し縮む；photos は一行一枚「素材|秒|fx,fy」、複数なら every 秒ごとに切り替え、料理や名所を順番に）、カードの右に縦書きの小さな一行（side）、barcode があれば左下にバーコードと小さな一行（エンドカード）；章のページ、リストのページ、締めの KEEP / GOING.；字幕は下の文字の下に。"},
  'common.band': {"label":"斜めテープ","doc":"画面全体を斜めに横切る帯、帯の上に太い斜体の小さな文字（words、末尾に「 / 」を付けて区切り）がくり返し流れ、始めにさっと現れる；look で帯の見た目を選ぶ；angle と y で位置を決める；飾りで字幕ではない；KM BY KM、CITY BY CITY のようなリズムの言葉に、common.whoosh と一緒に。"},
  'common.binocular': {"label":"双眼鏡","doc":"双眼鏡でのぞく：画面を color（既定は黒）で覆い、左右に並んで重なる二つの丸窓だけを残す（shape binocular、spyglass は丸窓一つの単眼鏡）、窓の縁はやわらかく、始めに open 秒で小さく開く；cx、cy は中心（画面に対する比）、r は半径（画面の短辺に対する比）、overlap は二つの円の重なり（半径に対する比）；窓を主役に合わせるには、クリップの crop を変えるより cy／cx を動かすほうが簡単；字幕は窓の下の黒地に；のぞき見、遠くに見つけたもの（塀の上の猫、遠くの鳥、向かいの人）、絵本風・ウェス・アンダーソン風の旅行動画に。"},
  'common.photostack': {"label":"フォトスタック","doc":"無地のページ（bg）に角の丸い写真カードを上から積む：cards は一行一枚「素材|秒|ラベル|x,y,zoom」（動画はその秒のフレーム。x,y,zoom はクリップの crop と同じ切り取りで、x、y は狙う点、zoom は省略可）、every 秒ごとに一枚ずつ下から入り、細い縁（edge）とやわらかい影、右下に斜体のラベル（label 色、英語の小文字がきれい）；w はカードの幅（画面の短辺に対する比）、aspect は高さと幅の比、top は一枚目の上端；収まらないときは全体が自動で縮み、最後の一枚が字幕の上（セーフエリアの下端）で止まる；映像のない区間に置く（layer under）；一日に食べた・飲んだ・見たものをまとめて並べる、絵本風・ウェス・アンダーソン風の旅行動画に、common.shutter と一緒に。"},
  'common.popcard': {"label":"ポップカード","doc":"少し傾いた白い写真カード（ink 色の細い枠、右下にずらした shadow 色の影）が弾んで入り、中で自分のショットを再生する：shots は一行一ショット「秒|素材|素材の秒|x,y,zoom|ラベル|still」（秒は項目の頭から、次の行まで再生、x,y,zoom は切り抜き、still は静止画）、カットごとにカードが軽く弾む。ラベルは左上の角（pillSide right で右上）の pill 色のカプセルで、変わったときだけ弾む。x、y、w、h はカードの枠（画面比）、tilt は傾き。ページ全体がカードのときはメイントラックにクリップを置かず、下に common.backdrop（pattern words）を敷く。購入品紹介、開封、コーデ、一品ずつの紹介（ドーパミンカラー、common.sticker、common.badge の box、タイトルテンプレート pop と）。小さなカードを並べれば締めのまとめに。"},
  'common.sticker': {"label":"フラットステッカー","doc":"小さなフラットステッカー。太い ink の線と右下にずらした影、小さく傾いて弾んで入り、軽く揺れる。x、y は中心、size は幅（画面の短辺に対する比）。カードの角やタイトルの横に（ドーパミンカラーの購入品紹介、リスト、Vlog、common.popcard と。文字入りの爆発シールは common.burst の shadow、カーソルは common.touch の cursor）。"},
  'common.grid': {"label":"クリーングリッド","doc":"すっきりしたグリッドのレイアウト：無地の地（gutter）に、細い隙間で区切った角または角丸のセルをいくつか置き、各セルが自分のショットを再生して一つずつ現れる（reveal：fade フェード、scale 拡大、slide スライド、wipe ワイプ。映像もセルと一緒に動く）。layout で配置を選ぶ（横長の動画では左右に並ぶ）。boxes で自分のセルを書ける（一行一つ「x,y,w,h」画面比率）。shots は一行一セル「素材|素材の秒|x,y,zoom|still」（セルが現れたとき素材の秒から再生、still は静止、行のないセルはサンプル画像）。times と from は各セルが現れる秒と方向（カンマ区切り。書いていないものは 0.4 秒ごと、左右交互）。exitAt のあとセルは来た方向へ戻る。セルの映像には音がない（音は BGM、ナレーション、トラック上のクリップで）。ページが全体を覆うときはメイントラックを空けてよい。マンガページとの違い：枠線も集中線もない。まとめ、ビフォーアフター、リスト、複数の場所を一度に。"},
  'common.slant': {"label":"斜めの帯","doc":"画面を 2〜3 本の全面の帯に斜めに分ける（count。斜めの辺は平行で angle 度）。各帯が自分のショットを再生し、映像ごと横から交互に飛び込んでくる。縦長の動画では上下に重ね、横長では左右に並べる。帯の間に細い継ぎ目（seam、0＝なし）、まだ帯が来ていないところは bg 色。shots は一行一本「素材|素材の秒|x,y,zoom|still」（帯が現れたとき素材の秒から再生、行のない帯はサンプル画像）。times と from は各帯が現れる秒と方向（カンマ区切り。書いていないものは 0.35 秒ごと、縦長は左右交互、横長は上下交互）。labels は各帯の角の小さなタグ（カンマ区切り、例 BEFORE,AFTER）。exitAt のあと帯は滑って戻る。帯の映像には音がない（音は BGM、ナレーション、トラック上のクリップで）。ページが全体を覆うときはメイントラックを空けてよい。ビフォーアフター、スポーツ、三連発のオープニングに。"},
  'common.postage': {"label":"切手","doc":"ミシン目の縁の切手が落ちてくる（または横から滑り込む）。切手の絵柄の中で自分のショットを再生する（source 素材、from 素材の秒、crop 切り抜き、still 静止。素材がないときはサンプル画像）。映像は切手と一緒に動き、止まったあとも tilt の小さな傾きを保つ。絵柄の下の余白に value 額面と line 小さな一行を印刷し、markAt に丸い消印（place 地名、date 日付）が右下の角に押される。backdrop は下地（desk 木の机、color 単色、none 透明）。切手の映像には音がない。common.flatlay（3D の机：ポストカード、写真立て。ポストカード裏の切手はカードに貼った静止画）、common.postmark（消印だけ）、common.stamp（ゴム印）と違い、一枚の平らな切手の絵柄で映像が流れ、映像の上に透明に重ねられる。いくつかの物を 3D の机に並べるなら flatlay、切手一枚で一画面を持たせるならこれ。旅の一か所、思い出の一コマに。"},
  'common.letterbox': {"label":"シネスコ帯","doc":"映画の黒帯が上下の端から滑り込み、真ん中に ratio の縦横比の画面を残す（0＝自動：横長 2.39、縦長は正方形）。帯には字間を広げた title と小さな sub を置く：縦長の動画では二行とも上の帯の、プラットフォームの上の安全域より下（帯が浅いときは文字なし）。横長ではタイトルを下の帯の中央、小さな文字を上の帯に。titleAt は文字が浮かぶ秒（-1＝帯が揃ったとき）。outAt のあと帯は戻る。common.film の letterbox パラメータと違い、帯が動き、文字を載せる。映画らしいオープニング、章タイトルに。"},
  'common.bounce': {"label":"弾む大きな文字","doc":"動く大きな文字：items は 1 行に 1 フレーズ「秒|文字|大きさ|色|x|y|モード|オプション」、文字が拍に合わせて一つずつ入ってくる。モード drop は落ちてきてつぶれて弾む、pop は何もないところから弾け出る、slam は大きいところから叩きつける、float は浮かび上がってゆっくり漂う、sway は弾け出て揺れる、knock は切り抜き文字：色紙（sheet、sheetTo まで）が画面を覆い、文字が穴になって下の映像が見える。オプション jump=秒/秒 で跳ねる、sink=秒 で【強調】文字が画面の下へ落ちる、out=秒 で縮んで消える、wob=1 で着地後に一度震える、stagger=秒 は文字の間隔、shadow=1 は影、scrim=1 は文字の後ろの暗い帯、emph=色 は強調の色。大きさは短辺 1080 基準の px（幅が足りなければセーフエリアに収まるよう縮む）、色は空欄＝color、hl＝強調色。宣言、ブランド動画、スローガン、拍に合わせた文字、冒頭のフック。"},
  'common.token': {"label":"コインステッカー","doc":"手描きの金貨ステッカー（白いステッカーの縁、ゆっくり浮かぶ）と、横の白いテープにマーカーで書いたラベル。steps は1行1ステップ「秒|ラベル|コインの文字|none/miss/made」：ラベルかコインの文字が変わるとコインが裏返って新しい面になり、miss は赤いバツ、made は緑のチェックを一画ずつ描く（ラベルの文字も緑に）。enter で飛び出して登場、exit で最後に縮んで消える。何回目の挑戦、願いごと、成功・失敗、ポイント集め、ステージ。common.coin（コイン投入）、common.error（失敗）、common.ding（成功）と合わせる。"},
  'common.heading': {"label":"タイトル","doc":"タイトル（作品名、章、地名、エンディング）：見た目（style：字幕の見た目とタイトル専用のもの）、レイアウト、背景、登場、退場、色、フォントを自由に組み合わせる。よく使う組み合わせは名前付きのタイトルテンプレート（npm run tellcut -- catalog TTL で一覧、template に id、作品全体は c.titleTemplate）。kicker はタイトルの上の小さな一行、sub は下の小さめの一行。【語】はハイライト色。layout：center 中央、top 上、bottom 下、lower 左下（大きめのテロップ位置）、left 左寄せ中央、corner 右上に小さく、full セーフエリアの幅いっぱいに拡大。backing：band 暗い帯、scrim 画面全体を暗く、blur 画面全体をぼかす、card 単色のカード、rules 上下の細い線、bar 左の色帯、black 真っ黒。専用の登場：track 字間が詰まる、mask 下から現れる、open 中央から開く、focus ぼかしからピントが合う、rule 線が先に引かれてから文字。退場：spread 字間が広がる、sink 下へ沈む。"},
  'title:plain-center': {"label":"中央の白文字","doc":"中央に白い文字、フェードで出入り。画面がすっきりしているときに一番控えめ"},
  'title:doc-rules': {"label":"ドキュメンタリーの細線","doc":"明朝体。上下の細い線が中央から引かれてから文字が出る。ドキュメンタリーや人文系の作品名、章に"},
  'title:lower-bar': {"label":"左下のカラーバー","doc":"左下に太いゴシック、左にメインカラーの帯、ワイプで登場。地名、人名、段落タイトルに"},
  'title:neon-scrim': {"label":"暗くしてネオン","doc":"画面全体を暗くし、中央のネオン文字がぼかしからピントが合って光る。夜景、パーティー、オープニングに"},
  'title:gold-black': {"label":"黒地に金文字","doc":"真っ黒な画面に金色のセリフ体、ぼかしから現れ字間が広がって消える。オープニング、エンディング、式典に"},
  'title:sticker-bounce': {"label":"ステッカーが弾む","doc":"白縁のステッカー文字が丸ごと弾んで登場、縮んで退場。気軽な vlog、開封、グルメに"},
  'title:vhs-corner': {"label":"ビデオの隅の文字","doc":"右上に小さなビデオカメラの画面文字、一文字ずつタイプ。レトロ、ホームビデオに"},
  'title:cinema-band': {"label":"映画の暗い帯","doc":"画面を横切る暗い帯に細い文字、字間が詰まって登場し広がって退場。旅行映像、映画風のタイトルに"},
  'title:serif-focus': {"label":"明朝体のピント","doc":"少し字間を空けた明朝体が、ぼかしからピントが合って現れる。人文系、ドキュメンタリー、グルメの作品名に"},
  'title:spaced-track': {"label":"字間の広いタイトル","doc":"細い大文字を広い字間で。字間が詰まって登場し、広がって退場。映画風の英語タイトル、旅行映像に"},
  'title:stack-left': {"label":"雑誌風の積み重ね","doc":"1行目は大きく、続く行は半分の大きさのハイライト色、左寄せで下から現れる。雑誌風、リストの見出しに"},
  'title:sign-glitch': {"label":"ネオン看板","doc":"暗い看板にネオン管の光る文字、グリッチで登場。夜市、バー、店名に"},
  'title:vintage-card': {"label":"レトロなカード","doc":"暗いカードにクリーム色のクラシックなセリフ体、ゆっくり上がる。老舗、家族の物語、思い出に"},
  'title:seal-stamp': {"label":"二重線の印","doc":"メインカラーの二重線の枠の印、少し傾いて、大きいところから押される。認定、結論、おすすめに"},
  'title:split-open': {"label":"上下ツートーン","doc":"文字の上半分が白、下半分がハイライト色。中央から開いて登場、下へ沈んで退場。スポーツ、ストリート、オープニングに"},
  'title:giant-full': {"label":"画面いっぱいの大文字","doc":"いちばん太い巨大な文字が画面の幅いっぱいに、深くやわらかい影、ぼかしからピントが合う。オープニングの一語、章の数字に"},
  'title:script-lower': {"label":"手書きの下線","doc":"手書き文字にハイライト色の下線を一筆、左下にワイプで登場。vlog、手帳風の地名と日付に"},
  'title:ribbon-top': {"label":"リボンのタイトル","doc":"両端に切れ込みのあるメインカラーのリボンに一行ずつ、上で弾んで登場。イベント、お祝い、リストの見出しに"},
  'title:chalk-board': {"label":"黒板とチョーク","doc":"木枠の黒板にチョークの文字、フェードイン。授業、教室、メニューに"},
  'title:gradient-full': {"label":"グラデーションの大文字","doc":"グラデーションで塗った大きな文字が画面の幅いっぱいに、大きいところから縮んで落ちる。オープニング、カウントダウン、大事な数字に"},
  'title:chrome-black': {"label":"黒地にクローム","doc":"真っ黒な画面にクロームの金属文字、ぼかしからピントが合い、字間が広がって退場。テック、車、製品発表のタイトルに"},
  'title:frost-blur': {"label":"すりガラス","doc":"背景をぼかし、霧のような白い文字が下から現れ、下へ消える。街、カフェ、暮らしの章立てに"},
  'title:slab-lower': {"label":"左下の色ブロック","doc":"ベタ塗りの色ブロックに乗せた文字を左下に、ワイプで出入り。人名、地名、店名に"},
  'title:marker-left': {"label":"蛍光ペンの見出し","doc":"左寄せの文字の後ろに蛍光ペンのひと塗り、下から現れる。ノート、授業、リストの段落に"},
  'title:duotone-open': {"label":"ずれた二色","doc":"二色をずらして重ねた文字が中央から開く。音楽、ストリート、スポーツに"},
  'title:halo-scrim': {"label":"暗がりに光の輪","doc":"画面を暗くし、柔らかく光る文字がぼかしからピントが合う。夜、思い出、やさしいオープニングに"},
  'title:extrude-bounce': {"label":"立体ポップ","doc":"厚みのある立体文字が弾んで登場、縮んで退場。ゲーム、子ども、軽いオープニングに"},
  'title:longshadow-top': {"label":"長い影","doc":"斜めに長い影を引くフラットな文字が上で下から現れる。解説、科学、ハウツーに"},
  'title:pixel-top': {"label":"ピクセルゲーム","doc":"ピクセル文字が上で一文字ずつ打ち出される。ゲーム、ステージ、チャレンジに"},
  'title:terminal-left': {"label":"ターミナル","doc":"黒地に緑のターミナル文字を左寄せで打ち出す。プログラミング、テック、ハッカー風に"},
  'title:rgb-scrim': {"label":"色ずれグリッチ","doc":"赤と青にずれた文字が暗くした画面にグリッチで現れる。電子音楽、テック、スリラーに"},
  'title:ransom-bounce': {"label":"切り抜き文字","doc":"新聞の切り抜きを貼った文字が一文字ずつ弾んで登場。お笑い、ミステリー、いたずらに"},
  'title:tape-top': {"label":"マスキングテープ","doc":"マスキングテープに貼った文字を上に、伸び縮みして登場。手作り、手帳、日常の vlog に"},
  'title:postit-left': {"label":"付箋","doc":"付箋の文字が左寄せでめくれて登場。やること、リマインダー、勉強ノートに"},
  'title:ticket-bottom': {"label":"チケットの半券","doc":"チケットの半券の形の文字が下でせり上がる。旅、映画、展覧会に"},
  'title:punch-zoom': {"label":"インパクト","doc":"太く迫力のある文字が大きいところから叩きつけられる。要点、どんでん返し、結論に"},
  'title:credit-bottom': {"label":"クレジット","doc":"下に字間の広い細い一行、字間が詰まって現れ、広がって消える。スタッフ、エンドクレジット、出典に"},
  'title:serif-card': {"label":"白いカードに明朝","doc":"クリーム色のカードに濃い明朝体、ゆっくりせり上がる。本、展覧会、穏やかなドキュメンタリーに"},
  'title:neon-rules': {"label":"ネオンと罫線","doc":"上下二本の細い線を先に引き、ネオン文字が灯る。夜景、バー、イベントに"},
  'title:giant-mask': {"label":"特大文字のリビール","doc":"画面幅いっぱいの特大文字が下から現れ、下へ沈む。章の番号、一語のオープニングに"},
  'title:scrapbook-card': {"label":"スクラップのタイトルカード","doc":"クリーム色のカードに朱色の太い明朝、上下に二重線、左上から青緑の紙片がのぞき、少し傾いている：スクラップブック、旅、家族の動画のタイトルに。"},
  'title:mono-cycle': {"label":"入れ替わる白抜き","doc":"幅の広い幾何学的な大文字を重ね、一行だけ塗り、ほかは白抜き、塗りの行が 0.45 秒ごとに下へ移り、グリッチで入る：旅行・都市・ストリートのタイトルや章に（文字のフレームと一緒に）。"},
  'title:didone-full': {"label":"雑誌の巨大見出し","doc":"濃い色の巨大なハイコントラストのセリフ体、一行目は小さな冠詞（THE）、二行目は画面幅いっぱい（英語がいちばん映える、一行目は二行目より短く）、下から現れる：都市・ランドマーク・グルメ特集の見出しに（雑誌のマストヘッドと一緒に）。"},
  'title:storybook': {"label":"絵本のタイトル","doc":"マスタード色の太いセリフの大文字、右下に濃いハードシャドウ；上の大文字のない行（a day / in、simply）は一回り小さい斜体の導入、下の一行は斜体の小さな文字：絵本風・ウェス・アンダーソン風のタイトルや章（a day in KYOTO、simply BLOOM.）、common.binocular、common.photostack、字幕テンプレート story-serif と一緒に。"},
  'title:story-card': {"label":"絵本のタイトルカード","doc":"一面の青緑に二本のマスタード色の細い枠、その中に絵本のタイトル（斜体の導入 and finally,、太いセリフの大文字、下に斜体の小さな一行 — the last stop —）：最後の一軒や次の章のタイトルカード（backColor で地の色、accent で枠の色を変える）。"},
  'title:fin': {"label":"絵本のエンディング","doc":"黒地にマスタード色の斜体の fin.、その下に小さな一行（街の名前、動画の名前）：絵本風のエンディング。"},
  'title:pop': {"label":"ドーパミンのカラーブロック","doc":"鮮やかなフラットなブロックに太い明朝体、横に並べて少し傾ける：最後の行（ブロック）はアクセント色に白、それより前の行は黒地にハイライト色、CJK 文字のない行は Playfair の太い斜体。kicker は黒い小さなブロックに白文字。一文字ずつ弾んで出る。ドーパミンカラーのタイトル、セクション、エンディングに。accent で最後のブロックの色を変える。common.backdrop の words、common.popcard、common.sticker、字幕テンプレート pop-box と。"},
  'common.flatlay': {"label":"3D デスク","doc":"three.js で描く本物の 3D の机：ポストカード、ポラロイド、写真立て、古いテレビ、カードがリネン、大理石、コンクリート、ベルベットの上に置かれ、窓の光と木の葉の影がゆっくり揺れる。柔らかい影と浅い被写界深度つき。それぞれの写真面は自分のショットを再生し（音なし）、上から落ちる、横から滑り込む、3D で裏返る。カメラはゆっくり寄る、真上に上がる、または一枚の写真に飛び込んで画面を覆う。元の音が要るとき、飛び込んだあとメイントラックに引き継ぐときは c.flatlayClip でそのショットを揃えて置く。複数の物は objects（JSON の配列、それぞれ kind で物を選ぶ）に。x、y は机の単位（机の中央が 0、y は上向き；9:16 で見えるのは ±1.2 × ±2.0、16:9 は ±3.0 × ±1.6）、rot はラジアン（正＝反時計回り）。surface none は透明な机で、動画の上に重なる。"},
  'common.candles': {"label":"ローソク足チャート","doc":"値動きのチャート動画のひとそろい（9:16 向け）。mode で chart、header、tally、card、big に分かれる。データはプロジェクトの CSV（data：media/data/ndx.csv のようなファイルのパス、または CSV の文字そのもの。1 行に「日付,始値,高値,安値,終値」。見出し行や Adj Close、Volume などの余分な列があっても大丈夫。「日付,終値」だけなら平らな足になる。空欄はサンプルの架空データ）。keys は 1 行に「動画の秒|日付|表示する日数か all」で、各瞬間にどの日まで描くか、画面に何日分見せるかを決める（chart、header、tally に同じものを渡せばいつも一致する）。keys も他の秒数もすべて動画の秒で、項目が何秒から始まっても変わらない。shocks はどのモードにも同じ秒数を渡すと、その秒に一緒に揺れる（画面全体が跳ねる）。updown は red が赤で上昇・緑で下落（台湾）、green が緑で上昇・赤で下落。top は DOM のモードの上端（画面の高さに対する割合、-1 は各モードの既定の位置）。株、指数、仮想通貨の価格、為替、長期の推移、暴落の振り返り。効果音は common.thunder、common.impact、common.explode。"},
  'common.lens': {"label":"レンズ","doc":"上に何かを重ねるのではなく、下の映像そのものを曲げるレンズ（映像と、下のトラックのブロックや字幕もいっしょに曲がる）。shape は circle 円、box 四角、full 画面全体。strength は各 look の強さで、enter／exit で強さを 0 から伸ばしたり、行き過ぎて戻したりする。注意：レンズの下の字幕もいっしょに曲がる。字幕をくっきり見せたいときは、レンズを字幕より下のトラックに置く。ブレンドするブロックとは重ねて使えない。プレビューで見えるのは Chromium 系ブラウザ（Chrome、Edge）だけ。書き出しは常に Chrome を使う。エディターの「Preview: Smooth」でも見えない（そこではモザイクも何も隠さない）。「Preview: Full」と書き出しでは見える。"},
  // ブロックのテンプレート（engine templates.ts）、キーは <type>#<テンプレート id>
  'common.glitch#signal-loss': {"label":"電波障害","doc":"監視カメラの映像、電波の乱れ、回想に入るところに：細い走査線と下へ流れる明るい帯。look scan だけより頻繁に、大きく画面全体が横に跳ぶ。"},
  'common.glitch#rgb-hit': {"label":"強拍の色ずれ","doc":"音楽の強拍、驚く一瞬に：乱れるたびに赤と青の版が大きく離れる。look rgb だけより激しい。"},
  'common.glitch#data-break': {"label":"データ破損","doc":"テクノロジー、ハッキング、システムエラーに：背の高い長方形がたくさん横にずれ、シアンとマゼンタに色づく。"},
  'common.glitch#soft-tear': {"label":"控えめな裂け目","doc":"サスペンスの盛り上げ、目立たないノイズに：ときどき色のない反転した細い帯が 2〜3 本走るだけで、主役を邪魔しない。"},
  'common.glitch@tear': {"label":"反転した横帯","doc":"画面から反転した横帯が何本かちぎれる（既定）。場面転換やドッキリの一瞬に。bands は本数、maxHeight は最大の高さ、tint でシアン／マゼンタに色づく。"},
  'common.glitch@scan': {"label":"走査線","doc":"細い走査線と、ゆっくり下へ流れる明るい帯、ときどき画面全体が横に数 px 跳ぶ。監視カメラ、古いテレビ、ハッカーの画面に。"},
  'common.glitch@rgb': {"label":"色ずれ","doc":"下の映像の赤と青が本当にずれる。ふだんはわずかな色ずれ、走ると大きく離れる。音楽、ビート、電波不良に。"},
  'common.glitch@block': {"label":"ブロックのずれ","doc":"下の映像の長方形がいくつか横にずれ、シアン／マゼンタに色づく。データ破損、切り替え、壊れた感じに。bands はブロックの数。"},
  'common.leak#prism-sweep': {"label":"虹色の光の帯","doc":"音楽のパート、青春の思い出、夢のようなつなぎに：幅の広い虹色の光の帯が左から画面全体を横切る。いつもより明るく大きい。"},
  'common.leak#bokeh-night': {"label":"夜景のボケ","doc":"夜景、夜市、お祭り、温かいエンディングに：たくさんのぼけた丸い光が画面に留まり、ゆっくり明るくなったり暗くなったりする（横切らない）。"},
  'common.leak#flare-top': {"label":"上のレンズフレア","doc":"映画のようなオープニング、逆光のカット、SF のタイトルに：とても明るい横長の光の筋が画面の上、やや右に留まり、反対側までゴーストの光の輪が並ぶ。"},
  'common.leak#warm-corner': {"label":"隅の暖かい光","doc":"思い出、家族、静かなインタビューに：淡い暖色の光が左上の隅に留まり、少しだけ動いて、最後までそこにある。"},
  'common.leak#sweep-fast': {"label":"すばやい光の横切り","doc":"2 つのカットのつなぎに：小さく明るい暖色の光が左端から右端の外まで一気に横切る。"},
  'common.leak@glow': {"label":"暖かい光","doc":"大きな暖色の光に淡い光の芯、後ろにローズ色の光がつく（既定）。思い出、旅のアルバム、ページめくりの着地、表紙、冒頭や最後の暖かいつなぎに。"},
  'common.leak@prism': {"label":"虹色の帯","doc":"斜めの虹色の光の帯が横切る（glow の 1.8 倍遠くまで動く）。ガラス越しの日差し、夢のような、青春、音楽に。"},
  'common.leak@bokeh': {"label":"玉ボケ","doc":"十数個のぼけた丸い光がゆっくり漂い、明るくなったり暗くなったりする。夜景、お祭り、ロマンチック、温かいエンディングに。seed で位置が変わる。"},
  'common.leak@flare': {"label":"レンズフレア","doc":"明るい点を通って横に長く伸びるアナモルフィックの光の筋と、画面の中心を通る線上の小さなゴースト。映画的、SF、テック、オープニングに。streak はその色で、既定は青白。"},
  'common.film#super8-home': {"label":"昔のホームムービー","doc":"子どものころ、親の世代のホームビデオ、レトロな結婚式に：映写機で映した 8 ミリの家庭用フィルム。look super8 だけより暖かく、粒子が粗く、ビネットが重い。"},
  'common.film#vhs-tape': {"label":"90 年代のビデオテープ","doc":"90 年代のビデオテープ、レトロな vlog、テープを替えたあとの思い出に：look vhs だけより濃い走査線と暖かい色。始まってすぐトラッキングノイズの帯が上から下へ流れる。"},
  'common.film#print-zine': {"label":"雑誌の網点","doc":"雑誌、ポスター、ポップアートのパートに：画面全体がやや粗い印刷の網点になる。ビネットなし。"},
  'common.film#cinema-scope': {"label":"シネマスコープ","doc":"16:9 の横長の動画向け。映画のような旅の動画、タイトルに：上下に 2.39:1 の黒帯、淡い粒子とやわらかいビネット（縦長の画面では黒帯で中央の細い帯しか残らない）。"},
  'common.film#heavy-grain': {"label":"粗い粒子","doc":"ストリートスナップ、ドキュメンタリー、荒々しいパートに：とても粗くコントラストの強い粒子が 1 秒に 12 回だけ変わる。高感度フィルムのよう。"},
  'common.film@grain': {"label":"フィルムの粒子","doc":"画面全体の細かい粒子と柔らかいビネットだけ。控えめなフィルム感、ノスタルジックな段落に。"},
  'common.film@vhs': {"label":"ビデオテープ","doc":"家庭用ビデオテープ：固定の走査線、暖色寄り、浮いた黒、ビネット。tracking「秒:長さ:強さ」の区間ではトラッキングノイズの帯が上から下へ流れる。テープ交換、回想、古いビデオ、DV に。common.whirr と組み合わせる。"},
  'common.film@super8': {"label":"8 ミリフィルム","doc":"映写された 8 ミリの家庭用フィルム：暖色寄り、明るさがコマごとにちらつき、重めのビネットと角の丸い黒い枠、縦の傷が現れては消え、ほこりや毛が 2 コマごとに変わり、枠全体がわずかに揺れる。昔のホームムービー、子どものころ、親の世代の思い出、レトロな結婚式に。common.whirr や映写機の音と組み合わせる。"},
  'common.film@print': {"label":"印刷の網点","doc":"印刷の網点：画面が斜めに並んだ網点になり、暗いところは点が大きく明るいところは小さく、色もそれぞれの点に分かれ、うっすら紙の色が乗る。雑誌、新聞、切り抜き、ポップアート、レトロなポスターに。dot は網点の間隔。ビネットなし。下にある文字も網点になるので、字幕はその上に置く。"},
  'common.speedlines#manga-focus': {"label":"マンガの集中線","doc":"驚き、人や物を強調するときに：密な集中線が四辺から中心へ迫り、真ん中に主役のための大きなきれいな楕円を残す。"},
  'common.speedlines#rush-right': {"label":"右へ突進","doc":"走る、運転する、速く動くときに：画面全体の平行なスピード線が右へ飛ぶ。"},
  'common.speedlines#fall-down': {"label":"下へ落下","doc":"落ちる、急降下、飛び降りるときに：長い直線が画面全体で下へ飛ぶ。"},
  'common.speedlines#burst-center': {"label":"中心から爆発","doc":"登場、ダッシュ、大きな発表に：中心のすぐ近くから長い線がたくさん放射する。デフォルトより密で、中心に近いところから始まる。"},
  'common.speedlines@radial': {"label":"放射線","doc":"(x, y) の一点から外へ放射するマンガのスピード線。だんだん長くなり、わずかにちらつく（inner は始まりの半径、length は線の長さ）。爆発カードの後ろ、驚きや転換の一瞬に。"},
  'common.speedlines@focus': {"label":"集中線","doc":"マンガの集中線：太い黒いくさびが画面の四辺から (x, y) へ向かい、周りにきれいな楕円を残す（inner がその大きさ）、線は震える。衝撃、登場、顔のアップ、「こいつだ！」。"},
  'common.speedlines@streak': {"label":"平行スピード線","doc":"長さも太さもばらばらな平行のスピード線が画面全体を angle の方向へ飛んでいく。ダッシュ、急ぐ、早送り、車窓。映像の上では白が見やすい。"},
  'common.sparkle#confetti-rain': {"label":"紙吹雪の雨","doc":"お祝い、受賞、誕生日に：mode confetti の倍の色とりどりの紙が上から降り、画面をいっぱいにする。"},
  'common.sparkle#glint-once': {"label":"一度きりのきらめき","doc":"商品の見どころ、ジュエリー、きらりと光る歯に：とても大きな十字の光が現れ、少し回って消える。一度だけ。"},
  'common.sparkle#star-burst': {"label":"星の大爆発","doc":"正解、変身、レベルアップに：デフォルトより多くの星が一点からはじけ、より遠くまで飛ぶ。"},
  'common.sparkle@burst': {"label":"星がはじける","doc":"四角い星が (x, y) の一点から弾けて飛び散る（spread は飛ぶ距離）。正解、サプライズ、強調の一瞬。"},
  'common.sparkle@twinkle': {"label":"瞬く星","doc":"四角い星が (x, y) の周りに散らばり（spread は範囲）、ずっと瞬く。高級感、夢のような場面。"},
  'common.sparkle@confetti': {"label":"紙吹雪","doc":"色とりどりの紙片が画面の上から降ってきて、くるくる回り左右に揺れる。色は color と theme の accent、accent2、hl。アイテムの間に次々と降る（x、y、spread は使わず、count 一つで紙 4 枚）。誕生日、受賞、完成、発表、パーティー。"},
  'common.sparkle@glint': {"label":"十字の光","doc":"(x, y) の一点から長い十字の光が伸び、大きくなり、少し回って消える。アイテムの最初の 1 秒のうち（count と spread は使わない）。商品、金属、ジュエリー、新車、刃物が「キラッ」と光る。"},
  'common.countdown#flip-clock': {"label":"パタパタ時計","doc":"新製品発表のカウントダウン、年越しに：パタパタ時計が 1 枚ずつめくれる。最後も数字のまま。"},
  'common.countdown#film-leader': {"label":"昔の映画のリーダー","doc":"レトロなオープニング、昔の映画の始まりに：画面の幅近くある大きな円盤で、針が 1 秒に 1 回転しながら 5 から 0 まで数える。最後も数字のまま。"},
  'common.countdown#slant-go': {"label":"斜体の GO","doc":"スポーツ、チャレンジの開始に：とても大きな斜体の数字と右側の弧。最後は GO!"},
  'common.countdown#ring-corner': {"label":"隅の小さなタイマー","doc":"クイズ、制限時間のある課題に：小さなリング型タイマーが画面の上に留まり、本編を邪魔しない。最後も数字のまま。"},
  'common.countdown@ring': {"label":"リング","doc":"大きな数字が1つごとに弾み、外側の輪が回りきる（accent は輪の色、ink は数字の縁取り、ring を切ると輪なし）：クイズ、制限時間のある課題に。"},
  'common.countdown@slant': {"label":"斜体の大きな数字","doc":"太い長体の斜体の数字（Anton）、斜め後ろに白抜きの影、右側の弧が一拍ごとに開き、colors で色が順番に変わる：スポーツや単色の速いカットの 3-2-1 のオープニングに、common.grade と一緒に。"},
  'common.countdown@flip': {"label":"めくり時計","doc":"パタパタ式のめくり時計：上下二つに分かれたカードに数字（カードは ink、数字は color）、一拍ごとに上半分が下へめくれて次の数字が出る：レトロ、オープンまでのカウントダウン、年越し、発表会、「あと何日」に。"},
  'common.countdown@leader': {"label":"古い映画の頭","doc":"古い映画の頭のカウントダウン：円盤（color）、十字の線、一拍ごとに一回転する針、真ん中に数字（ink）、少しちらつき、ほこりが付く、既定は白黒：レトロなオープニング、懐かしさ、ホームビデオ、「映画が始まる」に。"},
  'common.wipe#iris-close': {"label":"アイリスクローズ","doc":"段落の終わり、アニメ風の場面転換に：画面が円になって中央の一点まで閉じ、同じ点からまた開いて新しい画面になる。昔のアニメの締めのように。"},
  'common.wipe#blinds-turn': {"label":"ブラインド","doc":"ビジネス、プレゼン風の場面転換に：やや細い 12 枚の横板が上から 1 枚ずつ回って閉じ、同じ向きに回って開く。"},
  'common.wipe#ink-spread': {"label":"墨のにじみ","doc":"文化、水墨、お茶や本の場面転換に：いくつもの墨が画面のあちこちでにじんで一つになり、吸い取られるように引いていく。"},
  'common.wipe#stripes-pop': {"label":"カラーストライプ","doc":"トレンド、コーデ、ドーパミンカラーの段落替えに：4 色の斜めの帯が次々と掃いて画面を覆い、また 1 本ずつ掃き出ていく。"},
  'common.wipe#tiles-collage': {"label":"コラージュタイル","doc":"コラージュ、手帳、写真の壁のページ替えに：画面を 6 × 10 の小さなマスに分け、1 枚ずつ覆ってから 1 枚ずつめくる。"},
  'common.wipe#band-steep': {"label":"急角度の帯","doc":"スポーツ、ニュース速報の場面転換に：とても斜めの色帯が右から左へ掃く。"},
  'common.wipe@band': {"label":"斜め色帯","doc":"斜めに切れた色帯が左から右へ掃き（dir で逆向きも可）、アイテムのちょうど真ん中の瞬間に画面全体を覆い、先端に細い線が付く。ふだんの場面転換やレイアウトの切り替えに。color は色帯、edge は線の色、line は太さ。"},
  'common.wipe@hand': {"label":"手でふさぐ","doc":"暗くぼやけた手のひらのシルエットが残像を引きながら右下から迫り、アイテムの真ん中でレンズを完全にふさぎ、左下へ滑って離れる。場面転換、振り向き、撮られたくないときに。hand は手の色。"},
  'common.wipe@curl': {"label":"ページめくり","doc":"ページめくり：アイテムは切り替え点から始まり、最初は古いページが画面を覆う——color 色の紙、または前のショットの静止画（source／t／crop、win または画面全体に置く）に、artAt で止めたブロックを重ねたもの（art／artParams、例えば common.magazine のページ。静止画はその映像枠に入る）——それが angle の向きにめくれていく：折り目が画面を横切り、めくれた部分は鏡像の裏面（back 色、折り目のそばの光沢、表の印刷がうっすら透ける）で影を落とし、新しいページの折り目のそばに影の帯ができる。雑誌のページめくり、ノートのめくり、章の切り替えに、common.whoosh と組み合わせる。rev で逆再生（ページがかぶさる、雑誌を閉じる）。"},
  'common.wipe@tiles': {"label":"マスのコラージュ","doc":"画面を cols × rows に切り、紙色（color、二段階の濃さ）のマスが一枚ずつ閉じて真ん中で全部覆い、また一枚ずつ開く。マスの間は edge 色の細い継ぎ目。スクラップブック、コラージュ、写真の壁のページ替えに、common.slide と組み合わせる。その後も継ぎ目を残すなら common.scraps の grid。"},
  'common.wipe@vortex': {"label":"文字の渦","doc":"color と edge が交互の文字の輪（words）、隣り合う輪は逆回転、全体がゆっくり拡大し、両端 0.12 秒でフェード、その間は画面を覆う。都市・ストリート・文字のフレームの章替えに、common.monoframe と一緒に。"},
  'common.wipe@stripes': {"label":"多色ストライプ","doc":"何色かの斜めの帯が一本ずつ横切り、項目のちょうど真ん中で最後の一本が画面を覆い、また一本ずつ抜けて新しい画面を見せる。ドーパミンカラーのセクション切り替えに（最後の色を新しいセクションの地の色に、common.backdrop の words と）。colors は色（カンマ区切り）、dir left で右から入る。"},
  'common.wipe@iris': {"label":"アイリス","doc":"映像が円になり、color が外側から閉じてきて、アイテムの中央で (x, y) の一点まで閉じて画面全体を覆い、同じ点から開いて新しい映像になる。円の縁に edge 色の細い輪（太さは line）。昔の映画、サイレント映画、アニメの終わりと始まり、一人や一つの物に注目させるときに（x, y をそこに置く）。"},
  'common.wipe@blinds': {"label":"ブラインド","doc":"画面を rows 枚の横の羽根に分け、上から一枚ずつ回って閉じ（回るときに明暗がつく）、中央で全部閉じて画面を覆い、同じ向きに回り続けて開く。家、室内、朝、のぞき見、サスペンスの場面転換に。"},
  'common.wipe@ink': {"label":"インクのにじみ","doc":"縁が少し不規則な color 色のインクのしみ（飛び散った小さな点つき）が画面のあちこちで広がって一つになり、中央で覆い尽くし、別のいくつかの点から吸い取られるように引いて新しい映像が現れる。水墨、書道、手作り、アート、文学的な場面転換に。seed でしみの位置が変わる。"},
  'common.rolldoor#shop-close': {"label":"閉店","doc":"動画の終わり、今日の仕事納めに：画面全体のシャッターが 0.2 秒からゆっくり下り（0.8 秒で下まで）、「本日閉店」の札が貼られる。"},
  'common.rolldoor#shop-open': {"label":"開店","doc":"オープニング、お店の開店に：最初はシャッターが閉まって「營業中」（営業中）の札が貼られ、0.2 秒から上へ巻き上がって画面が見える。"},
  'common.backdrop#halftone-pop': {"label":"ポップな網点","doc":"ポップアート、マンガ、スポーツ感の背景に：halftone だけより細かく濃い網点。左下が最大で右上へ小さくなる。"},
  'common.backdrop#sunburst-show': {"label":"バラエティの放射","doc":"抽選、発表、バラエティ番組風の背景に：中心から放射する幅広の 2 色の光線がゆっくり回る。"},
  'common.backdrop#waves-summer': {"label":"夏の波","doc":"海辺、夏、ゆったりした段落の背景に：大きめの 4 層の波の帯が下から重なり、それぞれの速さで横へ流れる。"},
  'common.backdrop#spot-quote': {"label":"名言スポット","doc":"名言、インタビュー、ポッドキャストの背景に：黒に近い青灰色の地に、上端から濃いめのやわらかい光が差し、下と四隅が暗くなる。"},
  'common.backdrop#dots-party': {"label":"パーティードット","doc":"かわいい、お祝い、子ども向けの背景に：大きめで濃い水玉がゆっくり流れ、両側に小さな飾りがきらめく。"},
  'common.backdrop@gingham': {"label":"ギンガムチェック","doc":"color2 の太い帯が縦横に重なるギンガムチェック（濃さ tint、マスの大きさ scale）。かわいい、家庭的、手作り感のある段落の背景に。"},
  'common.backdrop@dots': {"label":"水玉","doc":"きれいに並んだ color2 の小さな水玉（濃さ tint、間隔 scale）。かわいい、お祝い、子ども向けの背景に。"},
  'common.backdrop@stripes': {"label":"ストライプ","doc":"45 度の color2 の斜めストライプで、1 本おきに色がつく（濃さ tint、1 組の幅 scale）。にぎやかでリズムのある段落の背景に。"},
  'common.backdrop@grid': {"label":"方眼","doc":"color2 の細い線で描いた方眼紙（濃さ tint、マスの大きさ scale）。解説、ノート、情報っぽい背景に。"},
  'common.backdrop@solid': {"label":"無地","doc":"地の色 color だけの無地で、柄はない。すっきりした地がほしいとき、glow、pool、bits だけを使いたいときに。"},
  'common.backdrop@gradient': {"label":"グラデーション","doc":"上の color から下の color2 へ斜めに変わるグラデーションで、柄はない。やわらかくすっきりした冒頭、エンドカード、パネルの背景に。"},
  'common.backdrop@diamond': {"label":"ひし形","doc":"レジ横のすべり止めマットのひし形模様（color2 の細い斜線の交差）。pool は暖かい光の輪、vignette は四隅を暗くする。暗いレジ台や作業台に。"},
  'common.backdrop@spot': {"label":"スポット","doc":"暗いポスター地で、上端から柔らかい光が落ち（color2、濃さ tint）、下へ向かって暗くなる。名言、インタビュー、ポッドキャストに。"},
  'common.backdrop@words': {"label":"文字の壁","doc":"ドーパミンの文字の壁：word をページいっぱいに一列ずつ繰り返す（color2 色・濃さ tint の太いセリフの袋文字、列の高さ scale）、隣の列は drift で逆向きに流れる。セクションごとに色を変える（ライム、コバルト、ショッキングピンク、オレンジ）。common.popcard、common.sticker、タイトルテンプレート pop と。"},
  'common.backdrop@halftone': {"label":"網点","doc":"網点：45 度に並ぶ丸（color2、濃さ tint、間隔 scale）が左下でいちばん大きく、右上へ小さくなって消える。ポップアート、マンガ、レトロな印刷、スポーティーな地に。"},
  'common.backdrop@sunburst': {"label":"放射光","doc":"画面の中心から放射する二色の光線（color2、濃さ tint）がゆっくり回る。抽選、発表、セール、レトロなポスター、バラエティに。scale が大きいほど光線が少なく太い。drift は回る速さで 0.1 度／秒単位、drift を入れないと回らない、40 がちょうどいい。"},
  'common.backdrop@waves': {"label":"波","doc":"下から重なる四層の波の帯（color2、下ほど濃い）が、それぞれの速さで横へ流れる。海辺、夏、のんびり、さわやか、音楽に。scale は波の大きさ。drift を入れないと動かない、40 がちょうどいい。"},
  'common.shader#neuro-tech': {"label":"テックな網","doc":"テック、AI、データの段落の背景に：暗い地に光る細い線の網が、look neuro だけよりゆっくり流れる。"},
  'common.shader#cells-glass': {"label":"ステンドグラス","doc":"手作り、ステンドグラス、アートの背景に：look cells だけよりいびつな色のセルが、ゆっくりうごめく。"},
  'common.shader#dither-retro': {"label":"レトロなドット","doc":"レトロゲーム、電子音楽の背景に：大きめの網点で描く大きく流れる模様。昔のパソコンの単色画面のように。"},
  'common.shader#smoke-slow': {"label":"静かな煙","doc":"ブランド、落ち着いた段落の背景に：煙の輪を画面からはみ出すほど大きくし、中央の暗がりのまわりを煙が画面いっぱいに覆う。look smoke だけより穏やかに、ゆっくり漂う。"},
  'common.shader#rays-stage': {"label":"ステージの光線","doc":"ステージ、発表、授賞式の背景に：上から差し込む、look rays だけより強い光線。"},
  'common.shader@mesh': {"label":"流れるグラデーション","doc":"いくつかの色が絵の具のようにゆっくり流れ、にじみ合うやわらかなグラデーション。冒頭、エンドカード、ブランドらしい背景に。amount を上げるほど大きくゆがみ、grain で粒子を重ねる。"},
  'common.shader@grain': {"label":"ざらついたグラデーション","doc":"back 色の地の隅から、粗い粒子のついた色のグラデーションが湧き出し、ゆっくり形を変える。質感のある冒頭、素材のない区間に。grain を 0 にするとこの look 自身の粒子量 0.25。"},
  'common.shader@rays': {"label":"光線","doc":"back 色の地に、上の一点から光の筋が放射状に差し込み、光がにじむ。ステージ、発表、授賞式の背景に。"},
  'common.shader@smoke': {"label":"煙の輪","doc":"back 色の地の中央に色のついた煙が輪になり、ふちから細く漂い出る。ブランド、落ち着いた段落の背景に。"},
  'common.shader@warp': {"label":"ゆがむ格子","doc":"格子がねじれ、引き伸ばされて、大理石のように流れる色の塊になり画面いっぱいに広がる（back は使わない）。にぎやかでサイケデリックな冒頭や段落の背景に。"},
  'common.shader@swirl': {"label":"渦","doc":"いくつかの色と back 色の太い帯が中心から回りながら広がる渦。レトロでサイケデリックな冒頭に。grain を 0 にするとこの look 自身の粒子量 0.2。"},
  'common.shader@blobs': {"label":"流体の玉","doc":"back 色の地で、いくつかの色の流体の玉が溶け合い、ゆっくり形を変える。シンプルな冒頭、エンドカードに。amount を上げるほど玉が増える。"},
  'common.shader@dots': {"label":"点の軌道","doc":"back 色の地を色とりどりの小さな点が埋め、それぞれの軌道を回る。にぎやかでパーティーのような段落の背景に。amount を上げるほど広く散らばる。"},
  'common.shader@neuro': {"label":"光る神経網","doc":"暗い地に光る細い線の網が流れ、線の交わるところが特に明るい。テック、AI、ニューラルネットワーク、深夜、サスペンスの冒頭や段落の背景に。最初の色が線、最後の色が光る点で、amount を上げると交点が明るくなる。"},
  'common.shader@cells': {"label":"細胞のマス","doc":"細胞やステンドグラスのような不規則な色のマスがゆっくりうごめき、マスの間に back 色の細いすき間がある。自然、生物、コラージュ、にぎやかな情報の背景に。amount を上げるとマスがいびつになり、grain は各マスに内向きの影をつける。"},
  'common.shader@dither': {"label":"レトロな網点","doc":"レトロな網点：最初の色と back の 2 色だけで、規則正しく並んだ点が流れるゆがみ模様を描く。古いパソコンや携帯ゲーム機の 1 ビット画面のよう。レトロ、ピクセル、ゲーム、ハッカー、Lo-fi に。amount は点の大きさ。"},
  'core.flash#bloom-pop': {"label":"光のフラッシュ","doc":"強拍、写真のフラッシュに：中心の光がいっきに画面を覆い、0.5 秒で一点に縮んで消える。"},
  'core.flash#fade-in': {"label":"白からフェードイン","doc":"オープニング、思い出から目覚める場面に：最初は画面全体が白く、アイテムの長さをかけて中央の光のかたまりへ引き、それも縮んで画面が現れる。"},
  'core.flash#fade-out': {"label":"黒へフェードアウト","doc":"エンディング、段落の終わりに：アイテムの長さをかけて黒がゆっくり画面を覆い、最後は真っ黒になる。"},
  'core.flash#soft-dip': {"label":"やわらかな光の転換","doc":"やさしい場面転換に：画面が明るくなるだけ（スクリーン）。0.15 秒で明るくなり、少し止まってからゆっくり戻る。"},
  'core.flash@flat': {"label":"全面フラッシュ","doc":"画面全体を均一な色が覆い、カーブどおりに明るくなって引く。撮り直し、場面転換、カメラのシャッターの閃光に。fade と組み合わせれば項目全体のフェードイン・フェードアウトにも。"},
  'core.flash@bloom': {"label":"広がる光","doc":"1 点（x, y）から広がる光で、だんだん大きくなり最後は画面を覆う。トンネルの出口の光、回想、エンディングに。"},
  'core.flash@glow': {"label":"光のかたまり","doc":"（x, y）にとどまる光のかたまりで、大きさ（size）は変わらず明るさだけがカーブどおりに変わり、画面を覆わない。お祝いの金色の光、スポットライトに。blend normal なら明るい映像の上でも見える。"},
  'common.grade#bw-to-color': {"label":"モノクロからカラーへ","doc":"思い出から今へ戻る場面に：最初は全体がモノクロで、0.6 秒でいっきに元の色に戻る。"},
  'common.grade#mono-punch': {"label":"単色で強調","doc":"ある瞬間を強調したいときに：元の色から、0.3 秒で全体が濃い単色（深め）に染まり、0.9 秒で元の色に戻る。"},
  'common.grade#bw-hold': {"label":"ずっとモノクロ","doc":"思い出、ドキュメンタリー、シリアスな場面に：アイテムのあいだずっとモノクロ。"},
  'common.grade#sepia': {"label":"ノスタルジックな茶色","doc":"古い街並み、古い写真、懐かしさに：全体が深めの茶色の単色に染まり、明るいところはベージュ寄り。"},
  'common.tone#golden-hour': {"label":"ゴールデンアワー","doc":"夕焼け、屋台、ノスタルジーに：全体が濃いオレンジゴールドになり、周りは濃い茶色に沈む。"},
  'common.tone#blue-hour': {"label":"ブルーアワー","doc":"夜、雨、静かな・寂しい場面に：全体が青寄りになり、周りは深い紺に沈む。"},
  'common.tone#pink-dream': {"label":"ピンクの夢","doc":"デート、カフェ、スイーツ、思い出に：ピンクの光、周りは深い紫に染まる。"},
  'common.tone#teal': {"label":"ティールの映画調","doc":"海辺、街の夜景、旅に：ティールの光、周りは深い青緑に沈み、映画のカラーグレードのよう。"},
  'common.lens#spot-zoom': {"label":"小さなものを拡大","doc":"画面の小さなもの（値段、看板の文字、手の中の小物）を指す場面に：デフォルトより小さい丸い虫めがね。細い白ふちで、行きすぎてから戻るように現れ、中は 2.5 倍。画面の左下にあるので、x と y をそのものに合わせる。"},
  'common.lens#scan-glass': {"label":"虫めがねでなぞる","doc":"探す、確かめる、じっくり見る場面に：白ふちにガラスの照り返しがある丸い虫めがねが、アイテムの長さをかけて画面を左から右へなぞり、通ったところを 2 倍に拡大する。y をなぞりたい列に合わせる。"},
  'common.lens#censor': {"label":"モザイクで隠す","doc":"見せられないもの（通行人の顔、ナンバープレート、ロゴ）を隠す場面に：いちばん大きなマス目（画面の短辺の 6%）の四角いモザイクがその場にとどまる。出入りの動きはなく、最初から最後まで同じ。x、y、size を隠したいものに合わせる。"},
  'common.lens#pixel-cut': {"label":"ピクセル転換","doc":"話題や段落が変わる場面転換に：画面全体がモザイクになり、マス目が大きくなってからまた小さくなる。アイテムは 0.5〜0.8 秒にして、カットの継ぎ目にまたがせる（半分は前のショットの終わり、半分は次のショットの始まり）。いちばん大きなマス目のときにショットが切り替わる。"},
  'common.lens#heat-haze': {"label":"陽炎","doc":"暑さ、めまい、夢、水の中に：画面全体がゆるやかに揺らぎ、横に寝た波がゆっくり上へ流れる。始まりと終わりはふわっと出入りする。長く置いてもよい。"},
  'common.progress#dog': {"label":"犬のかけっこ","doc":"ペット、散歩、ゆるい Vlog に：小さな犬が画面下端のトラックを右へ跳ねながら走り、通ったところに色がつき、ゴールの旗に着くと旗が弾む。runner を別の絵文字にすれば別のキャラクターになる。"},
  'common.progress#sausage': {"label":"ダックスフント","doc":"ペット、家族、かわいい雰囲気の動画に：画面下端の手描きのダックスフントの胴体が進行バーになり、進むほど伸びる。しっぽを振り続け、ゴールで舌を出す。look を cat か worm にすれば別の動物になる。"},
  'common.progress#paws': {"label":"足あとの列","doc":"ペット、散歩、旅の道中に：12 個の足あとが上端に沿って 1 つずつ押され、左右の足が交互に並び、いちばん新しいものがいちばん明るい。"},
  'common.progress#fuse': {"label":"導火線","doc":"フック短編、サスペンス、カウントダウンに：火花が画面下端のロープを爆弾へ向かって燃えていき、後ろに灰が残り、着くと爆弾が跳ねる。その瞬間に答えを見せる。"},
  'common.progress#battery': {"label":"充電中","doc":"開封、チャレンジ、筋トレ、1 日のお出かけに：左下の電池が 1 マスずつ充電され、横のパーセントが増えていき、満タンになると色が変わって 2 回点滅する。"},
  'common.progress#rocket': {"label":"ロケット打ち上げ","doc":"発表、成長、チャレンジ、目標達成に：画面左端のロケット（右端はショート動画アプリのボタンの場所）が炎を引いて下から上へ上り、通った軌道に色がつき、てっぺんの月に着くと月が弾んで花火が上がる。runner を風船にすれば風船が上っていく。"},
  'common.progress#vine': {"label":"花咲くつる","doc":"園芸、料理、成長の記録、親子に：手描きのつるが画面下端に沿って右へ伸び、葉を出しながら進み、終点でつぼみが開いて花になる。goal をいちごにすれば実がなる。"},
  'common.progress#stamps': {"label":"スタンプカード","doc":"チャレンジ、チェックイン、リスト形式の動画に：右下の小さな紙のカードに、章が 1 つ終わるたびに星のスタンプが押され、全部たまるとカードが跳ねてスタンプの色が変わる。dots はマスの数、runner で別のスタンプに。"},
  'common.progress@bar': {"label":"進行バー","doc":"セーフゾーンの上端または下端に沿った細い進行バーで、動画とともに左から右へ埋まる。控えめな進行表示がほしいときに。"},
  'common.progress@dots': {"label":"章の点","doc":"セーフゾーンの上端または下端に沿った章の点の列。着いた点は塗られ、今の点は少し大きい。dots は点の数、icons に絵文字を入れると絵文字の列になる（1 か所に 1 品など）。"},
  'common.progress@tabs': {"label":"章タブ","doc":"セーフゾーンの上端または下端に沿った章タブの列（アイコン＋章名、済んだものはチェック、今の章が点灯して弾む）。labels は章名、icons は章名の前のアイコン。レシピや解説など手順のある動画に。"},
  'common.progress@pencil': {"label":"手書きステップ","doc":"左に手書きのタイトルと赤線、右に「ステップ 3／8」（counterSize で文字サイズ）と手描きの丸の列（今のものは赤く塗り、済んだものはチェック）。レシピや解説を一歩ずつ。"},
  'common.progress@timeline': {"label":"日付のタイムライン","doc":"等間隔の日付（labels）を結ぶ細い線の上を、光る点が from 番目から step 番目の地点へ滑り、線の下に大きな日付と場所（place）を書く。step -1 は線を最後まで引いて「初日 — 最終日」と書く（エンディング）。旅日記を一か所ずつ。"},
  'common.progress@slots': {"label":"番号カード","doc":"番号付きカードの列。点線の空カード（01 02 03）が、その点を話したとき（fills）に実カードになり、メインカラーの色ブロックに番号、横にキーワード（labels）。pulses で後からもう一度跳ねて光る（振り返り）。common.slip の slot で大きなカードがその枠へ飛び込む。3つのルール、3つの理由、リスト型のポッドキャスト切り抜きに。"},
  'common.progress@osd': {"label":"カメラの To-Do","doc":"カメラの OSD 風 To-Do カウンター。VT323 のピクセル文字にビデオテープの赤と青のにじみ、「TO-DO 3/6」（title はカウントの前の文字）の下に四角が並び、fills の秒でチェックが入り（done の色）、チェックした項目（labels）が四角の下に hold 秒タイプされる。全部済むとカウントが点滅。セーフエリアの右端（align left なら左端）。common.camcorder、common.ding と合わせる。レトロなカメラ風 Vlog の 1 日の To-Do に。"},
  'common.progress@runner': {"label":"走るキャラクター","doc":"キャラクター（runner、既定は犬）がトラックの上を右へ跳ねながらゴール（goal、既定は旗）へ走る。どちらも好きな絵文字やプロジェクト内の画像にできる（旅なら飛行機や車、ペットなら犬や猫）。"},
  'common.progress@stretch': {"label":"胴長の犬","doc":"手描きのダックスフントで、胴体が進行バーになってどんどん伸び、しっぽを振り、到着すると舌を出す（look cat は猫、worm はいも虫。毛の色は既定で茶色 #c98a4b、color で変える）。ペット、家族、かわいい雰囲気の動画に。"},
  'common.progress@paws': {"label":"足あと","doc":"足あとが 1 つずつ押される（dots は数、12 がおすすめ。runner で別の絵文字のスタンプに）。ペット、散歩、旅の道中に。"},
  'common.progress@segments': {"label":"区切りバー","doc":"ストーリーズ風の区切りバーで、1 章 1 区切り、今の区切りが少しずつ埋まる（dots は区切りの数、at は各区切りの開始秒）。章に分かれた動画に。"},
  'common.progress@fuse': {"label":"導火線","doc":"火花がロープを伝ってゴール（既定は爆弾）へ燃えていく（color は #ffb300）。カウントダウン、フック、サスペンスに。"},
  'common.progress@battery': {"label":"充電中の電池","doc":"隅の電池が 1 マスずつ充電され、横にパーセントを表示。20% 未満は赤、満タンで done の色になり 2 回点滅（点灯したマスは既定で緑 #34c759、color で変える。align left で左寄せ）。開封、チャレンジ、筋トレ、1 日のお出かけに。"},
  'common.progress@rocket': {"label":"ロケット","doc":"縦向きで、画面の左端か右端にセーフエリアの高さいっぱいに置く。炎を引いたロケットが下から上のゴール（既定は月）まで上り、着くとゴールが弾んで花火が上がる（align left で左端、それ以外は右端。position と y は効かない。runner を風船など上に向かうものに替えられる。画面の端を上から下まで通るので、幅の広い字幕に当たるときは反対側に移すか iconSize を小さくする。縦型ショートでは、アプリのボタンがある右端を避けて左端に置く）：発表、成長、チャレンジ、目標達成に。"},
  'common.progress@ring': {"label":"隅の輪","doc":"隅の輪が少しずつ描かれ、中央にパーセントを表示。満タンで done の色になり軽く弾む（size は大きさ、align left で左寄せ。runner に絵文字を指定するとパーセントの代わりに中央に置く）：どんな動画にも合う。"},
  'common.progress@vine': {"label":"伸びるつる","doc":"手描きのつるが端に沿って右へ伸び、葉を出しながら進み、終点で花が開く（既定は緑のつる #4caf50 とピンクの花びら #ff8fb1。color でつると葉、done で花びらを変える。goal に絵文字を指定すると実るもの、例：いちご）：園芸、料理、成長の記録、親子に。"},
  'common.progress@stamps': {"label":"スタンプカード","doc":"隅の小さな紙のカードに、章が 1 つ終わるたびにスタンプが 1 つ押される（dots はマスの数、6 を超えると 2 段）。全部たまるとカードが跳ね、スタンプが done の色になる（runner で別のスタンプに、例：星。align left で左寄せ）：チャレンジ、チェックイン、リストに。"},
  'common.lens#whip': {"label":"ホイップ","doc":"すばやい場面転換、振り向き、別の方を見る場面に：画面全体が一瞬横に流れて線になり、またくっきり戻る。アイテムは 0.3〜0.5 秒にして、カットの継ぎ目にまたがせ、いちばんぼけたときにショットが切り替わるように置く。"},
  'common.lens@magnify': {"label":"虫めがね","doc":"虫めがね。レンズの中を 1〜2.5 倍に拡大。画面の小さなものを指す場面に。travel で画面をなぞると「探す」感じ。"},
  'common.lens@fisheye': {"label":"魚眼","doc":"魚眼。真ん中がふくらみ、ふちが押しつぶされる。コミカル、大げさ、のぞき込む場面に。"},
  'common.lens@mosaic': {"label":"モザイク","doc":"モザイク。マス目は最大で画面の短辺の 6%。見せられないものを隠す。shape full に enter、exit grow でピクセル化の場面転換。"},
  'common.lens@ripple': {"label":"水面・陽炎","doc":"水面・陽炎。画面が揺らぎ、波がひとつの向きに流れる。暑さ、めまい、夢、水中に。speed が流れる速さ、axis が波の向き。"},
  'common.lens@streak': {"label":"一方向のブラー","doc":"一方向のブラー。横か縦に線のように引き伸ばす。振りパン、すばやい場面転換に。axis が向き。"},
  'common.lens@prism': {"label":"色収差","doc":"色収差。ふちに近いほど赤とシアンが大きく分かれ、真ん中ははっきりしたまま。夢っぽい、ぼんやり、テック感に。"},
  'common.badge@star': {"label":"星形","doc":"黒い縁の黄色い五芒星のバッジ、番号は中央に少し傾けて、プレートは太字の下に蛍光ペンの線（plateColor）。ランキングの何位、リストに。"},
  'common.badge@burst': {"label":"ギザギザ","doc":"爆発ステッカーのように尖った角が一周するバッジ、番号は中央、プレートは星形と同じく蛍光線の字。にぎやかなリスト、何軒目に。"},
  'common.badge@circle': {"label":"丸","doc":"黒い縁の丸いバッジ、番号は中央、プレートも蛍光線の字。落ち着いた区間紹介、何番目のコツに。"},
  'common.badge@box': {"label":"斜めブロック","doc":"少し傾いたフラットなブロック（color の地、textColor の文字、太い斜体。フォントは Playfair Display が雑誌らしい）、タイトル札も同じ色の小さなブロック、x はブロックの左端。ドーパミンカラーのリスト、common.popcard と。"},
  'common.tag@pill': {"label":"カプセル","doc":"小さなカプセル型タグの列（c1、c2、c3 の色を順に使う）が1つずつ弾んで出る。タイトル下の要点の小さな字：認証、種類、価格帯、距離など。"},
  'common.tag@label': {"label":"場所と日付","doc":"四角がつながった場所＋日付のラベル（濃い地に白字、強調色の縁、蛍光色の日付）で、1拍のうちに左から一気に現れる。旅の動画で着いた場所と日付を示すときに。"},
  'common.tag@tape': {"label":"マスキングテープ","doc":"マスキングテープのラベル：タグ1つごとに生成り色の紙テープに手書きで書かれ、文字の下に蛍光ペンの線が伸びる。no は1本目のテープの左に赤ペンで丸く囲む（店や停留所の番号）。テープは少し弾んで貼られる。ノート、手帳、散歩地図に。"},
  'common.tag@pin': {"label":"地図ピン","doc":"ピンのラベル：しずく形の地図ピンが x、y（ピンの先）に落ち、上にラベルカード（1つ目のタグ、2つ目はその下の小さな1行）。check の秒にピンの頭にチェックが入る。地図、行った場所、名所に。"},
  'common.tag@glass': {"label":"すりガラス","doc":"すりガラスのタグが1枚ずつ現れる（step は間隔）。stack で縦に並び、check は各タグが出てから何秒後かにアクセント色のチェックが入る。ブランド映像、チェックリスト、できることに。"},
  'common.tag@day': {"label":"手帳の日付","doc":"手帳の日付ラベル：x、y に破れた紙片、角にマスキングテープ、最初のタグは斜体セリフの大きな字（Day 2、07:30）でペンの下線、2 つ目はその下に手書き（天気、場所）、くるっと回って貼られる。vlog の何日目、一日のタイムライン、旅の日記に。"},
  'common.tag@ember': {"label":"炭火の焼き印","doc":"炭火の焼き印の料理名札：炭色の札が左から滑り込み、左端に c1 色の光るバー、最初のタグの文字が焼きごてのように一文字ずつ押され（c1 色に光ってから紙の色に冷める）、2 つ目のタグはその下の小さな1行。元の大きさは size 3.2（既定の 1.8 はピル向け）。焼肉、炭火焼き、料理名や店名に。"},
  'common.header@chip': {"label":"番号ブロック","doc":"画面上端に色ブロックの番号とタイトル（01 オープニング、Step 2…）、左から滑り込む。ふつうの章や手順に。"},
  'common.header@kicker': {"label":"題の見出し","doc":"区間の間ずっと掲げる題の見出し：上にメインカラーの丸と灰色の小さな字（番組名、kickerSize で字の大きさ）、下に太字の題が左から現れ、【語】 はメインカラーになる。入りきらないときは小さな字が縮み、題は折り返し、どちらも左右のセーフエリアに収まる。この動画が何を問うか：インタビュー、ポッドキャスト、レビューに。"},
  'common.header@slate': {"label":"カチンコ","doc":"隅の小さなラベル：カチンコが落ちてきて拍子木が閉じ、番号とタイトルが書いてある（common.thud と合わせる）。撮影現場らしい章の始まりに。"},
  'common.header@flip': {"label":"パタパタ表示","doc":"隅の小さなラベル：パタパタ式の表示板で番号の各マスが順にめくれて止まり、最後にタイトルの板が開く（common.tick）。旅、出発、次の行き先に。"},
  'common.header@side': {"label":"縦のしおり","doc":"隅の小さなラベル：画面左端の縦長のしおりで、上に色ブロックの番号、タイトルは縦書き（長いと縮み、さらに省略。common.whoosh）。画面の中央をふさがない章の目印に。"},
  'common.header@big': {"label":"大きな番号","doc":"隅の小さなラベル：大きな白抜きの番号が下から現れ、その下半分にタイトルが重なる（common.whoosh）。雑誌の誌面のような章の始まりに。"},
  'common.burst@sticker': {"label":"ギザギザステッカー","doc":"ギザギザの爆発形の中に大きな1語（弾んで入り、少し傾く。points はギザギザの数）。「出発！」「めっちゃうまい」のようなステッカー風の爆発文字。shadow に色を入れると右下にずれた色の影、dots に色を入れると塗りの上に網点（漫画の爆発フキダシ、common.comic と）。"},
  'common.burst@blast': {"label":"画面ごと爆発","doc":"画面全体が弾ける：白いフラッシュ、回転する放射光、脈打つ赤いビネット、二重縁取りの巨大な文字。振り切れ、記録更新、大発表に。"},
  'common.burst@rays': {"label":"放射線の文字","doc":"かじりついた瞬間：(x,y) から細い放射線が一周飛び、大きな文字（サクッ！）が (tx,ty) で大から縮んで弾み、斜めに傾く。かじる、叩く、砕ける、肉汁に。"},
  'common.burst@cloud': {"label":"雲フキダシ","doc":"ふっくらした雲の形の中に大きな1語（fill が塗り、ink が枠線。points はふくらみの数、seed で大きさが変わる）。やわらかく弾んで入り、少し揺れてから止まる。「おいしい」「やった」のようなかわいい、うれしい言葉に。shadow、dots は sticker と同じ。"},
  'common.burst@star': {"label":"星のスタンプ","doc":"角の丸い太った五芒星の中に1語。大きくなりながら4分の1回転して止まる（fill が塗り、ink が枠線。文字は短めに）。評価、勝利、「No.1」「おすすめ」に。shadow、dots は sticker と同じ。"},
  'common.burst@splat': {"label":"ペンキの飛び散り","doc":"fill 色のペンキの飛び散り（形は seed で決まり、枠線なし）に、下へ垂れる数本の筋と飛んだ小さなしぶき。文字は textColor（fill に近すぎると黒か白に自動で切り替え）。小さい状態から一気にぶつかり、しぶきは少し遅れて飛び出す。散らかった、うるさい、「やばい」「ネタバレ」に。"},
  'common.quote@words': {"label":"1語ずつの名言","doc":"動きのある名言：動画が右上の小窓（win）に縮み、左に大きな引用符と話者、その下に話す時間に合わせて1語ずつ行が跳び出す（times、なければ等間隔）。hit の行が拡大して叩きつけられ、全体が一度揺れ、メインカラーの光が走り、前の行は暗くなる。pre は数行を先に暗い予告文字として出し、ghost はその行を先に薄く出す（冒頭の予告）。sizes、serif で行ごとの文字サイズと明朝体。"},
  'common.quote@card': {"label":"締めの名言カード","doc":"不透明な締めの名言カード（bg が地の色）：大きな引用符、数行が1行ずつ浮かび上がり（hit の行はメインカラー、前は灰色）、短い線と出典（who）、一番下に小さな字1行（kicker）。sizes、serif で行ごとの文字サイズと明朝体。"},
  'common.quote@type': {"label":"タイプライター","doc":"タイプライター：名言を左揃えのかたまりにして画面中央へ。1文字ずつ同じ幅のマスで打ち出され（打ち終わりは長さの約6割）、最後の文字の後ろにメインカラーの四角いカーソル、打っている間は点きっぱなし、打ち終わると点滅。【語】（なければ hit の行）はメインカラー、kicker は上、who は打ち終わってから下に出る。y は1行目の上端（-1＝中央）。告白、チャットのような一言、定義に。"},
  'common.quote@block': {"label":"等幅ブロック","doc":"同じ幅に積んだ大きな文字：どの行も同じ幅に拡大縮小し（短い行はとても大きく、長い行は小さく）、隙間なく積んで一つのかたまりに。1行ずつ順に叩きつけられる。【語】（なければ hit の行）はメインカラー、行末の「，。」は外す。kicker は上、who は最後に下。y は1行目の上端（-1＝中央）。宣言、スローガン、冒頭の一言、文字そのものが絵になるときに。"},
  'common.slam@plain': {"label":"縁取り文字","doc":"縁取りの大きな文字（color は文字色、outline は縁、shadow に色を入れるとずれた影）。どんな要点の一言にも。"},
  'common.slam@led': {"label":"LED 看板","doc":"黒い LED 看板で光る赤い文字（ledColor で色を変える）、文字の上に暗い点の格子。止まった本音に。"},
  'common.slam@gold': {"label":"シャンパンゴールド","doc":"斜体セリフの大きな文字をシャンパンゴールドのグラデーションで塗り、暗い柔らかな光彩と、着地の瞬間の暖かい光。歓声、願いごと、名前に。"},
  'common.slam@neon': {"label":"ネオン","doc":"白に近い芯に hl 色の光が幾重にも重なるネオン管の文字、【語】はもう一本のシアンの管。行ごとに何度か瞬いてから点き、そのあとはやさしく明滅する（弾まない、揺れない。stagger で行ごとに順に点く）。夜景、バー、街、「営業中」に。"},
  'common.slam@extrude': {"label":"立体ブロック","doc":"レトロな立体ブロック文字：color の面、細い outline の縁、右下へ何層も重ねた硬い影（shadow に色を入れると側面の色になる）。タイトル、バラエティ番組のノリ、大きな宣言に。"},
  'common.slam@box': {"label":"色ブロック","doc":"行ごとに outline 色のベタのブロックにのせ、左右交互に少し傾け、両側から一行ずつ順に滑り込む（stagger で間隔、shadow でブロックにずれた影）。雑誌の切り抜きラベル風。主張の列挙、手順、ごちゃごちゃした映像の上の強い一言に。"},
  'common.slam@split': {"label":"版ずれ","doc":"color の文字の後ろに二枚の色版（hl とシアン）がずれて重なり、着地のとき約 0.3 秒暴れてから小さなずれで止まる。テック、グリッチ、エラー、「え、なに？」に。"},
  'common.strike@marker': {"label":"マーカー2筆","doc":"太いマーカーの線2本が左から斜めに行を横切る（2本目のほうが急）。どんな「実はちがう」にも。"},
  'common.strike@scribble': {"label":"ぐしゃぐしゃ","doc":"行全体を左から約 0.3 秒で塗りつぶす、細かく行き来するギザギザの殴り書き。怒って消す、言い間違い、前言撤回に。"},
  'common.strike@cross': {"label":"大きなバツ","doc":"少し震えた手描きの2筆で、行の上に角から角へ大きなバツ。まちがい、NG、絶対やっちゃダメに。"},
  'common.strike@bar': {"label":"黒塗り","doc":"accent 色のベタの帯が左から行をなぞって覆い隠す、機密文書の黒塗りのように。言えないこと、検閲、中止になった計画に。"},
  'common.onomatopoeia#whoosh-pass': {"label":"ビューンと通過","doc":"何かが飛んでいく、場面転換、時間が進む：画面下半分に斜めの文字が左から飛び込み、残像とスピード線を引く。"},
  'common.onomatopoeia#zzz': {"label":"寝落ち","doc":"寝落ち、ぼんやり、退屈：右上に Z が三つ、ひとつずつ高く、ゆっくり浮かんで上へ流れる。"},
  'common.onomatopoeia#thud-column': {"label":"縦のドドド","doc":"足音、ノック、嫌な予感：画面右に縦に並ぶ黒い三文字、ひとつずつ落ちて左右にずれ、ゴロゴロ揺れる。"},
  'common.onomatopoeia#pow': {"label":"POW","doc":"命中、衝突、ツッコミの一撃：画面中央のとても大きなアメコミ文字、網点と硬い影、まるごと弾けて出る。"},
  'common.onomatopoeia#scream-wide': {"label":"画面いっぱいの悲鳴","doc":"びっくり、パニック、請求書を見た瞬間：だんだん大きくなる長い文字列が画面中央を横切り、強く震える。"},
  'common.onomatopoeia#tada': {"label":"ジャーン","doc":"お披露目、開封、変身完了：金色の TA-DA! が回りながら開き、まわりで星がまたたく。"},
  'common.onomatopoeia@pop': {"label":"ポンと出る","doc":"色付きの文字に太い黒フチ、一文字ずつ弾んで出て、一文字ごとに左右に少し傾き、止まっている間は小さく震える（depth で黒い立体の影）：笑い声、クンクン、ふつうの擬音。"},
  'common.onomatopoeia@shout': {"label":"叫び","doc":"一文字ごとに大きくなり、巨大なところから叩きつけられる。黒フチの外に color2 のフチと立体の影、ずっと強く震える：大声、ドーン、悲鳴、びっくり。"},
  'common.onomatopoeia@tremble': {"label":"ブルブル","doc":"color2 の細フチ文字の左右に color の残像、どの文字も休まず震えて傾く：寒い、怖い、緊張、スマホの振動。"},
  'common.onomatopoeia@whisper': {"label":"ひそひそ","doc":"color2（白）のフチのない細い文字、字間は広く、まわりに ink 色のやわらかい影。一文字ずつゆっくり浮かんで上へ流れる：シーン…、Zzz、気まずい間、心の声。"},
  'common.onomatopoeia@zoom': {"label":"ビューン","doc":"前に傾いた文字が左から飛び込み、color の残像と color2 のスピード線を引く：ビューン、サッ、ダッシュ、通り過ぎるもの。"},
  'common.onomatopoeia@rumble': {"label":"ゴゴゴ","doc":"ink 色の黒い文字に color の細フチと光、上から落ちてつぶれて戻り、そのあと重くゴロゴロ揺れる：雷、ドスン、地震、威圧感。"},
  'common.onomatopoeia@sparkle': {"label":"キラキラ","doc":"上の color2 から color へのグラデーション文字、白フチの外に細い墨の線とやわらかい光、回りながら開き、まわりで四角い星がまたたく：キラキラ、登場、完成、きれい。"},
  'common.onomatopoeia@bubble': {"label":"ぷにぷに","doc":"丸い文字に厚い color2 のフチ、ゼリーのように次々と跳ね、上がるときは伸びて落ちるとつぶれる：チュッ、ポン、もぐもぐ、やわらかい・かわいいもの。"},
  'common.onomatopoeia@halftone': {"label":"網点","doc":"アメコミ風の文字：color の上に color2 の網点、太い黒フチ、右下にずれた硬い影、単語全体が一度に弾けて出る：ドン、POW、BAM、命中、衝突。"},
  'common.handwrite@pen': {"label":"万年筆","doc":"細いインク色の万年筆の文字が1文字ずつ書かれ、後ろに note の紙色のグローがあるので動画の上でも読みやすい。字幕、ポストカード、日記、手帳に。"},
  'common.handwrite@chalk': {"label":"チョーク","doc":"ざらざらで粒っぽく、濃さが少しむらのあるチョークの文字。note の紙色で書かれ、後ろにうっすら粉が舞う。暗い画面では黒板のよう（paper: note のときメモが color 色の小さな黒板になる）。レシピ、授業、メニューに。"},
  'common.handwrite@marker': {"label":"蛍光ペン","doc":"1行書かれるごとに、少し傾いた半透明で両端がかすれた蛍光ペンの帯がペンのあとを追って引かれ、文字は color のインク色のまま。要点、ノート、勉強 vlog に。hl（蛍光ペンの色）を読むのはこれだけ。"},
  'common.handwrite@crayon': {"label":"クレヨン","doc":"太く、ふちが欠けたロウっぽいクレヨンの文字で、文ごとに次のクレヨンに持ち替える：1文目は color、そのあと青、緑、オレンジ、紫の順（決まったクレヨン色のセット）。子ども、家族、落書き日記に。"},
  'common.dotmatrix@still': {"label":"静止","doc":"止まったドット文字、看板は文字の幅で最大 w、入りきらないときはドットが縮む。看板、LED ボードに。"},
  'common.dotmatrix@marquee': {"label":"電光掲示","doc":"幅 w の看板の中を右から左へ流れ続ける電光掲示（speed は速さ）。電光掲示、LED ボードに。"},
  'common.dotmatrix@type': {"label":"1文字ずつ","doc":"1文字ずつ打ち出す（typeDur は打ち終わるまでの時間）。look print と合わせるとレシートが印字されるよう。レシート、呼び出し機に。"},
  'common.headline@doc': {"label":"ドキュメンタリー","doc":"ドキュメンタリー風のタイトルカード：明朝体の大きな文字（複数行可）と 1 行の小さな文字、上下 2 本の細線が中央から伸び、カード全体が浮かび上がって最後にフェードアウト。bg band は文字の後ろに暗い帯、black は画面全体を黒に（重い字幕カード、章、年代、地名）、none は文字と影だけ。type で 1 文字ずつ打ち出す。enter roll は一文字ずつ生地を伸ばすように細い形から元の幅へ広がる。strikeFrom＋strikeAt でその時間にその文字以降へ細い線を引き、文字が薄れる（「〇〇不使用」「前はこう思っていた」）。歴史、ドキュメンタリー、エッセイ、旅、ブランド動画の章の始まりに。"},
  'common.headline@brand': {"label":"ブランドの一文","doc":"ブランド映像の文字：左下に1行ずつぼかしからくっきり現れ、小さな字（sub）は上の小見出しになる。y は最後の行のベースライン（-1 はセーフエリアの下端）。ブランド映像の一文、私たちがすること。"},
  'common.headline@proof': {"label":"数字の証明","doc":"ブランド映像の証明：左に数え上がる大きな数字（text、例えば 90+）、小さな字（sub）はその下の字間の広いラベル。text が数字でないときは brand の大きさで1行ずつぼかしから現れる。ブランド映像でやってきた量を見せるときに。"},
  'common.headline@name': {"label":"名前タイトル","doc":"斜体セリフの大きな名前（text。漢字・かな・ハングルは斜体にせず立てたまま）が一文字ずつ浮かび、光が一度走り、その下に中央の小さな点から金の線が左右へ伸び、字間の広い一行（sub、例えば SWEET SIXTEEN）。誕生日・結婚式・卒業の名前タイトルに。"},
  'common.stamp@box': {"label":"四角スタンプ","doc":"四角い枠と太字のスタンプが一度大きくなってから落ち、少し傾いて押される。一、二語の判定に。"},
  'common.stamp@circle': {"label":"丸スタンプ","doc":"二重丸のスタンプ。文字より少し大きい二重の輪の真ん中に字があり、box と同じように落ちてくる。本物の印らしく見せたい判定やおすすめに。"},
  'common.stamp@card': {"label":"主張カード","doc":"ステッカー風の主張カード：メインカラーのべた塗りカードに白い太字（2行まで、【語】 は hl 色）、黒枠とくっきりした影、横に小さなタグ（tag）、1.35倍から弾んで落ちる。anchor でカードの上端または下端を y に合わせる。対談や討論での一人の主張、要点の一言。"},
  'common.stamp@double': {"label":"判決の印","doc":"判決の大きな印：二重線の角丸枠、半透明の紙色の地（paper）、柔らかい影。box と同じように落ちてくる。判決、却下、結審、認定。"},
  'common.stamp@ember': {"label":"焼き印","doc":"焼き印の結論：炭色の角丸の札（ink）にかすかな斜線と color の内枠、斜体セリフの大きな字が 1.45 倍から落ちてきて、焼きごてのように color に光り 1 秒で paper 色に冷める。焼肉、グリル、おいしい、結論。"},
  'common.pen@circle': {"label":"丸囲み","doc":"手描きの丸でものを囲み、終わりが少し行き過ぎる。画面の要点や商品を囲むのに。"},
  'common.pen@arrow': {"label":"矢印","doc":"左下から右上へ曲線を引き、最後に矢じりを足す。画面の中の何かを指すのに。"},
  'common.pen@underline': {"label":"波線","doc":"上下に揺れる波線の下線（h は小さめ、例えば 0.04）。文字や商品の下に引いて強調。"},
  'common.pen@check': {"label":"チェック","doc":"チェックマーク。できた、正解、リストの一項目が完了。"},
  'common.pen@cross': {"label":"バツ","doc":"2 画のバツ。間違い、これはダメ。"},
  'common.pen@heart': {"label":"ハート","doc":"ハート。filled のときはペンの色で塗る。好き、おすすめ。"},
  'common.pen@star': {"label":"星","doc":"五角の星。filled のときは fill の色で塗る。要点、お気に入り。"},
  'common.pen@stars': {"label":"星がはじける","doc":"小さな星とハートが輪になって真ん中からはじけ、揺れながら少しふくらんだり縮んだりする。サプライズ、かわいい、うれしい。"},
  'common.pen@burst': {"label":"とげの光輪","doc":"とげとげの光輪。描き終わると少し広がる。強調、「これすごい」。"},
  'common.pen@rays': {"label":"驚き線","doc":"上に扇形に並ぶ 5 本の短い線。マンガで頭の上に出る驚き線。驚き、発見。"},
  'common.pen@steam': {"label":"湯気","doc":"くねった湯気が 3 本、上へ立ちのぼっては消える。できたての温かい料理。"},
  'common.pen@clock': {"label":"時計","doc":"塗りのある目覚まし時計（上に小さなベル 2 つ）、針が回る。時間、待ち時間、どれだけかかったか。"},
  'common.pen@house': {"label":"家","doc":"小さな家（屋根、煙突、ドア、窓）。描き終わると煙突から小さなハートが漂う。家、帰宅、住まい。"},
  'common.pen@snow': {"label":"雪の結晶","doc":"六角の雪の結晶がゆっくり回る。寒さ、冬、冷たいもの。"},
  'common.pen@diamond': {"label":"ダイヤ","doc":"fill の色で塗ったダイヤ。横で十字の光が 2 つきらめく。貴重、高級。"},
  'common.pen@qmark': {"label":"はてな","doc":"手書きのはてなマーク。疑問、「なんで？」。"},
  'common.pen@thumb': {"label":"いいね","doc":"fill の色で塗ったいいねの手。おすすめ、高評価。"},
  'common.pen@trace': {"label":"形のトレース","doc":"カットをまたぐ形の線：カット前のショットで形をなぞり（from、画面比率の座標の点）、cut 秒でカットをまたいで、morph 秒のうちに次のショットの同じ形（to）へ変形し、重なった瞬間に光る（style、x、y、w、h は使わない）。マッチカット、形のリレー。"},
  'common.emoji@sticker': {"label":"ステッカー","doc":"大きな絵文字ステッカーが (x, y) で弾んで現れて揺れる。感情や笑いどころのリアクション。"},
  'common.emoji@rain': {"label":"絵文字の雨","doc":"絵文字の雨が上から降る。全画面（check はセーフゾーンからはみ出すとは見なさない）、count は数。お祝い、食いしん坊感。"},
  'common.emoji@float': {"label":"上へ流れる","doc":"ハートと絵文字が x、y から揺れながら上へ流れていく。rate は1秒に何個。ライブ配信や SNS のリアクション。"},
  'common.emoji@tap': {"label":"ダブルタップ","doc":"ダブルタップの大きなハートが x、y で弾み、小さなハートが輪になって飛び散ってから上へ消えていく。いいね。"},
  'common.emoji@cover': {"label":"顔隠し","doc":"顔を隠す大きな絵文字：最初のフレームから最後まで原寸・不透明で動かない。follow: face と組むとあごから髪の生え際まで隠れる大きさに自動で広がる。path は「秒|x|y|大きさ」の行どおりに動かし、box は 1 つの枠の中だけに描き（雑誌ページの映像の枠）、backing は後ろに同じ色の円を敷いて花びらのすき間を埋める。顔を出さない人に。"},
  'common.callout@circle': {"label":"手描きの丸","doc":"目標を手描きの丸で囲む（color の色）。食材や見てほしい一品を指すのに。"},
  'common.callout@cross': {"label":"バツ","doc":"目標に大きなバツ（bad の色）。ダメ、間違ったやり方。"},
  'common.callout@ban': {"label":"禁止","doc":"禁止アイコン：丸に斜線（bad の色）、中に電話（icon phone）や任意の絵文字。「電話注文不可」のようにできないこと。"},
  'common.callout@burst': {"label":"肉汁の放射線","doc":"目標の周りから外へ飛び出す肉汁の放射線（color の色）。かぶりつくと肉汁があふれる一口。"},
  'common.touch@dot': {"label":"グレーの点","doc":"スマホのシステムの半透明グレーの点（edge はその枠）。スマホ操作の画面録画。"},
  'common.touch@glow': {"label":"光る指先","doc":"白く光る指先。指をもっと目立たせたい画面録画。"},
  'common.touch@cursor': {"label":"マウスカーソル","doc":"パソコンの矢印カーソル。ずっと画面にあり、ジェスチャーの間をすべって移動し、tap はクリック：カーソルが縮んで輪が広がる。color は塗り、edge は枠。common.desktop のレトロなデスクトップと組み合わせる。"},
  'common.sticker@heart': {"label":"ハート","doc":"ぷっくりしたハートのステッカー（color で塗る）。好きなもの、おすすめの横に。"},
  'common.sticker@bolt': {"label":"稲妻","doc":"斜めの稲妻のステッカー。要点、サプライズ、勢いのあるタイトルの横に。"},
  'common.sticker@star': {"label":"星","doc":"五角の星のステッカー。見どころ、リストのお気に入り。"},
  'common.sticker@smile': {"label":"スマイル","doc":"丸いスマイルのステッカー（ほっぺと曲がった口）。楽しい、気軽な Vlog。"},
  'common.panel@panel': {"label":"太い枠","doc":"太い枠（角丸、くっきりした影、斜めに貼ったテープ）：border は枠の色、shadow は影のずれ、tapeColor はテープの色。c.panel() のパネルレイアウトの既定の枠で、映像を柄の背景の上に縮めたフック動画に。"},
  'common.panel@print': {"label":"写真の縁","doc":"白い写真用紙の縁、柔らかい影、上端に2本のマスキングテープ：margin は縁の幅、print は用紙の色、tapeColor2 は2本目のテープ。手帳、レシピ。"},
  'common.panel@bezel': {"label":"暗い細枠","doc":"暗い細い枠と深く柔らかい影で、機械や看板に埋め込まれた画面のよう。border は枠の色。"},
  'common.panel@hole': {"label":"枠の外の地","doc":"枠の外を暗い地で塗りつぶし（fill。淡い光、細い斜線）、枠の縁に ring 色の線を一周させる。看板レイアウト、呼び出し機。"},
  'common.panel@offset': {"label":"ずれた色面","doc":"枠がなく、動画窓の後ろでずらした色の塊（block、shadow だけ右下へずれる）が開始時に窓の後ろから滑り出し、印刷のずれのように見える。名言ポスター、インタビュー。"},
  'common.panel@drawn': {"label":"手描きの枠","doc":"手描きの枠：pen でクレヨン crayon／マーカー marker／鉛筆 pencil／ボールペン ballpoint を選び、冒頭の drawIn 秒で一筆ずつ描かれ、線は毎秒 boil 回ゆれ、外側にさらに ring 色の細線（double）、corners の角にマスキングテープのシール。絵本、ノート、落書き風。"},
  'common.camcorder@osd': {"label":"ファインダー表示","doc":"映像の上に重ねるファインダーの表示：左上に ● REC（毎秒点滅）／STBY／STOP／PLAY／PAUSE／FF／REW／PHOTO（status「秒|状態」1 行に 1 つ）、四隅の枠線（popAt で飛び出す）と中央の十字、テープカウンター（counter「秒|表示」で設定し、その後は状態に合わせて進む：録画中 1 倍、ff／rew は spin 倍、それ以外は止まる。counterAt top で右上、bottom で左下）、TAPE 番号（tape「秒|番号」、交換のたびにトラッキングノイズの帯）、電池（battery「秒|目盛り」、0 は赤く点滅）、テープ残量（remain「秒|分」、1 分未満は赤く点滅）、日付スタンプ（date「秒[-秒]|2004-08-14 10:30[|行き先の日付 または 倍速]」、dateFormat で書式）、地名を 1 字ずつ（place「秒-秒|文字」。placeAt top で左上の REC の下、bottom で左下）、W–T ズームバー（zoom「秒-秒|から|まで」）、TAPE END（end「秒-秒」）。撮った映像にずっと重ねて、カメラ越しに見ているように。"},
  'common.camcorder@ff': {"label":"早送り","doc":"早送り：砂嵐 → 青い画面に ▶▶、日付の大きな文字が from から to へめくれる → 砂嵐（snowIn、snowOut は前後の砂嵐の秒数、ffFormat は大きな日付の書式、blue は青い地の色）。時間を飛ばすとき、たとえば数日後。"},
  'common.camcorder@rew': {"label":"巻き戻し","doc":"巻き戻し：stills「素材|秒|x,y,zoom」の静止画が逆順に加速しながら流れ、画面が裂け、中央に ◀◀（素材がなければ描いた代わりの絵）。前の場面に戻る、振り返り。"},
  'common.camcorder@snow': {"label":"砂嵐","doc":"砂嵐だけで画面全体を覆う。テープの交換、二つの録画の間の空白。"},
  'common.magazine@feature': {"label":"中ページ","doc":"中ページ：映像枠の下にゆっくり寄る静止画のコマ（cells「素材|秒|x,y,zoom」、- は描いた見本）、コマの上のタグ（tags「秒|コマ|EN|文字」）、映像の左上に赤地の欄名（kicker）と白い大見出し（headline、settleAt で小さくなる）、コマに重なるプルクオート（quote＋quoteAt。slam で叩きつけ、quoteEn は英語の小さな行、quoteBy は出典）、ページ下の行。特集の本文で、流しながら見出しを付け、一言を引き出す。"},
  'common.magazine@cover': {"label":"表紙","doc":"表紙：特大の斜体の誌名、裁ち落としの大きな映像、赤い帯の大見出しが滑り込む（banner／bannerEn）、下のコマの表紙コピー（lines）、バーコード。オープニング、この号で何を語るか。"},
  'common.magazine@list': {"label":"一覧ページ","doc":"一覧ページ：上に映像、紙の上に欄名と大見出し、番号付きの行が 1 行ずつ入る（items「秒|題名|説明」）。目次、ランキング。"},
  'common.magazine@back': {"label":"裏表紙","doc":"裏表紙：映像を全面に暗く敷き、誌名、締めの大きな文字（headline／deck）、赤い再生ボタン（cta）。エンディングで、完全版がどこにあるかを伝える。"},
  'common.comic@one': {"label":"一コマ","doc":"ページ全体で大きな一コマ。一つのショットで見せる大きな場面に、集中線（focus）と一緒に。"},
  'common.comic@two': {"label":"上下二コマ","doc":"上下二コマ、間のコマ間は右上がりの斜め。行動とその返し、原因と結果の二つのショット。"},
  'common.comic@two-flip': {"label":"逆斜め二コマ","doc":"上下二コマ、コマ間の斜めは two と逆（右下がり）。two のページの次に置き、続くページの斜めが重ならないように。"},
  'common.comic@three': {"label":"上一つ下二つ","doc":"上に大きなコマ一つ、下に小さなコマ二つ、コマ間はどれも少し斜め。メインのショットと二つのリアクションや細部。"},
  'common.comic@four': {"label":"四コマ","doc":"2×2 の四コマ、コマ間は少し斜め。起承転結、リアクションの連続。"},
  'common.comic@side': {"label":"左右二コマ","doc":"左右二コマ、間のコマ間は斜め。横長の動画向け。"},
  'common.grid@two': {"label":"上下二つ","doc":"上下二つのセル（横長の動画では左右）。ビフォーアフター、二つの場所の比較。"},
  'common.grid@three': {"label":"上一つ下二つ","doc":"上に大きなセル一つ、下に小さなセル二つ。メインのショットと二つの細部。"},
  'common.grid@four': {"label":"四つ","doc":"2×2 の四つのセル。四つの場所、四つの物のまとめ。"},
  'common.grid@bento': {"label":"弁当","doc":"大きいセル一つ、小さいセル二つ、横長の帯：上に大きなセル、中ほどに小さなセル二つ、下に横長の帯。主役一つと細部いくつかのまとめ。"},
  'common.grid@six': {"label":"六つ","doc":"2×3 の六つのセル（横長の動画では 3×2）。リスト、複数の場所を一度に。"},
  'common.flatlay@postcard': {"label":"ポストカード","doc":"横長のポストカード、写真の下に白い帯、左に斜体の地名（place）、右に年（year）。裏返す（flipAt）と裏には仕切り線、宛名の線、切手があり、手書き（back）が一文字ずつ書かれ、最後に消印が押される（mark、markAt で押す）。objects で portrait を付けると縦長。旅、行った場所、誰かへの一言。"},
  'common.flatlay@polaroid': {"label":"ポラロイド","doc":"白いインスタント写真、下の広い白縁に手書きの一行（caption）。思い出、あの夏、誕生日。"},
  'common.flatlay@photo': {"label":"写真立て","doc":"縦長の木の写真立て、白いマットが写真を囲み、マットの下に手書きの一行（caption）、厚みあり。古い写真、ある年の記念。"},
  'common.flatlay@tv': {"label":"古いテレビ","doc":"木目の箱の古いテレビ、左の 4:3 の画面でショットを再生、右に二つのつまみとスピーカーの網、画面の下にブランド名（caption）。懐かしさ、昔の録画や番組。"},
  'common.flatlay@card': {"label":"カード","doc":"縦長の紙のカード、上半分が写真、下の広い余白に手書きの一行（caption）。誕生日、お祝い、別れ。"},
  'common.paper@desk': {"label":"クラフト紙の机","doc":"クラフト紙の机（繊維、斑点、ビネット。既定）。わずかに傾いた罫線のインデックスカード（赤い上線と青い罫線、マスキングテープ）、鉛筆の小さな落書き、斜体のサイン1行を足せる。レシピ、手帳、手書き解説に。落書きとサインは既定ではなし：doodles: true で doodleSet の落書きを描く。kitchen（コーヒー豆、泡立て器：レシピ）、journal（星、ハート、うず巻き）、travel（紙飛行機、点線の航跡、小さな太陽）。doodles: false で落書きなし。sign でサインの文字を書く（例えば「Recipe」）、空＝なし。"},
  'common.paper@book': {"label":"絵本のページ","doc":"絵本の中身のページ：まだらな紙目、左に背の影と縫い目、右にページの厚み、ビネット、下にクレヨンの草地の帯。絵本、お話の動画に。paper は紙の色、meadow は草地。"},
  'common.paper@grid': {"label":"方眼ノート","doc":"方眼ノート：方眼、赤い余白線、上端のリング、ビネット。ノート、手書き解説に。cell は方眼、binding はリング。"},
  'common.paper@print': {"label":"雑誌の紙","doc":"雑誌の紙：なめらかなオフホワイト、細かな斑点、淡い繊維、暖色のビネット。雑誌風のレイアウトに。common.magazine の紙。"},
  'common.meter@center': {"label":"中央の数字","doc":"中央の大きな数字、その下に今の段階名と目盛り尺（stages は段階、stagePrefix は段階名の前の字、ruler を切ると尺なし、ticks は尺の目盛り）：深さ、標高、温度、回数のように上がり続けたり下がり続けたりする値に。"},
  'common.meter@band': {"label":"年代尺","doc":"上部に暗い帯、数字は左寄せで単位は小さめ、その下に min から max までの数字入り目盛り尺とその上を滑るマーカー、pins で値の位置に小旗を立てる（accent メインカラー、hl ハイライト色、dashed 破線の白抜きの旗）。数字が旗に届くとその横にラベルが出る：年号、歴史、時代に。"},
  'common.meter@ruler': {"label":"縦の物差し","doc":"右端に立つ物差し：届いた値ごとに矢印と数字が残り、最新のものは大きくメインカラー。同じ値の pin があればそのラベルも付く：身長、高さ、順位に。"},
  'common.chart@bars': {"label":"棒グラフ","doc":"棒が伸び数字が跳ね上がる（dir h 横棒／v 縦棒。compare ratio は「× 6.7」の倍率、gap は差のかっこ、base は基準の点線、stat は大きな数字1行が跳ね上がる）：2〜3 件の数字の比較に。"},
  'common.chart@pie': {"label":"円グラフ","doc":"円グラフが1切れずつ塗られる（note は下に掛けるラベル、colors は各切れの色）：時間やお金など全体の内訳に。"},
  'common.chart@people': {"label":"人型グラフ","doc":"小さな人が1人ずつめくれ、最初の k 人に色が付いて囲まれる（10人中4人。n は総人数、stat が空なら「N 人中 K 人」と書く）：「何人中何人」の割合に。"},
  'common.chart@rank': {"label":"ランキング","doc":"ランキングリストで1行が点灯し「12位」が付く（data の3列目は順位。reveal up は最下位から上へ順に発表し、同順位は一緒に、1位が最後。同じ順位の行には tie の文字を添えた括弧）：ランキング、順位の発表に。"},
  'common.chart@balance': {"label":"天秤","doc":"天秤：両側の分銅が皿に落ち、重いほうへ傾く（note は上の文字、tag は皿の色）：二つのものの重さ比べに。"},
  'common.chart@table': {"label":"対照表","doc":"対照表：線が引かれ、マスが対角線に沿って浮かぶ（data は1行1列「マス|マス|マス」で1行目が見出し、hl は「行,列」）：数軒の店や数種類のものを項目ごとに比べるときに。"},
  'common.chart@line': {"label":"折れ線","doc":"1〜2本の曲線が時間とともに描かれる（再生ヘッド、曲線上のマーカー、基準線。data は1行1本「名称|1,3,2,5」、axis は横軸の両端、marks は曲線上のマーカー、base は基準線、grow は再生ヘッドが全体を進む時間）：時間による変化、推移に。"},
  'common.audiogram@bars': {"label":"対称の棒","doc":"上下対称の棒の列（中央が今、外側ほど少し前）、カバーは波形の上の角丸の四角に正方形に切って置き、count は棒の数（既定 41）：対談、インタビューに。名札は波形の上。"},
  'common.audiogram@wave': {"label":"流れる波形","doc":"直近 1.5 秒の音量が右から左へ流れるなめらかな曲線、カバーは波形の上の角丸の四角に正方形に切って置く：棒より柔らかい画面にしたいポッドキャストに。"},
  'common.audiogram@ring': {"label":"丸いカバー","doc":"丸いカバーの周りに放射状の棒（カバーが声に合わせて少しふくらむ）、カバーは中心に円く切って置き、count は棒の数（既定 72）：番組のカバーや話し手の写真を真ん中に置けるときに。"},
  'common.candles@chart': {"label":"チャート","doc":"黒地に光るローソク足チャートで、カメラが最新の足を追って右へ進み、価格の範囲（対数）もそれに合わせてズームし、画面全体を使う。shocks では赤と水色の残像とズームも付く：動画のメインの画面に。さらに band はチャートの上端と下端（画面の高さに対する割合「0.55,0.86」）、tipX は最新の足の位置。sparks は火花の区間（1 行に「秒-秒」）。markers は目印（1 行に「秒-秒|日付|文字」：金色の点と文字）。refs は参考の点線（1 行に「秒-秒|日付|文字」：前の高値）。brackets は計測の括弧（1 行に「秒-秒|起点の日付」、騰落率を表示）。crashes「高値の日付|安値の日付」と、それを光らせて他を暗くする glow の区間。bolts は稲妻が落ちる秒（「秒@日付」でその日に落ちる）。bursts は花火。grays は白黒になる区間（休場の日）。reds は赤い警戒（周辺減光とウイルスの粒）。hud は警戒の枠（1 行に「秒-秒|文字」）。pillars は白い光の柱（1 行に「秒-秒|日付」）。walls は銘柄のタイルの壁（1 行に「秒-秒|起点の日付|タイトル」。銘柄は wall の横長の CSV「date,AAPL:アップル,MSFT:マイクロソフト,…」で各銘柄の終値。先頭 12 銘柄を傾いた 3D の壁にし、タイルには起点からチャートが描いた日までの騰落率）。"},
  'common.candles@header': {"label":"見出し","doc":"小見出し（label）、動く終値の大きな数字（直近 20 本で上げなら上昇色、下げなら下落色）、日付、右に「高値比 −x%」（vs）か「最高値更新」（high）のラベル。5% を超えて下げると前の高値の日付（prev）を出す：chart の上に置き、同じ keys でその瞬間の価格を示す。"},
  'common.candles@tally': {"label":"暴落カウント","doc":"暴落を数える四角の列（falls は 1 行に「高値の日付|しきい値を割った日付|回復した日付」：割った時点でその四角が下落色に、回復すると上昇色になってチェックが付く。右に「n/総数」、左に tallyLabel、from は数え始める動画の秒）：暴落の振り返りで何回目か、いくつ回復したかを数えるときに。"},
  'common.candles@card': {"label":"出来事カード","doc":"左に色の縦線（color）、分類ラベル（tag）と日付（date）、太字のタイトル（title）、その下に 1 行（sub）。左から滑り込み、タイトルはグリッチで入る：チャートがある日に着いたとき、その日の出来事（金融危機、銀行の破綻）を示すのに。"},
  'common.candles@big': {"label":"大きな文字","doc":"大きな文字ひとつ（text。数字やパーセントは 0 から数え上がる。tone は up 上昇色／down 下落色／white／gold、font は num 細めの数字／text 太いゴシック、size、align は left／center）と、その下の 1 行（sub）：1 日の下落率のように一目で見せたい数字に。"},
  'common.list@check': {"label":"チェック","doc":"各行の頭に ✓ の丸（good の色）：3つの要点、覚えておくことに。"},
  'common.list@pros': {"label":"長所と短所","doc":"各行の頭に + 長所／− 短所、項目の頭に - を付けると短所（長所は good、短所は accent の色）：レビューの長所と短所に。"},
  'common.list@number': {"label":"番号","doc":"各行の頭に 1. 2. 3. の番号の丸：解説の手順、順番にやることに。"},
  'common.notecard@step': {"label":"手順カード","doc":"赤ペンで囲んだ番号（no）、タイトル、1〜2行の説明（text）、「ラベル|内容」の欄（fields）：レシピや解説の1ステップに。"},
  'common.notecard@list': {"label":"チェックリスト","doc":"チェックボックスを1項目ずつチェック。size でリストの字を大きくし、項目が多いか字が大きいと1列か2列に並び、カードが上へ伸びる。tick は ToDo リストのチェック：リストは書き終わっていて、カードが左から滑り込み、tick 番目より前はチェック済みで蛍光ペン付き、tick 番目が今チェックされ蛍光ペンが引かれ、カードはまた滑って出ていく。ticked でチェック済みの項目を指定、strike でチェックした項目を赤ペンで消し、stamp で全部チェックし終わると赤いスタンプを押す。check を切るとリストを書くだけ、out を切るとカードは画面に残る。addInk は + で始まる後から足した項目を別の色で書く：材料リスト、ToDo リストに。"},
  'common.notecard@title': {"label":"料理名カード","doc":"大きな料理名に赤線、サブタイトル（sub）、外国語名（latin）：レシピの冒頭で料理を紹介するときに。"},
  'common.notecard@done': {"label":"完成カード","doc":"「完成！」＋手描きのハート（sub は料理名、latin は外国語名、note は一番下の小さな1行）：できあがりの締めに。"},
  'common.versus@title': {"label":"対決オープニング","doc":"上下の枠にそれぞれ大きな字が叩きつけられ（words、彼が言う／彼女が言う）、中央の字幕帯に VS のひし形が回り込み、両側に名前（names）：冒頭に。dir、top、band、foot は common.duo と同じ値にする。"},
  'common.versus@round': {"label":"ラウンドカード","doc":"画面全体のラウンドカード——両者の色が両側から滑り込んで斜めにぶつかり、ROUND 1（label）が弾み、題（text）が浮かび（【語】 は黄色）、最後に上へ引き抜かれる：各問、各ラウンドの始まりに。"},
  'common.versus@table': {"label":"対照表","doc":"対照表——「a vs b」、2列の名前、1行1問（rows：題|a の答え|b の答え|a の小見出し|b の小見出し、\\n で改行）が1行ずつ滑り込み、最後に視聴者への一言の問いかけ（ask）：締めに。"},
  'common.story@poll': {"label":"投票","doc":"白いステッカーに質問と 2〜4 個の選択肢のバー。投票が入ると各バーが結果まで伸びてパーセントが数え上がり、選ばれたものにチェックが付く。視聴者に「する？しない？」「どっち？」と聞くときに（例：また行きたい？）。質問は text、options は | で区切る、at で投票、votes は結果（例 62,38）、pick にチェック。"},
  'common.story@slider': {"label":"絵文字スライダー","doc":"白いステッカーの質問の下にトラックがあり、絵文字が at から end の間に value（0–1）まで滑る。何かを採点したり、どれだけ好きかを見せたりするときに（例：この海はどれだけ青い？）。emoji はスライダーの絵文字。"},
  'common.story@timer': {"label":"タイマー","doc":"暗いステッカーの mm:ss が at から end の間に from 秒から to 秒まで進む。待ち時間にもカウントダウンにも（例：料理待ち）。icon は内蔵アイコン名か絵文字 1 つ、text は時間の上の小さな字。"},
  'common.album@grid': {"label":"写真グリッド","doc":"グループごとに並ぶ写真のマス（各グループの上に場所と日付、右端の日付の吹き出しが追従）、上にタイトルと右上のボタン、下にタブバー。アルバムをめくる、旅を一日ずつ振り返るときに。「# 場所|日付|吹き出しの文字|レイアウト」でグループ開始（場所が空＝日付だけ；レイアウト L 左に大きく右に 2 枚、R その逆、2 は 2 枚並び、1 は全幅 1 枚、3 は 3 枚ずつの列、空＝枚数で自動、3 枚は L／R 交互；残りは 3 枚ずつ）、scroll「秒|位置|イージング」でスクロール（位置＝グループ番号、0 から、小数可；end で最後；850px で px 指定；out／inOut／linear／back）、日付の吹き出しは bubble（日付と吹き出しの文字）、hide「秒-秒|写真」で開いていくマスを空白に、タイトル title（空＝点灯中のタブ名）と右上のボタン button、タブバー（tabs「アイコン|名前」カンマ区切り、tab 点灯するタブ、-1＝grid は 1 つ目・foryou は 2 つ目）、任意のセグメント（chips、chip）。"},
  'common.album@foryou': {"label":"思い出ページ","doc":"思い出ページ：タイトル、section と more リンク、大きな思い出カード 1 枚（cardTitle 手書き、cardSub）、次の列のタイトル（next）が少し見え、下に grid と同じタブバー。思い出を開き、続けて zoom でカードから動画へ飛ぶときに。カードの画面は source／t／crop（空＝photos の pick 番目）、tapAt で少し縮む、fadeIn で紙色からフェードイン。"},
  'common.album@zoom': {"label":"タップで開く","doc":"写真が zoomFrom から zoomTo へ飛ぶ（tile：pick 番目のマス、位置は項目開始時の scroll；full：全画面、crop はメイントラックのクリップと同じなので本物のクリップに引き継ぐ；fit：全体を黒帯付きで；card：思い出カード）、後ろの黒が追従（全画面＝黒）。アルバムから写真を開いて本物のクリップにつなぐ、またはクリップからアルバムへ戻るときに。move 秒で飛び（ease）、最後に fadeOut。"},
  'common.album@swipe': {"label":"左右スワイプ","doc":"写真を見ながら左へ：今の写真（source か pick 番目）が出て、次（source2 か pick+1 番目）が右から入る。写真を 1 枚ずつめくるときに。fit／fit2 で全体表示（横長は上下に黒帯）。"},
  'common.album@viewer': {"label":"写真ビューア","doc":"写真を見るときの上下のバー——戻る、date、when、action の文字、ツールバー（tools：アイコンをカンマ区切り）——の間にメイントラックのクリップが見える。スマホで 1 枚の写真を見て、ハートを押すときに。heart は heartAt で弾んで heart の色に、show「秒|不透明度」のキー（クリップが流れたら消す）。"},
  'common.search@home': {"label":"トップページ","doc":"メイントラックのクリップをぼかして暗くした上のトップページ：見出し、検索ボックスに 1 文字ずつ入力、下に候補リスト。冒頭で調べたいことを打ち込むときに（例：週末どこ行く）。hint 見出し、query ボックスの文字、候補リスト sugg は 1 行に 1 つ（「前半|補完」か行全体；query と同じ部分は薄く、残りは太字）、pick 何行目を pickAt 秒にタップするとボックスがその行に、out 秒で上へ消える。"},
  'common.search@results': {"label":"検索結果","doc":"検索結果ページ：検索ボックス、タブ、タイトルと要約、中央に角丸の動画窓、その左下から飛び出す事実カード。場所やテーマを紹介し、要点を事実カードで見せるときに。ボックスに入力、erase で先に古い文字を削除；tabs「すべて, ニュース…」の下線が tabFrom から tab へスライド；title、titleSub、snip；動画窓は角丸の穴、メイントラックのクリップは frame: searchWindow(パラメータ, 幅, 高さ)；load 秒まで「検索中…」のカード；facts 1 行に 1 枚「秒|見出し|大きな字|単位」動画窓の左下から飛び出す事実カード；dym もしかして（dymAt、dymHi 何文字目を強調、dymLead 前の文字）；big 動画窓の上の大きな字；related 関連検索「a, b; c」；press 秒に検索ボックスが光る；view full＝動画が全画面、上に検索ボックス・タブ・chips 1 行に 1 つ「秒|字」のフィルターが順に点灯。"},
  'common.search@ask': {"label":"質問の展開","doc":"質問の展開：質問の一覧で、1 問ずつ動画窓に開き、閉じると一覧が 1 行上へ。よくある質問に 1 つずつ答えるときに（答えは完全版まで伏せてもよい）。qs 1 行に 1 問「秒-秒|質問|ヒント」、ヒントに redact＝答えを伏せて reveal。"},
  'common.search@end': {"label":"エンディング","doc":"エンディング：ボックスに再入力して候補をタップ、続いて答えを伏せた強調スニペットと、サムネイルが動画窓の結果カード。最後に完全版へ誘導するときに。snipAt 強調スニペット（snipTitle、snipLead、snipNote）、cardAt 結果カード（badge、title、dur）、press 秒に再生ボタンを押す。"},
  'common.search@bar': {"label":"小さな検索バー","doc":"ページなし：映像の上部に小さな検索バーが留まり（虫眼鏡と query の質問）、press 秒で右端にチェックが飛び出す。話し手がその質問に答える間ずっと残す。typeAt -1＝最初から入力済み、barY は中心の高さ（-1＝上のセーフエリアのすぐ下）、最後の out 秒でフェードアウト、未指定なら 0.3 秒。"},
  'common.window@media': {"label":"クリップ・写真","doc":"ウィンドウの中で自分のクリップか写真を流す。写真や短いクリップを見せるときに（例：パーティーの写真）。source、in、cx・cy・zoom で寄せる、progTo があると写真の下に進捗バー。"},
  'common.window@search': {"label":"検索欄","doc":"ウィンドウの中の検索欄に text を 1 文字ずつ打つ。キーワードを打って次のパートにつなぐときに（例：今日の主役）。typeAt で打ち始める。"},
  'common.window@profile': {"label":"プロフィール","doc":"ウィンドウの中に「名前|値」の一覧が 1 行ずつ出る。人を紹介するときに（名前、年齢、ステータス）。text は 1 行に 1 項目。"},
  'common.window@progress': {"label":"進捗バー","doc":"ウィンドウの中の進捗バーが満タンになり、上の文字が進行中から完了に変わる。準備中から完了までを見せるときに（例：飾り付け中…から飾り付け完了）。text「進行中|完了」、progFrom から progTo で満タン。"},
  'common.outro@cta': {"label":"誘導カード","doc":"エンドの誘導カード：紙色の地に、数行の大きな字が拍に合わせて1行ずつ押され（【語】 はメインカラーの小札に入る）、下に番号付きの点の列（最後の数個ははてな）、手描きの矢印がリンクへ向かって描かれ拍で弾む。本編、プロフィール、コメント、次の回への誘導に。cta は矢印の横の小さな字、tipX、tipY は矢印の先、dots は点の数、hidden は最後のいくつをはてなにするか。"},
  'common.outro@credits': {"label":"クレジット","doc":"最後のお礼のクレジット：lines が 1 拍に 1 行ずつ浮かぶ（*星で囲んだ行* はハイライト色の斜体で漢字・かな・ハングルは立てたまま、_下線で囲んだ行_ は字間の広い小さな字、ほかは太字の名前）、後ろに暗いベール。誕生日・結婚式・卒業の最後に。cover でベールの濃さ、y はリストの中心、冒頭の名前タイトルは common.headline の look name。"},
  'common.outro@episode': {"label":"番組エンドカード","doc":"ink 色の地（cover で濃さ）に、番組名を大きなセリフ体で数行、メインカラーの短い線、中央に再生ボタン付きの角丸 16:9 ウィンドウ（穴：本線クリップの frame は outroWindow(パラメータ, W, H)）、その下に話数（ep）、メインカラーのボタン（cta）、小さなクレジット（credit）が順に浮かぶ。番組（ポッドキャスト、インタビュー、シリーズ）のエンドカードに。y は全体の中心。"},
  'common.echo@stack': {"label":"上下に重ねる","doc":"文字の上下に echoes 層ずつ白抜きが重なり、始めに文字の位置から広がり、外側ほど薄い：ふつうのエコー文字、地名、動作の言葉、章の始まり。"},
  'common.echo@trail': {"label":"残像","doc":"白抜きが文字の後ろに隠れ、一層ごとに右下へずれて薄くなり、始めに文字の下から滑り出る、厚みのある立体の残像：飛び出す、スピード感、重みのあるタイトル；echoes は全部で何層。"},
  'common.echo@zoom': {"label":"波紋","doc":"白抜きが文字と同じ中心で一層ごとに大きく（約 1.25、1.55、1.9 倍）薄くなり、始めに外へ押し広がってからゆっくり呼吸する、文字のまわりの波紋：強調、衝撃、鼓動、この言葉を見て；echoes は全部で何層。"},
  'common.echo@wave': {"label":"ウェーブ","doc":"上下に重なった白抜きが左右に揺れ、一層ごとに少し遅れて外へ伝わる波になり、塗りの文字は動かない：音楽、海、揺れ、ゆったりした場面；echoes は上下それぞれ何層。"},
  'common.band@tape': {"label":"テープ","doc":"color の塗りの帯に ink の文字が左へ流れ、左から現れる：ふつうのリズムの言葉のテープ。"},
  'common.band@caution': {"label":"警告テープ","doc":"少し太い警告テープ：color の地に、上下の縁に沿って ink の斜めのしま模様が文字と一緒に流れ、文字はその間：工事中、注意、危険、期間限定、大ニュース。"},
  'common.band@cross': {"label":"クロス","doc":"二本の帯が X に交差：二本目は逆の角度で色が入れ替わり（ink の帯に color の文字）、文字は右へ流れ、少し遅れて右から現れる：立入禁止、禁止、対立、二つのことがぶつかる、にぎやかなオープニング。"},
  'common.band@outline': {"label":"線だけ","doc":"塗りなし：帯の上下の縁に color の細い線が二本、その間に color の文字、映像がよく見える：隠したくないきれいな映像、軽めのリズムの言葉；ink は使わない。"},
  'combo:impact': {"label":"インパクト","doc":"パンチ、ビンタ、着地、大きな文字を叩きつける瞬間に：中心から線がはじけ、真ん中で光がぱっと広がって縮んで消える。重い打撃音と画面の揺れつき。"},
  'combo:glitchcut': {"label":"グリッチカット","doc":"話題の急な切り替え、何かがおかしくなった瞬間、別の場面への移動に：カットをまたいで走査線と横ずれ、続いて色がずれる。レコードを止める音つき。"},
  'combo:punchline': {"label":"オチ","doc":"ギャグが決まった瞬間、ツッコミ、あきれ顔に：画面が漫画の網点になり、太い集中線が四方から中心へ寄る。びよ〜んというバネの音と小さな揺れつき。"},
  'combo:rewind': {"label":"巻き戻し","doc":"もう一度見返す、さっきに戻る、もう一回：画面がビデオテープになり、トラッキングノイズの帯が下へ流れ、反転した細い帯がちらつく。テープを巻き戻す音つき。"},
  'combo:reveal': {"label":"お披露目","doc":"答えの発表、完成品のお披露目、商品の登場に：虹色の光の帯が左から画面を横切り、真ん中に来たところで光の点が大きな十字の輝きになる。光が走るシャキーンという音つき。"},
  'combo:celebrate': {"label":"お祝い","doc":"目標達成、クリア、受賞、誕生日に：真ん中の少し上にやわらかな金色の光が灯ってゆっくり消え（フラッシュではない）、カラフルな紙吹雪が上から一面に降る。8bit のクリアファンファーレつき。"},
  'combo:leader': {"label":"フィルムリーダー","doc":"本編の始まり、懐かしい雰囲気のオープニングに：映写された 8mm の家庭映画で、昔のリーダーの大きな円盤が 3 から 1 へカウントダウンし、針が 1 秒で 1 周する。カウントごとにカチッ、最後にピッ。"},
  'combo:memory': {"label":"思い出","doc":"回想、昔のこと、あの頃を思い出す場面に：左上に暖かい光がゆっくり灯ってまた消え、画面全体に粗いフィルムの粒子がかかる。小さなチャイムつき。"},
  'combo:rush': {"label":"急げ","doc":"スピードアップ、急ぐ、早送り、ダッシュに：白いスピード線が画面一面を右へ飛び、小さく明るい光が左から横切る。シュッという音と早送りの上がっていく音、小さな揺れつき。"},
  'combo:closing': {"label":"店じまい","doc":"動画の最後専用（最後の 2.4 秒に置き、動画の終わりと同時に終わるように。途中に置くと 2.4 秒後に映像が戻る）。今日の作業終わり、閉店、今日はここまで：画面いっぱいのシャッターがガラガラと下り、ガチャンと閉まって閉店の札が貼られ、そのまま真っ暗にフェードする。"},
  'combo:irisout': {"label":"アイリスアウト","doc":"昔のアニメ風の締めや場面転換に：画面が円に縮んで真ん中の一点まで閉じ、その点から星がはじけて、同じ点から次の画面へ開く。木琴のポンという音つき。"},
  'combo:stage': {"label":"登場","doc":"主役の登場、発表、授賞に：ぼけた舞台の光の玉が上昇音とともに明るくなり、その瞬間、上のほうにとても明るいレンズフレアの光の筋が入る。重い打撃音つき。"},
};
